window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s39-102","number":102,"surah":39,"verses":[68],"references":[{"surah":39,"verses":[68]}],"verseLabel":"الزمر: 68","question":"ما دلالة ﴿ثم نفخ فيه أخرى﴾، وما أثر حذف موصوف ﴿أخرى﴾؟","answer":"﴿أخرى﴾ صفة لمصدر محذوف، أي نفخة أخرى. وحذف الموصوف إيجاز يدل عليه فعل النفخ، وذكر الصفة يبرز مغايرة هذه النفخة للأولى في أثرها: فبعد الصعق يكون القيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص766، تحت عنوان «بلاغة استعمال مفردة ﴿أخرى﴾»","url":""}]},{"id":"s39-103","number":103,"surah":39,"verses":[69,70],"references":[{"surah":39,"verses":[69,70]}],"verseLabel":"الزمر: 69–70","question":"ما الذي تضيفه كلمة ﴿أَشْرَقَتِ﴾ إلى مشهد أرض القيامة؟","answer":"تصور نورًا قويًا منتشرًا يملأ أرض المحشر كلها، لا مجرد ضوء محدود؛ فتفتتح مشهد القضاء بانكشاف تام يليق بظهور الحق والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص774–775، تحت عنوان «بلاغة استعمال مفردة الإشراق»","url":""}]},{"id":"s39-142","number":142,"surah":39,"verses":[69,70],"references":[{"surah":39,"verses":[69,70]}],"verseLabel":"الزمر: 69–70","question":"لماذا رُتبت أحداث القضاء من وضع الكتاب إلى مجيء النبيين والشهداء ثم الحكم؟","answer":"ليجري المشهد على ترتيب المحاكمة الكاملة: تُعرض السجلات، وتقام الشهادة، ثم يصدر الحكم بالحق؛ فيظهر أن الجزاء قائم على حجة ظاهرة وعدل تام.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص784، تحت عنوان «براعة ترتيب الأحداث في مشهد القضاء»","url":""}]},{"id":"s39-143","number":143,"surah":39,"verses":[69,70],"references":[{"surah":39,"verses":[69,70]}],"verseLabel":"الزمر: 69–70","question":"لماذا ذُكرت توفية كل نفس بعد القضاء بين العباد بالحق؟","answer":"لأن التوفية ثمرة القضاء ومرحلته التنفيذية؛ فبعد ثبوت الحكم يأخذ كل إنسان جزاء عمله كاملًا، فيظهر اتصال الحكم العادل بتحققه من غير نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص787، تحت عنوان «نكتة عطف التوفية على القضاء بين العباد»","url":""}]},{"id":"s39-104","number":104,"surah":39,"verses":[69],"references":[{"surah":39,"verses":[69]}],"verseLabel":"الزمر: 69","question":"ما سر تقديم وضع الكتاب على الإتيان بالنبيين والشهداء؟","answer":"قدم الكتاب لأنه يجمع ما ضبط من الأعمال، فيعرض الأصل الذي تتعلق به الشهادة. ثم يحضر النبيون والشهداء فتظهر الحجة على العباد على أكمل وجه، مع أن الله غني بعلمه عن شهادة الشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص780–781، تحت عنوان «نكتة تقديم وضع الكتاب على الإتيان بالنبيين»","url":""}]},{"id":"s39-105","number":105,"surah":39,"verses":[19,71],"references":[{"surah":39,"verses":[19,71]}],"verseLabel":"الزمر: 19، 71","question":"لماذا قيل ﴿حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ﴾ ولم يقل «صدق عليه»؟","answer":"لأن ﴿حق﴾ تدل على ثبوت الحكم ووجوبه ولزومه بعد قيام أسبابه، وهو الأنسب لعذاب استقر استحقاق صاحبه له؛ أما الصدق فيتجه أساسًا إلى مطابقة الخبر للواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص218–219، تحت عنوان «نكتة التعبير بلفظ ﴿حق﴾ دون (صدق)»","url":""}]},{"id":"s39-144","number":144,"surah":39,"verses":[19,71],"references":[{"surah":39,"verses":[19,71]}],"verseLabel":"الزمر: 19، 71","question":"لماذا سُمِّي العذاب في قوله ﴿حَقَّتْ كَلِمَةُ الْعَذَابِ﴾ كلمةً؟","answer":"لأن العذاب ثبت وتقرر بكلمة الله وقضائه، فأُطلق اسم الكلمة على ما نتج عنها من حكم وعقوبة؛ وفي ذلك تصوير لسرعة نفاذ قضائه وارتباط المصير بوعده الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص813، تحت عنوان «فصاحة التعبير المجازي في لفظ ﴿كلمة﴾»","url":""}]},{"id":"s39-106","number":106,"surah":39,"verses":[71,73],"references":[{"surah":39,"verses":[71,73]}],"verseLabel":"الزمر: 71، 73","question":"لماذا استُعمل الفعل نفسه ﴿سِيقَ﴾ للكافرين إلى النار وللمتقين إلى الجنة؟","answer":"جاء في المتقين على سبيل المشاكلة اللفظية بين المشهدين، لا لتساوي الحالين؛ فسوق الكافرين إهانة ودفع، أما المتقون فيتقدمون إلى الجنة مكرمين، وباتحاد اللفظ يبرز اختلاف المصيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص12، تحت عنوان «بلاغة المشاكلة في مفردة (سيق)»","url":""}]},{"id":"s39-107","number":107,"surah":39,"verses":[71,73],"references":[{"surah":39,"verses":[71,73]}],"verseLabel":"الزمر: 71، 73","question":"ما الذي توحي به الواو في ﴿وَفُتِحَتْ أَبْوَابُهَا﴾ عند وصول المتقين إلى الجنة؟","answer":"من أوجهها أنها واو الحال؛ أي جاء المتقون وقد فُتحت الأبواب لاستقبالهم، بخلاف فتح أبواب النار عند وصول أهلها. ويورد المبحث أوجهًا أخرى، فلا تُحصر دلالتها في تفسير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص14–15، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s39-108","number":108,"surah":39,"verses":[71,72],"references":[{"surah":39,"verses":[71,72]}],"verseLabel":"الزمر: 71–72","question":"لماذا قيل للكافرين ﴿ادْخُلُوا أَبْوَابَ جَهَنَّمَ﴾ بعد اعترافهم بمجيء الرسل؟","answer":"ليأتي الحكم عقب الإقرار بالحجة؛ والأمر هنا للإهانة والتقريع لا للتكليف، فيدخلونها عالمين أن مصيرهم نتيجة تكذيبهم بعد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص815، تحت عنوان «غرض الأمر ﴿ادخلوا﴾»","url":""}]},{"id":"s39-109","number":109,"surah":39,"verses":[72],"references":[{"surah":39,"verses":[72]}],"verseLabel":"الزمر: 72","question":"ما مناسبة وصف أهل النار بالمتكبرين في ﴿فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾؟","answer":"اختير وصف المتكبرين لأنه يبين الدافع إلى كفرهم: استعلاؤهم عن توحيد الله وإفراده بالعبادة وقبول آياته. فبعد ذكر كفرهم صرح بعلته، وجاء ذم المثوى ملائمًا لهذا الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص817–818، تحت عنوان «نكتة اختيار لفظ ﴿المتكبرين﴾ دون (الكافرين)»","url":""}]},{"id":"s39-110","number":110,"surah":39,"verses":[73],"references":[{"surah":39,"verses":[73]}],"verseLabel":"الزمر: 73","question":"ماذا تتضمن تحية خزنة الجنة للمتقين بقولهم ﴿طِبْتُمْ﴾؟","answer":"تتضمن الثناء والتكريم: طابت نفوسهم بالإيمان وأعمالهم بالطاعة، وطاب لهم الآن مقامهم ونعيمهم؛ فهي كلمة تجمع طهارة الطريق وطيب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص18، تحت عنوان «بلاغة استعمال مفردة ﴿طبتم﴾»","url":""}]},{"id":"s39-145","number":145,"surah":39,"verses":[73],"references":[{"surah":39,"verses":[73]}],"verseLabel":"الزمر: 73","question":"لماذا قيل لأهل الجنة عند دخولها ﴿خَالِدِينَ﴾؟","answer":"ليكتمل الترحيب بإزالة آخر ما قد ينغص الفرح: فالنعيم ليس إقامة مؤقتة يخشى انقطاعها، بل خلود دائم يطمئنون معه إلى بقاء ما نالوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص19، تحت عنوان «فائدة الحال ﴿خالدين﴾»","url":""}]},{"id":"s39-111","number":111,"surah":39,"verses":[74],"references":[{"surah":39,"verses":[74]}],"verseLabel":"الزمر: 74","question":"لماذا بدأ أهل الجنة بحمد الله على صدق وعده قبل ذكر توريث الأرض؟","answer":"لأن صدق الوعد هو الأصل الجامع لكل ما نالوه، ثم جاء توريث الأرض وحرية التبوؤ تفصيلًا لتحقق ذلك الوعد؛ فبدأوا بالنعمة الكبرى قبل آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص24، تحت عنوان «نكتة تقديم صدق الوعد على توريث الأرض»","url":""}]},{"id":"s39-112","number":112,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"ما سر التعبير بـ﴿حَافِّينَ مِنْ حَوْلِ الْعَرْشِ﴾ دون «حافين حول العرش»؟","answer":"يعرض المبحث في ﴿من﴾ توجيهات: الزيادة للتوكيد، أو التبعيض، أو ابتداء الغاية، ويرجح في عرضه الأخير ابتداء الحف من جوانب العرش. وعلى هذا يبرز اللفظ منشأ الإحاطة وامتدادها، دون أن يلزم منه تقرير هيئة تفصيلية لصفوف الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص34–35، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من حول﴾»","url":""}]},{"id":"s39-113","number":113,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"لماذا قُدِّم التسبيح على الحمد في وصف الملائكة ﴿يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ﴾؟","answer":"لأن تنزيه الله عن النقص يسبق إثبات صفات الكمال له؛ فالتسبيح تخليَة من كل عيب، والحمد تحليَة بكل جميل، وباجتماعهما يكتمل الثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص37، تحت عنوان «غرض تقديم التسبيح على الحمد»","url":""}]},{"id":"s39-114","number":114,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"من القائل ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ في ختام مشهد القيامة؟","answer":"حُذف القائل ليشيع الحمد كأنه نطق به الكون كله بعد ظهور عدل الله، ويجوز أن يكون من قول الملائكة والمؤمنين؛ فالمقصود تعميم الثناء لا تعيين صوت واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص41–42، تحت عنوان «نكتة بناء ﴿وقيل﴾ للمفعول»","url":""}]},{"id":"s39-115","number":115,"surah":39,"verses":[75],"references":[{"surah":39,"verses":[75]}],"verseLabel":"الزمر: 75","question":"ما مناسبة ختم السورة بقوله ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾؟","answer":"يختم الحمد مشهد القضاء بالحق وإيصال كل فريق إلى جزائه، فيشهد بكمال عدل الله وحكمه. ويتصل آخر السورة بأولها؛ فقد افتتحت بإنزال الكتاب والدعوة إلى إخلاص الدين، واختتمت بالتسبيح والحمد عند تمام الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص44–45، تحت عنوان «بلاغة رد عجز السورة على صدرها»","url":""}]},{"id":"s39-146","number":146,"surah":39,"verses":[3,75],"references":[{"surah":39,"verses":[3,75]}],"verseLabel":"الزمر: 3، 75","question":"كيف تجيب خاتمة السورة عن مطلعها في الانتقال من ﴿إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ﴾ إلى ﴿وَقُضِيَ بَيْنَهُم بِالْحَقِّ﴾؟","answer":"افتتحت السورة بوعد الحكم في اختلاف المشركين، ثم عرضت الخصومة والموت والبعث ومصير الفريقين، حتى انتهت إلى وقوع ما وُعد به: ﴿وقضي بينهم بالحق﴾. فالحكم في المطلع إعلان لما سيكون، والقضاء في الخاتمة إنجاز وفصل نهائي؛ وبذلك تنغلق بنية السورة على تمام العدل والحمد.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص122–125، مبحث «من سورتي المؤمنون والزمر»، عنوان جزئي: «مناسبة الاختصام لمفتتح سورة الزمر وخاتمتها»؛ وانظر المادة الإلكترونية المباشرة بعنوان «تناسب فواتح سورة الزمر مع خواتيمها».","url":""}]},{"id":"s39-147","number":147,"surah":39,"verses":[7],"references":[{"surah":39,"verses":[7]}],"verseLabel":"الزمر: 7","question":"ما دلالة تقديم الكفر على الشكر في قوله ﴿إِن تَكْفُرُوا... وَإِن تَشْكُرُوا﴾، مع أن الغالب في القرآن تقديم الشكر؟","answer":"جاء الترتيب منسجمًا مع جو السورة؛ فقد سبق الحديث عن الكاذب الكفار واتخاذ الأولياء من دون الله، فكان الكفر هو المعنى المتقدم في السياق. وكذلك تعرض الخاتمة مصير الكافرين قبل مصير المتقين، فجاء ترتيب الشرطين في الآية صورة مصغرة للترتيب العام في السورة.","sources":[{"label":"فاضل السامرائي، «سر تقديم الكفر على الشكر في سورة الزمر»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-148","number":148,"surah":39,"verses":[10,53],"references":[{"surah":39,"verses":[10,53]}],"verseLabel":"الزمر: 10، 53","question":"ما سر حذف ياء المتكلم في ﴿قُلْ يَا عِبَادِ الَّذِينَ آمَنُوا﴾، وإثباتها في ﴿قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا﴾؟","answer":"تناسب سعة اللفظ سعة الجماعة في الاستعمال القرآني الذي تتبعه السامرائي؛ فصيغة «عبادي» أطول، وجاءت مع المسرفين وهم أكثر عددًا. أما «عبادِ» المحذوفة الياء فجاءت مع من حققوا الإيمان والتقوى والصبر، وهؤلاء أقل، فوافق قِصر المبنى قلة الجماعة.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين عباد وعبادي؟»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-149","number":149,"surah":39,"verses":[17],"references":[{"surah":39,"verses":[17]}],"verseLabel":"الزمر: 17","question":"ما سر عود ضمير المؤنث الجمع في ﴿أَن يَعْبُدُوهَا﴾ على «الطاغوت»؟","answer":"«الطاغوت» لفظ يستعمل للمفرد والجمع، وللمذكر والمؤنث بحسب السياق. وقد دل قوله قبلها ﴿فَاعْبُدُوا مَا شِئْتُم مِّن دُونِهِ﴾ على تعدد المعبودات، فحُمل الطاغوت هنا على جماعة الأصنام غير العاقلة، ولذلك عاد عليه ضمير المؤنث الجمع «ها».","sources":[{"label":"فاضل السامرائي، «دلالة تأنيث الضمير في: اجتنبوا الطاغوت أن يعبدوها»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 17.","url":""}]},{"id":"s39-150","number":150,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"ما سر إطلاق الخشية في ﴿يَخْشَوْنَ رَبَّهُمْ﴾ من غير تقييدها بـ«الغيب»؟","answer":"اقشعرار الجلد ولين القلب حالان باطنتان لا يطلع على حقيقتهما إلا صاحبهما وربه؛ فمعنى الغيب داخل في الصورة نفسها. ولو قيل «بالغيب» لم يضف القيد معنى يحتاجه المقام، فجاء التعبير مطلقًا محكمًا من غير زيادة لا تؤدي وظيفة.","sources":[{"label":"فاضل السامرائي، «سر عدم ذكر بالغيب في آية الزمر»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-151","number":151,"surah":39,"verses":[29],"references":[{"surah":39,"verses":[29]}],"verseLabel":"الزمر: 29","question":"ما دلالة التثنية في ﴿هَلْ يَسْتَوِيَانِ مَثَلًا﴾، بينما جاء في سورة النحل ﴿هَلْ يَسْتَوُونَ﴾؟","answer":"المثل في الزمر عرض رجلين معينين في الصورة: رجلًا تتنازعه شركاء، ورجلًا خالصًا لسيد واحد؛ فناسبت التثنية «يستويان». أما موضع النحل فالتعبير فيه بـ«من» يفتح الوصف لفئة وأفراد متعددين، فناسبه جمع الضمير «يستوون».","sources":[{"label":"فاضل السامرائي، «الفرق بين هل يستويان وهل يستوون»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 29.","url":""}]},{"id":"s39-152","number":152,"surah":39,"verses":[30],"references":[{"surah":39,"verses":[30]}],"verseLabel":"الزمر: 30","question":"ما الفرق البياني بين «مَيِّت» بتشديد الياء و«مَيْت» بتسكينها؟","answer":"«الميْت» بالتسكين يقال في الأصل لمن تحقق موته، حقيقة أو مجازًا. أما «الميّت» بالتشديد فيصح أن يطلق على الحي الذي سيؤول حتمًا إلى الموت؛ ولذلك جاء ﴿إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ﴾ خطابًا لأحياء سيقع عليهم الموت يقينًا.","sources":[{"label":"فاضل السامرائي، «الفرق بين مَيْت ومَيِّت في القرآن»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 30.","url":""}]},{"id":"s39-153","number":153,"surah":39,"verses":[38],"references":[{"surah":39,"verses":[38]}],"verseLabel":"الزمر: 38","question":"ما سر الماضي في ﴿إِنْ أَرَادَنِيَ اللَّهُ بِضُرٍّ﴾، والمضارع واسم «الرحمن» في ﴿إِن يُرِدْنِ الرَّحْمَنُ بِضُرٍّ﴾ بسورة يس؟","answer":"الماضي مع الشرط يصير مستقبل المعنى، لكنه كثيرًا ما يصور افتراض وقوع الحدث مرة، أما المضارع فيحتمل تجدده وتكرره؛ وصاحب يس يتوقع استمرار التهديد والضر، فكأنه يلوذ بالرحمن ويستدعي رحمته. كما وافق اسم «الله» كثرة وروده في الزمر، واسم «الرحمن» جو سورة يس وتكرره فيها.","sources":[{"label":"فاضل السامرائي، «الفرق بين إن أرادني الله وإن يردن الرحمن»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-154","number":154,"surah":39,"verses":[54],"references":[{"surah":39,"verses":[54]}],"verseLabel":"الزمر: 54","question":"ما دلالة الرفع في ﴿ثُمَّ لَا تُنصَرُونَ﴾ بعد الفعل المنصوب ﴿أَن يَأْتِيَكُمُ الْعَذَابُ﴾؟","answer":"«ثم» هنا ليست عاطفة تجعل «لا تنصرون» تابعًا للفعل المنصوب، وإنما هي استئنافية افتتح بها خبر جديد. فالمعنى: أنيبوا وأسلموا قبل مجيء العذاب؛ ثم إن جاءكم فلن تنصروا. واستقلال الجملة يجعل نفي النصرة حكمًا حاسمًا بعد فوات زمن الإنابة.","sources":[{"label":"فاضل السامرائي، «دلالة ثم الاستئنافية في: ثم لا تنصرون»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 54.","url":""}]},{"id":"s39-155","number":155,"surah":39,"verses":[73],"references":[{"surah":39,"verses":[73]}],"verseLabel":"الزمر: 73","question":"أين جواب ﴿حَتَّى إِذَا جَاؤُوهَا﴾، وما السر البلاغي في حذفه؟","answer":"حُذف جواب الشرط تفخيمًا لما يلقاه أهل الجنة؛ لأن تعيين جواب محدود يضيّق صورة النعيم، أما تركه فيفتح الخيال على ما تعجز العبارة عن الإحاطة به. فكأن المعنى: إذا جاؤوها وفتحت أبوابها واستُقبلوا بالسلام رأوا من الكرامة ما لا تبلغه اللغة.","sources":[{"label":"فاضل السامرائي، «اللغة تعجز أن تعبر عن نعيم الجنة: الجواب هناك»، مقطع مباشر على منصة «باحث».","url":""}]},{"id":"s39-156","number":156,"surah":39,"verses":[2,41],"references":[{"surah":39,"verses":[2,41]}],"verseLabel":"الزمر: 2، 41","question":"ما سر التعبير بـ﴿أَنزَلْنَا إِلَيْكَ الْكِتَابَ﴾ في أول السورة، وبـ﴿أَنزَلْنَا عَلَيْكَ الْكِتَابَ لِلنَّاسِ﴾ في أثنائها؟","answer":"يجيء حرف «إلى» مع جهة وصول الكتاب إلى الرسول ﷺ وما يتصل بتلقيه وعبادته، ولذلك أعقبه الأمر بالإخلاص. أما «على» فتناسب معنى الحمل والتكليف؛ فالآية الثانية تتحدث عن كتاب أُنزل للناس، والرسول مكلَّف بتبليغه لهم، فناسبها الحرف الدال على الاستعلاء وما فيه من ثقل الرسالة.","sources":[{"label":"فاضل السامرائي، «الفرق بين: أنزلنا إليك الكتاب، وأنزلنا عليك الكتاب للناس»، برنامج لمسات بيانية، مادة إلكترونية مباشرة.","url":""}]},{"id":"s39-157","number":157,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"ما سر التعبير عن خلق الأنعام بقوله ﴿وَأَنزَلَ لَكُم مِّنَ الْأَنْعَامِ ثَمَانِيَةَ أَزْوَاجٍ﴾؟","answer":"الإنزال هنا بمعنى الخلق والإيجاد، وهو استعمال عربي قرآني لا يلزم منه أن الأنعام هبطت بأعيانها من السماء. والتعبير يلفت إلى أن هذه الأزواج رزق مقدر مسخّر للإنسان، فمبدأ الإنعام والتقدير من الله، كما ينزل سائر رزقه وتدبيره على عباده.","sources":[{"label":"فاضل السامرائي، «وأنزل لكم من الأنعام ثمانية أزواج: هل أُنزلت الأنعام من السماء؟»، مقطع مباشر على منصة «باحث».","url":""}]},{"id":"s39-158","number":158,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"ما أثر دخول «من» في قوله ﴿لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ النَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ﴾؟","answer":"«من» لابتداء الغاية، فتجعل العذاب مبتدئًا من الجهة الملاصقة لهم من فوق ومن تحت، من غير فجوة يتوهم معها بعده عنهم. ولو قيل «فوقهم» فقط لاحتمل اللفظ وجود مسافة؛ أما التعبير القرآني فيرسم إحاطة مباشرة خانقة.","sources":[{"label":"فاضل السامرائي، «دلالة من في: لهم من فوقهم ظلل»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 16.","url":""}]},{"id":"s39-159","number":159,"surah":39,"verses":[18],"references":[{"surah":39,"verses":[18]}],"verseLabel":"الزمر: 18","question":"ما سر إظهار الضمير في ﴿أُولَئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ﴾، وحذفه في ﴿أُولَئِكَ الَّذِينَ هَدَى اللَّهُ﴾ بالأنعام؟","answer":"العائد مقدر في آية الأنعام أيضًا، لكن حذفه أخرج الهداية إلى سعة العموم؛ فالسياق هناك يضم أنبياء كثيرين وشرائع وهدايات متعددة. أما آية الزمر فتتحدث عن جماعة محددة تستمع القول وتتبع أحسنه، فذُكر الضمير لتخصيصهم بهذه الهداية وإبراز صلتها بهم.","sources":[{"label":"فاضل السامرائي، «الفرق بين هدى الله وهداهم الله»، مقطع مباشر على منصة «باحث».","url":""}]},{"id":"s39-160","number":160,"surah":39,"verses":[21],"references":[{"surah":39,"verses":[21]}],"verseLabel":"الزمر: 21","question":"ما سر إسناد التحطيم إلى الله في ﴿ثُمَّ يَجْعَلُهُ حُطَامًا﴾، والتعبير بـ﴿ثُمَّ يَكُونُ حُطَامًا﴾ في سورة الحديد؟","answer":"آية الزمر بنت المشهد كله على أفعال مسندة إلى الله: أنزل الماء، وسلكه ينابيع، وأخرج به الزرع؛ فناسب استمرار هذا النسق أن يقال «ثم يجعله حطامًا». أما آية الحديد فضربت مثلًا بالغيث ولم تسند مراحل المشهد ابتداءً إلى الله في تركيبها، فجاءت النتيجة بصيغة «يكون».","sources":[{"label":"فاضل السامرائي، «الفرق بين: ثم يجعله حطامًا، ثم يكون حطامًا»، مادة إلكترونية مباشرة.","url":""}]},{"id":"s39-161","number":161,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"ما دلالة اختيار «الخشية» في ﴿جُلُودُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ﴾ بدل الخوف أو الوجل؟","answer":"الخوف توقع المكروه، أما الخشية فخوف يمتزج بالتعظيم ويقوم غالبًا على العلم بمن يُخشى؛ ولذلك نُسبت إلى العلماء في موضع آخر. والوجل اضطراب يقع في القلب. فاختيار الخشية هنا يلائم تلقي القرآن بعلم وتعظيم، ثم ظهرت آثارها على الجلود والقلوب.","sources":[{"label":"فاضل السامرائي، «الفرق بين الخشية والخوف والوجل»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-162","number":162,"surah":39,"verses":[30],"references":[{"surah":39,"verses":[30]}],"verseLabel":"الزمر: 30","question":"ما سر الاكتفاء بـ«إنّ» في ﴿إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ﴾، وزيادة اللام في ﴿ثُمَّ إِنَّكُم بَعْدَ ذَلِكَ لَمَيِّتُونَ﴾ بالمؤمنون؟","answer":"تكرر ذكر الموت وصوره في سورة المؤمنون نحو عشر مرات، فناسب كثافة هذا الجو زيادة التوكيد بإن واللام. أما في سورة الزمر فقل ذكر الموت، فجاء التوكيد بحرف واحد. وهكذا وافقت قوة المبنى كثرة المعنى في موطنها، وخف المبنى حيث قل ترداده.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص114–121، مبحث «من سورتي المؤمنون والزمر».","url":""}]},{"id":"s39-163","number":163,"surah":39,"verses":[31],"references":[{"surah":39,"verses":[31]}],"verseLabel":"الزمر: 31","question":"ما سر إبقاء التاء في ﴿عِندَ رَبِّكُمْ تَخْتَصِمُونَ﴾، وإدغامها في ﴿وَهُمْ يَخِصِّمُونَ﴾ بسورة يس؟","answer":"«تختصمون» أطول مبنى، فناسبت خصومة الآخرة الطويلة التي تقام فيها الحجج وتسمع الأقوال ويقع القضاء. أما «يخصّمون» ففيها إدغام وشدة وسرعة، فوافقت خصومة الدنيا الصاخبة التي تفاجئ أصحابها الصيحة قبل أن يتموا جدالهم. فصورة اللفظ تحاكي طبيعة الحدث وزمنه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص122–125، مبحث «من سورتي المؤمنون والزمر»؛ وانظر المقطع المباشر «تأخذهم وهم يخصمون: ما معنى يخصمون؟».","url":""}]},{"id":"s39-164","number":164,"surah":39,"verses":[66],"references":[{"surah":39,"verses":[66]}],"verseLabel":"الزمر: 66","question":"ما دلالة تقديم اسم الجلالة في ﴿بَلِ اللَّهَ فَاعْبُدْ﴾؟","answer":"تقديم المفعول به على فعله يفيد الاختصاص في هذا المقام؛ فليس المراد مجرد الأمر بالعبادة، بل قصرها على الله وحده: الله وحده فاعبد، لا ما دعوك إلى عبادته من دونه. وهكذا جاء التقديم جوابًا قاطعًا لدعوة المشركين إلى الشرك.","sources":[{"label":"فاضل السامرائي، «تقديم المفعول ودلالة الاختصاص في: بل الله فاعبد»، مادة إلكترونية مباشرة من مباحث التعبير القرآني.","url":""}]},{"id":"s39-165","number":165,"surah":39,"verses":[68],"references":[{"surah":39,"verses":[68]}],"verseLabel":"الزمر: 68","question":"ما دلالة تقديم أهل السماوات على أهل الأرض في ﴿فَصَعِقَ مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ﴾؟","answer":"النفخة تأتي من جهة السماء ويبدأ أثرها هناك، فقدم من في السماوات موافقة لبداية الحدث ومساره، ثم عطف عليهم من في الأرض. فترتيب المذكورات ليس تعدادًا مجردًا، بل يتبع ترتيب وقوع الصعق في المشهد.","sources":[{"label":"فاضل السامرائي، «التقديم والتأخير بين السماوات والأرض في آية النفخ في الصور»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-166","number":166,"surah":39,"verses":[70],"references":[{"surah":39,"verses":[70]}],"verseLabel":"الزمر: 70","question":"ما سر الجمع بين الماضي في ﴿مَا عَمِلَتْ﴾ والمضارع الأعم في ﴿بِمَا يَفْعَلُونَ﴾؟","answer":"العمل في الأصل أخص، ويغلب أن يكون عن قصد؛ أما الفعل فأعم، يقع بقصد وبغير قصد. وفي موقف الحساب تكون أعمال الدنيا قد انقضت فقيل «عملت» بالماضي، ثم التفت الخطاب إلى الناس في الدنيا فقيل «يفعلون» بالمضارع؛ تحذيرًا لهم من أن علم الله محيط بما يتجدد منهم، مقصودًا كان أو غير مقصود.","sources":[{"label":"فاضل السامرائي، «الفرق بين العمل والفعل، وسر الماضي والمضارع في آية الزمر»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-167","number":167,"surah":39,"verses":[71],"references":[{"surah":39,"verses":[71]}],"verseLabel":"الزمر: 71","question":"ما دلالة ﴿يَتْلُونَ عَلَيْكُمْ آيَاتِ رَبِّكُمْ﴾ هنا، وورود ﴿يَقُصُّونَ عَلَيْكُمْ آيَاتِي﴾ في سورة الأنعام؟","answer":"التلاوة تكون لنص مكتوب أو محفوظ يُتبع بعضه بعضًا، فناسبت المخاطبين في الزمر الذين جاءتهم الرسل بآيات وكتب يتلونها. أما القصص فأوسع؛ يكون في المكتوب والمنطوق، وجاء في الأنعام خطابًا عامًا لمعشر الجن والإنس، فاختير له اللفظ الأعم.","sources":[{"label":"فاضل السامرائي، «الفرق بين يتلون عليكم آيات ربكم ويقصون عليكم آياتي»، برنامج لمسات بيانية.","url":""}]},{"id":"s40-1","number":1,"surah":40,"verses":[1],"references":[{"surah":40,"verses":[1]}],"verseLabel":"عنوان السورة","question":"لماذا سُمّيت سورة غافر بهذا الاسم؟","answer":"لأن مطلعها وصف الله بأنه ﴿غافر الذنب﴾، فصار الاسم تذكيرًا بباب المغفرة ودعوة إلى التوبة، وهو من أبرز مقاصد السورة في دعوة المجادلين إلى الرجوع للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص49–50، تحت عنوان «اسم السورة ومناسبة تسميتها»","url":""}]},{"id":"s40-2","number":2,"surah":40,"verses":[1],"references":[{"surah":40,"verses":[1]}],"verseLabel":"عنوان السورة","question":"لماذا تُسمّى سورة غافر أيضًا «سورة المؤمن»؟","answer":"لأنها انفردت بالتفصيل في قصة مؤمن آل فرعون الذي كتم إيمانه ثم جهر بالحجة مدافعًا عن موسى عليه السلام؛ فصار هذا المشهد المميز علمًا على السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص49، تحت عنوان «اسم السورة ومناسبة تسميتها»","url":""}]},{"id":"s40-3","number":3,"surah":40,"verses":[1,2,3],"references":[{"surah":40,"verses":[1,2,3]}],"verseLabel":"غافر: 1–3","question":"ما دلالة افتتاح سورة غافر بـ﴿حم﴾؟","answer":"تنبه الحروف المقطعة إلى أن القرآن مؤلف من الحروف العربية التي يعرفها المخاطبون، ومع ذلك عجزوا عن الإتيان بمثله؛ فهي تستثير الانتباه إلى إعجازه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص60، تحت عنوان «دلالة التعبير بالحروف المقطعة في بداية السورة»","url":""}]},{"id":"s40-137","number":137,"surah":40,"verses":[1,2,3],"references":[{"surah":40,"verses":[1,2,3]}],"verseLabel":"غافر: 1–3","question":"لماذا وُصف مُنزِّل القرآن هنا بأنه ﴿الْعَزِيزِ الْعَلِيمِ﴾؟","answer":"لأن عزة الله تؤكد أن تنزيله لا يُغالب، وعلمه يؤكد إحاطة الكتاب بالحكمة والحق؛ فاجتماعهما يلائم مصدر القرآن المعجز المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص63–64، تحت عنوان «نكتة الوصف بالعزيز العليم دون غيرهما»","url":""}]},{"id":"s40-4","number":4,"surah":40,"verses":[2],"references":[{"surah":40,"verses":[2]}],"verseLabel":"غافر: 2","question":"ما مناسبة تقديم ﴿الْعَزِيزِ﴾ على ﴿الْعَلِيمِ﴾ في مصدر التنزيل؟","answer":"قدم العزيز لأن ترتيب الحكم وإقامته يحتاجان إلى قوة تنفذهما، ثم جاء العليم ليدل على العلم الذي يكون به الإحكام. فيلائم ترتيب الوصفين كون الكتاب صادرًا عمن ينفذ أمره ويعلم مواضع حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص64، تحت عنوان «نكتة تقديم ﴿العزيز﴾ على ﴿العليم﴾»","url":""}]},{"id":"s40-5","number":5,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا قيل ﴿غَافِرِ الذَّنْبِ﴾ بدل وصف آخر للمغفرة؟","answer":"اختير الغفران لما فيه من معنى الستر والوقاية؛ فالله يستر ذنب عبده ويقيه تبعته وعقوبته، وفي الوصف فتح لباب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص66، تحت عنوان «نكتة التعبير بالغفران»","url":""}]},{"id":"s40-138","number":138,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"ما سر عطف ﴿قَابِلِ التَّوْبِ﴾ بالواو بعد ﴿غَافِرِ الذَّنْبِ﴾؟","answer":"ليظهر أن قبول رجوع العبد ومغفرة ذنبه فضلَان متلازمان غير متطابقين؛ فإذا تاب قُبل رجوعه وغُفر ذنبه، فتقوى الدعوة إلى التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص68، تحت عنوان «سر العطف بالواو في قوله: ﴿وقابل التوب﴾»","url":""}]},{"id":"s40-6","number":6,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا أُخّر وصف ﴿شَدِيدِ الْعِقَابِ﴾ عن المغفرة وقبول التوبة؟","answer":"ليبدأ الخطاب بما يفتح الرجاء ويستميل إلى التوبة، ثم يردع عن الإصرار بذكر العقاب؛ فالتقديم يؤكد سعة الرحمة من غير أن يفتح باب الاغترار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص70–71، تحت عنوان «نكتة تأخير الوعيد عن الوعد»","url":""}]},{"id":"s40-139","number":139,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا قيل ﴿ذِي الطَّوْلِ﴾ بعد ﴿شَدِيدِ الْعِقَابِ﴾؟","answer":"لأن الطَّول هو الفضل والإنعام؛ فجاء بعد الوعيد ليفتح باب الإحسان والرجاء، ويبين أن شدة العقاب لا تنافي سعة الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص71، تحت عنوان «نكتة التعبير بقوله تعالى: ﴿ذي الطول﴾»","url":""}]},{"id":"s40-7","number":7,"surah":40,"verses":[3],"references":[{"surah":40,"verses":[3]}],"verseLabel":"غافر: 3","question":"لماذا قُدّم ﴿إِلَيْهِ﴾ في قوله ﴿إِلَيْهِ الْمَصِيرُ﴾؟","answer":"لقصر المصير على الله وحده؛ فإليه المرجع النهائي، ولا يملك أحد من دونه الحكم في ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص76، تحت عنوان «غرض تقديم ﴿إليه﴾»","url":""}]},{"id":"s40-8","number":8,"surah":40,"verses":[4],"references":[{"surah":40,"verses":[4]}],"verseLabel":"غافر: 4","question":"لماذا قُصرت المجادلة في آيات الله على الكافرين؟","answer":"لأن المراد مجادلة المكابر الذي يريد رد الآيات بعد ظهور حجتها، لا النظر الصادق طلبًا للفهم؛ فجعلها القصر علامة على الكفر حين تكون لإبطال الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص81، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s40-9","number":9,"surah":40,"verses":[4],"references":[{"surah":40,"verses":[4]}],"verseLabel":"غافر: 4","question":"لماذا قيل ﴿فَلَا يَغْرُرْكَ﴾ عند الحديث عن تقلب الكافرين في البلاد؟","answer":"لأن ما يظهر عليهم من سعة ورواج قد يخدع الناظر فيحسبه دليل سلامة ونجاة؛ فنُهي الرسول ﷺ وكل سامع عن الاغترار بالإمهال الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص84، تحت عنوان «نكتة التعبير بالغرور»","url":""}]},{"id":"s40-10","number":10,"surah":40,"verses":[5],"references":[{"surah":40,"verses":[5]}],"verseLabel":"غافر: 5","question":"لماذا عُطف ﴿الْأَحْزَابُ﴾ على قوم نوح؟","answer":"ليجمع الأمم المختلفة التي تحزبت على رسلها بعد قوم نوح في صف واحد من التكذيب، على اختلاف أزمانها وأوطانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص91، تحت عنوان «بلاغة عطف ﴿والأحزاب﴾»","url":""}]},{"id":"s40-140","number":140,"surah":40,"verses":[5],"references":[{"surah":40,"verses":[5]}],"verseLabel":"غافر: 5","question":"ماذا يضيف قوله ﴿وَهَمَّتْ كُلُّ أُمَّةٍ بِرَسُولِهِمْ لِيَأْخُذُوهُ﴾ بعد ذكر التكذيب؟","answer":"يكشف أن المعارضة لم تقف عند إنكار اللسان، بل تحولت إلى عزم على البطش بالرسل؛ فتتدرج الصورة من التكذيب إلى العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص92–93، تحت عنوان «نكتة العطف في قوله: ﴿وهمت﴾»","url":""}]},{"id":"s40-11","number":11,"surah":40,"verses":[5],"references":[{"surah":40,"verses":[5]}],"verseLabel":"غافر: 5","question":"ما أثر مقابلة ﴿الْبَاطِلِ﴾ بـ﴿الْحَقَّ﴾ في قوله ﴿وَجَادَلُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ﴾؟","answer":"تبرز المفارقة بين وسيلتهم وغايتهم: يريدون إسقاط الثابت بما لا ثبات له، فتفضح المقابلة فساد مجادلتهم قبل بيان نتيجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص98، تحت عنوان «بلاغة الطباق بين الحق والباطل»","url":""}]},{"id":"s40-12","number":12,"surah":40,"verses":[5,6],"references":[{"surah":40,"verses":[5,6]}],"verseLabel":"غافر: 5–6","question":"ما دلالة قوله ﴿فَأَخَذْتُهُمْ﴾ في عقوبة الأمم المكذبة؟","answer":"صوّر إهلاكهم بالأخذ المحكم الذي لا انفلات منه، ليشعر بأن القوة التي أمهلتهم أحاطت بهم حين جاء موعد العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص99، تحت عنوان «بلاغة المجاز في فعل الأخذ»","url":""}]},{"id":"s40-141","number":141,"surah":40,"verses":[5,6],"references":[{"surah":40,"verses":[5,6]}],"verseLabel":"غافر: 5–6","question":"بِمَ يشبَّه ثبوت العذاب على الكافرين في قوله ﴿وَكَذَلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ﴾؟","answer":"شُبّه استحقاق الكافرين الحاضرين للعذاب باستحقاق الأمم السابقة التي كذبت فأُخذت؛ فيوصل وعيد الآخرة بالمثال التاريخي المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص104، تحت عنوان «بلاغة التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s40-13","number":13,"surah":40,"verses":[7],"references":[{"surah":40,"verses":[7]}],"verseLabel":"غافر: 7","question":"لماذا ذُكر إيمان حملة العرش مع أن إيمان الملائكة معلوم؟","answer":"لإبراز جامع الإيمان بينهم وبين المؤمنين الذين يستغفرون لهم؛ فذكر الصفة يبين سر عنايتهم بإخوانهم في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص114، تحت عنوان «فائدة ذكر الإيمان مع أنه مسلم به»","url":""}]},{"id":"s40-142","number":142,"surah":40,"verses":[7],"references":[{"surah":40,"verses":[7]}],"verseLabel":"غافر: 7","question":"لماذا قدّم حملة العرش التسبيح والإيمان على الاستغفار للمؤمنين؟","answer":"لأنهم بدؤوا بتعظيم الله والثناء عليه قبل طلب حاجتهم، فقدموا حق الرب ثم دعاءهم لعباده؛ وذلك من أدب الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص115، تحت عنوان «دلالة الترتيب بين الأفعال الثلاثة»","url":""}]},{"id":"s40-14","number":14,"surah":40,"verses":[7],"references":[{"surah":40,"verses":[7]}],"verseLabel":"غافر: 7","question":"لماذا قُدمت الرحمة على العلم في قول الملائكة ﴿وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا﴾؟","answer":"لأن الرحمة هي المقصودة في مقام طلب المغفرة، ثم جاء العلم ليؤكد إحاطة الله بحال المؤمنين وصدق توبتهم؛ فترتب الوصفان على مقصد الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص118–119، تحت عنوان «نكتة تقديم الرحمة على العلم»","url":""}]},{"id":"s40-15","number":15,"surah":40,"verses":[7,8],"references":[{"surah":40,"verses":[7,8]}],"verseLabel":"غافر: 7–8","question":"لماذا دعا الملائكة للمؤمنين بدخول الجنة بعد أن دعوا لهم بالوقاية من الجحيم؟","answer":"ليجمع الدعاء بين دفع الضرر ونيل النعيم؛ فالوقاية وحدها نجاة، ثم جاء طلب الجنة ليتم الفوز بالإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص127، تحت عنوان «فائدة عطف الدعاء بدخول الجنة على الوقاية من النار»","url":""}]},{"id":"s40-143","number":143,"surah":40,"verses":[7,8],"references":[{"surah":40,"verses":[7,8]}],"verseLabel":"غافر: 7–8","question":"لماذا شمل دعاء الملائكة أهل المؤمن وذريته؟","answer":"لأن نعيم الجنة يتم باجتماع الأحبة؛ فوسّعوا الدعاء ليشمل من يرتبط بالمؤمن من أهله، فيجتمع لهم النعيم والأنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص131، تحت عنوان «دلالة العطف وفائدته»","url":""}]},{"id":"s40-16","number":16,"surah":40,"verses":[8],"references":[{"surah":40,"verses":[8]}],"verseLabel":"غافر: 8","question":"ماذا تضيف كلمة ﴿عَدْنٍ﴾ إلى وصف الجنات؟","answer":"العدن هو الإقامة والثبات؛ فتدل الكلمة على أن دخولها استقرار دائم لا يعقبه خروج ولا تحول.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص129، تحت عنوان «براعة استعمال مفردة ﴿عدن﴾»","url":""}]},{"id":"s40-17","number":17,"surah":40,"verses":[9],"references":[{"surah":40,"verses":[9]}],"verseLabel":"غافر: 9","question":"لماذا قال الملائكة ﴿وَقِهِمُ السَّيِّئَاتِ﴾ مع أن السيئات أعمال وقعت بالفعل؟","answer":"أطلقت السيئات وأريد ما يترتب عليها من العقوبات والأهوال؛ فالدعاء أن يقيهم الله تبعات الذنوب، وجاء التعبير بالسبب لاستحضار الصلة بين العمل وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص139–140، تحت عنوان «لفظ ﴿السيئات﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s40-144","number":144,"surah":40,"verses":[9],"references":[{"surah":40,"verses":[9]}],"verseLabel":"غافر: 9","question":"ماذا تضيف الجملة الشرطية ﴿وَمَنْ تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ﴾؟","answer":"تجعل الوقاية من تبعات الذنب علامة محققة على الرحمة، وتؤكد أن السلامة يوم القيامة لا تكون إلا برحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص141، تحت عنوان «بلاغة التذييل بالجملة الشرطية»","url":""}]},{"id":"s40-18","number":18,"surah":40,"verses":[10],"references":[{"surah":40,"verses":[10]}],"verseLabel":"غافر: 10","question":"ما سر بناء ﴿يُنَادَوْنَ﴾ للمجهول في توبيخ أهل النار؟","answer":"لم يسم المنادي لأن المقصود إبراز النداء وما يحمله من التوبيخ، وإبهامه يزيد هوله على المنادين. ويتجه السامع بذلك إلى مضمون الحكم الذي يواجه أهل النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص149، تحت عنوان «نكتة التعبير بصيغة المبني للمفعول»","url":""}]},{"id":"s40-19","number":19,"surah":40,"verses":[10],"references":[{"surah":40,"verses":[10]}],"verseLabel":"غافر: 10","question":"لماذا قيل للكافرين إن مقت الله لهم ﴿أَكْبَرُ﴾ من مقتهم أنفسهم؟","answer":"لأنهم حين يرون الخسران يمقتون أنفسهم، فيقال لهم إن بغض الله لهم وقت كفرهم أعظم وأشد؛ فيتضاعف توبيخهم ولا يبقى الندم وصفًا كافيًا لحالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص151–152، تحت عنوان «بلاغة استعمال مفردة ﴿أكبر﴾ مادة وصيغة»","url":""}]},{"id":"s40-20","number":20,"surah":40,"verses":[11],"references":[{"surah":40,"verses":[11]}],"verseLabel":"غافر: 11","question":"لماذا فرّع أهل النار سؤال الخروج على اعترافهم بالذنوب؟","answer":"ظنوا أن اعترافهم قد يفتح لهم طريق النجاة، فجاءت الفاء لتكشف تعلقهم بأن يجعلوا الإقرار سببًا للخروج بعد فوات زمن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص166–167، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s40-145","number":145,"surah":40,"verses":[11],"references":[{"surah":40,"verses":[11]}],"verseLabel":"غافر: 11","question":"ماذا يفيد تنكير ﴿خُرُوجٍ﴾ في قولهم ﴿فَهَلْ إِلَى خُرُوجٍ مِنْ سَبِيلٍ﴾؟","answer":"يصور أنهم لا يطلبون خروجًا مخصوصًا، بل يتعلقون بأي نوع من الخروج مهما كان، من شدة ما هم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص168، تحت عنوان «نكتة تنكير لفظ ﴿خروج﴾»","url":""}]},{"id":"s40-146","number":146,"surah":40,"verses":[11],"references":[{"surah":40,"verses":[11]}],"verseLabel":"غافر: 11","question":"لماذا نُكرت ﴿سَبِيلٍ﴾ في سؤال أهل النار عن الخروج؟","answer":"للدلالة على أنهم يبحثون عن أدنى وسيلة ممكنة، أيًّا كانت؛ فالتنكير يصور اليأس الذي يدفعهم إلى التعلق بأي طريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص169، تحت عنوان «نكتة تنكير ﴿سبيل﴾»","url":""}]},{"id":"s40-21","number":21,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"ما وجه الأسلوب الحكيم في جواب طلب الخروج ببيان موقفهم من التوحيد والشرك؟","answer":"صرف الجواب نظرهم عن مجرد طلب الخروج إلى سبب ما حل بهم: كانوا يكفرون إذا أفرد الله بالدعاء، ويؤمنون إذا أشرك به. ففيه إفهامهم أن موطن النجاة كان قبول التوحيد، وقطع الرجاء الذي بنوه على مجرد الاعتراف المتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص174، تحت عنوان «بلاغة الأسلوب الحكيم»","url":""}]},{"id":"s40-22","number":22,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا قيل ﴿إِذَا دُعِيَ اللَّهُ وَحْدَهُ كَفَرْتُمْ﴾ ثم ﴿وَإِنْ يُشْرَكْ بِهِ تُؤْمِنُوا﴾؟","answer":"جاءت ﴿إذا﴾ لتحقيق وقوع دعوتهم إلى التوحيد ورفضهم لها، وجاءت ﴿إن﴾ في الشرك على صورة الفرض لأن الشرك بعد وضوح الأدلة مما لا ينبغي أن يقع أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص177–178، تحت عنوان «سر المخالفة بين أداتي الشرط»","url":""}]},{"id":"s40-147","number":147,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا جاء جواب الإشراك بصيغة المضارع ﴿تُؤْمِنُوا﴾؟","answer":"ليستحضر تجدد قبولهم للشرك واستعدادهم المتكرر له؛ فكلما عُرض عليهم باطل سارعوا إلى تصديقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص179، تحت عنوان «نكتة مجيء جواب الشرط بصيغة المضارع»","url":""}]},{"id":"s40-23","number":23,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا وُصف الله بـ﴿الْعَلِيِّ﴾ بعد قوله ﴿فَالْحُكْمُ لِلَّهِ﴾؟","answer":"لأن علوه يقرر أنه فوق كل منازع، فلا يعلو حكمٌ على حكمه ولا يرد قضاؤه؛ فناسب الوصف انفراده بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص181، تحت عنوان «اختيار صفة ﴿العلي﴾»","url":""}]},{"id":"s40-148","number":148,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا أُتبع ﴿الْعَلِيِّ﴾ بوصف ﴿الْكَبِيرِ﴾؟","answer":"لأن الكبرياء تجمع معنى العظمة والجلال، فتؤكد أن من انفرد بالحكم أعظم من كل ما عبدوه من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص182، تحت عنوان «اختيار صفة ﴿الكبير﴾»","url":""}]},{"id":"s40-149","number":149,"surah":40,"verses":[12],"references":[{"surah":40,"verses":[12]}],"verseLabel":"غافر: 12","question":"لماذا قُدّم ﴿الْعَلِيِّ﴾ على ﴿الْكَبِيرِ﴾ في غافر، وعُكس الترتيب في قوله ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ﴾؟","answer":"في غافر سبق الحديث عن اختصاص الله بالحكم فناسب البدء بالعلو الذي يقهر كل منازع، ثم الكبرياء. وفي الموضع الآخر جاء الكبرياء بعد إحاطة العلم لتقرير عظمة الذات، ثم ختم بالتعالي عن الشركاء والنقائص.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص183، تحت عنوان «نكتة التقديم والتأخير بين الوصفين»","url":""}]},{"id":"s40-24","number":24,"surah":40,"verses":[13],"references":[{"surah":40,"verses":[13]}],"verseLabel":"غافر: 13","question":"ما سر الجمع بين إراءة الله آياته وإنزال الرزق من السماء؟","answer":"إراءة الآيات تقيم دلائل الهداية، وإنزال الرزق يحفظ حياة الأبدان. فاجتمع ما يصلح الدين وما تقوم به الحياة، ليكون البرهان والامتنان داعيين إلى توحيد المنعم وإخلاص العبادة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص189–190، تحت عنوان «مناسبة العطف بين الجملتين»","url":""}]},{"id":"s40-25","number":25,"surah":40,"verses":[13],"references":[{"surah":40,"verses":[13]}],"verseLabel":"غافر: 13","question":"ما دلالة تسمية المطر النازل من السماء ﴿رِزْقًا﴾؟","answer":"المطر سبب لما يرزق به الناس من نبات وأقوات، فسمي باسم نتيجته على المجاز المرسل. وبذلك يبرز التعبير النعمة المقصودة من نزوله، فيدعو إلى شكر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص191–192، تحت عنوان «بلاغة المجاز المرسل»","url":""}]},{"id":"s40-26","number":26,"surah":40,"verses":[14],"references":[{"surah":40,"verses":[14]}],"verseLabel":"غافر: 14","question":"ماذا يفيد قوله ﴿وَلَوْ كَرِهَ الْكَافِرُونَ﴾ بعد الأمر بإخلاص الدين لله؟","answer":"يفيد أن إخلاص العبادة لله واجب ثابت في كل حال، لا يوقفه كره الكافرين ولا يعطل حكمه؛ فجاءت ﴿لو﴾ لتقرير المضي في التوحيد حتى مع تحقق أشد الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص201، تحت عنوان «نوع (لو) ومعناها»","url":""}]},{"id":"s40-27","number":27,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"ما دلالة تتابع الأوصاف ﴿رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ﴾؟","answer":"يجري الوصفان في نسق تعداد يكشف رفعة الله وعظمة ملكه مع وحدة الموصوف؛ فكل خبر يضيف وجهًا من الجلال من غير حاجة إلى تكرار اسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص208، تحت عنوان «بلاغة نمط التعديد»","url":""}]},{"id":"s40-150","number":150,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"لماذا تأخر قوله ﴿يُلْقِي الرُّوحَ مِنْ أَمْرِهِ﴾ بعد ﴿رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ﴾؟","answer":"لأن ذكر العزة والملك يمهد لأعظم نعمه على العباد: الوحي؛ فتأخير إلقاء الروح ينقل السياق من صفات الجلال إلى أثر الرحمة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص210، تحت عنوان «نكتة تأخير الخبر الثالث ﴿يلقي الروح﴾»","url":""}]},{"id":"s40-28","number":28,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"لماذا عُدّي إلقاء الوحي بـ﴿عَلَى﴾ في قوله ﴿يُلْقِي الرُّوحَ مِنْ أَمْرِهِ عَلَى مَنْ يَشَاءُ﴾؟","answer":"لتصوير الوحي نازلًا من العلو بقوة وثبات على من اصطفاه الله، وفيه تشريف للمتلقي وإيحاء بثقل الأمانة الملقاة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص213–214، تحت عنوان «نكتة تعدية فعل الإلقاء بحرف الاستعلاء»","url":""}]},{"id":"s40-29","number":29,"surah":40,"verses":[15,16],"references":[{"surah":40,"verses":[15,16]}],"verseLabel":"غافر: 15–16","question":"لماذا سُمّيت القيامة ﴿يَوْمَ التَّلَاقِ﴾؟","answer":"لأنه اليوم الذي يلتقي فيه الخلق جميعًا، ويلتقي العامل بعمله والظالم بالمظلوم؛ فالإضافة تختصر مشاهد الاجتماع والحساب في اسم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص216، تحت عنوان «فائدة الإضافة»","url":""}]},{"id":"s40-151","number":151,"surah":40,"verses":[15,16],"references":[{"surah":40,"verses":[15,16]}],"verseLabel":"غافر: 15–16","question":"ما الصورة في وصف الخلق يوم القيامة بأنهم ﴿بَارِزُونَ﴾؟","answer":"تصورهم خارجين مكشوفين في فضاء لا يسترهم شيء، ظاهرة أجسادهم وأعمالهم وأسرارهم أمام الله؛ فلا ملجأ ولا خفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص218–219، تحت عنوان «بلاغة استعمال مفردة ﴿بارزون﴾ بين الحقيقة والكناية»","url":""}]},{"id":"s40-30","number":30,"surah":40,"verses":[16],"references":[{"surah":40,"verses":[16]}],"verseLabel":"غافر: 16","question":"ما غرض السؤال ﴿لِمَنِ الْمُلْكُ الْيَوْمَ﴾؟","answer":"هو استفهام تقريري يعلن ظهور سلطان الله وانقطاع دعاوى الملك كلها؛ فالمشهد نفسه يحمل الخلق على الإقرار بأنه لا ملك إلا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص224–225، تحت عنوان «بلاغة الاستفهام المجازي وغرضه»","url":""}]},{"id":"s40-152","number":152,"surah":40,"verses":[16],"references":[{"surah":40,"verses":[16]}],"verseLabel":"غافر: 16","question":"لماذا ذُكر جواب السؤال ﴿لِلَّهِ﴾ مع أن الجواب معلوم؟","answer":"ليحسم التقرير ويعين الحقيقة التي لا جواب سواها، ويزيد توبيخ من نازعوا الله ملكه في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص226، تحت عنوان «نكتة ذكر جواب الاستفهام التقريري»","url":""}]},{"id":"s40-31","number":31,"surah":40,"verses":[17],"references":[{"surah":36,"verses":[54]},{"surah":40,"verses":[17]}],"verseLabel":"غافر: 17؛ يس: 54","question":"لماذا قيل ﴿الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ﴾؟","answer":"تفيد ﴿كل﴾ شمول الجزاء لجميع النفوس بلا استثناء ولا إهمال؛ مؤمنة أو كافرة، مطيعة أو عاصية، على قدر ما كسبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص231، تحت عنوان «نكتة دخول ﴿كل﴾»","url":""}]},{"id":"s40-32","number":32,"surah":40,"verses":[17],"references":[{"surah":40,"verses":[17]}],"verseLabel":"غافر: 17","question":"لماذا تكرر لفظ ﴿الْيَوْمَ﴾ في ﴿الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ﴾ و﴿لَا ظُلْمَ الْيَوْمَ﴾؟","answer":"الأول يعيّن يوم الجزاء الموعود ويستحضره كأنه حاضر، والثاني يثبت اختصاص ذلك المقام بظهور العدل التام ونفي الظلم؛ فالتكرار يرسخ رهبة اليوم وأمن عدله معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص230–235، تحت عنوان «معنى (أل) في ﴿اليوم﴾»","url":""}]},{"id":"s40-33","number":33,"surah":40,"verses":[18],"references":[{"surah":40,"verses":[18]}],"verseLabel":"غافر: 18","question":"لماذا عُدل عن «يوم القيامة» إلى وصفه بـ﴿الْآزِفَةِ﴾؟","answer":"لإبراز قرب الساعة وشدة دنوها؛ حُذف الموصوف وأقيمت صفته مقامه حتى تبدو القيامة وكأن حقيقتها الملازمة هي الاقتراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص244، تحت عنوان «سر العدول عن ذكر الموصوف»","url":""}]},{"id":"s40-34","number":34,"surah":40,"verses":[18],"references":[{"surah":40,"verses":[18]}],"verseLabel":"غافر: 18","question":"لماذا قُدّم نفي الحميم على نفي الشفيع؟","answer":"لأن الحميم قريب يبادر إلى النصرة من غير طلب، أما الشفيع فلا يتحرك غالبًا إلا بعد سؤال؛ فنُفي الأقرب والأسرع أولًا ثم ما بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص250، تحت عنوان «نكتة تقديم الحميم على الشفيع»","url":""}]},{"id":"s40-153","number":153,"surah":40,"verses":[18],"references":[{"surah":40,"verses":[18]}],"verseLabel":"غافر: 18","question":"لماذا قيل ﴿وَلَا شَفِيعٍ يُطَاعُ﴾؟","answer":"لنفي الشفاعة النافعة من أصلها؛ ليس لهم شفيع مقبول القول، والوصف يزيد اليأس من كل واسطة يرجونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص250–251، تحت عنوان «نكتة وصف الشفيع»","url":""}]},{"id":"s40-35","number":35,"surah":40,"verses":[19],"references":[{"surah":40,"verses":[19]}],"verseLabel":"غافر: 19","question":"ما وجه فرادة التعبير في ﴿يَعْلَمُ خَائِنَةَ الْأَعْيُنِ﴾؟","answer":"تجمع إضافة الخيانة إلى الأعين بين دقة اللفظ وقوة التصوير؛ فهي تستحضر النظرة الخفية التي يحاول صاحبها إخفاءها عمن حوله. وإحاطة العلم بها تقطع توهم أن خفاء الحركة على الناس يجعلها خافية على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص259–260، تحت عنوان «فن الفرائد في قوله: ﴿يعلم خائنة الأعين﴾»","url":""}]},{"id":"s40-36","number":36,"surah":40,"verses":[19],"references":[{"surah":40,"verses":[19]}],"verseLabel":"غافر: 19","question":"ما سر الجمع بين ﴿خَائِنَةَ الْأَعْيُنِ﴾ و﴿مَا تُخْفِي الصُّدُورُ﴾؟","answer":"ليجمع علم الله أخفى عمل ظاهر وأخفى سر باطن؛ فالنظرة المختلسة لا تفوته، وما يستره القلب لا يخفى عليه، وبذلك يستوي الظاهر والباطن أمام علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص261، تحت عنوان «معنى الواو في قوله: ﴿وما تخفي الصدور﴾»","url":""}]},{"id":"s40-37","number":37,"surah":40,"verses":[20],"references":[{"surah":40,"verses":[20]}],"verseLabel":"غافر: 20","question":"ما دلالة مقابلة ﴿وَاللَّهُ يَقْضِي بِالْحَقِّ﴾ بـ﴿لَا يَقْضُونَ بِشَيْءٍ﴾؟","answer":"تجمع المقابلة كمال حكم الله وعلمه وقدرته، وعجز المعبودات من دونه عن أي حكم أو أثر مهما صغر؛ فتقيم برهان التوحيد بين طرفين واضحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص271، تحت عنوان «بلاغة المقابلة في الآية»","url":""}]},{"id":"s40-38","number":38,"surah":40,"verses":[20],"references":[{"surah":40,"verses":[20]}],"verseLabel":"غافر: 20","question":"لماذا خُتمت الآية بقوله ﴿إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ﴾؟","answer":"لأن من يقضي بالحق لا بد أن يحيط بالأقوال والأعمال؛ فالسميع يعلم ما يقولون والبصير يرى ما يفعلون، بخلاف معبوداتهم التي لا تسمع ولا تبصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص273، تحت عنوان «نكتة ختم الآية الكريمة بالاسمين الجليلين»","url":""}]},{"id":"s40-39","number":39,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"لماذا نُكّرت ﴿قُوَّةً﴾ في وصف الأمم السابقة؟","answer":"للتعظيم والتفخيم؛ كانت لهم قوة ضخمة متنوعة في الأبدان والأموال والعمران، ومع ذلك لم تغن عنهم حين جاء عذاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص283، تحت عنوان «نكتة تنكير ﴿قوة﴾»","url":""}]},{"id":"s40-154","number":154,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"لماذا نُكّرت ﴿آثَارًا﴾ في قوله ﴿وَآثَارًا فِي الْأَرْضِ﴾؟","answer":"للدلالة على كثرة آثارهم وعظمتها وتنوعها من حصون ومدائن ومصانع، فبقي بعضها شاهدًا على قوة زالت ولم تدفع الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص284، تحت عنوان «نكتة تنكير ﴿آثارًا﴾»","url":""}]},{"id":"s40-40","number":40,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"ماذا يفيد ضمير ﴿هُمْ﴾ في قوله ﴿كَانُوا هُمْ أَشَدَّ مِنْهُمْ قُوَّةً﴾؟","answer":"يؤكد أن الأمم السابقة نفسها ـ لا غيرها ـ كانت أشد من المخاطبين، فيقوي التحذير: من هم أعظم قوة أُخذوا ولم يعجزوا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص282، تحت عنوان «نكتة دخول ضمير الفصل ﴿هم﴾»","url":""}]},{"id":"s40-155","number":155,"surah":40,"verses":[21],"references":[{"surah":40,"verses":[21]}],"verseLabel":"غافر: 21","question":"لماذا تكرر وصف الأمم السابقة بالقوة والآثار في موضعين من سورة غافر؟","answer":"ليجعل آثارهم الباقية برهانًا محسوسًا على قوة أصحابها ثم على هلاكهم؛ اختلف تركيب الموضعين بحسب السياق، واتفقا في كسر غرور المكذبين بقوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص76–77، تحت عنوان «بلاغة التشابه اللفظي مع الآية (21) من هذه السورة»","url":""}]},{"id":"s40-41","number":41,"surah":40,"verses":[22],"references":[{"surah":40,"verses":[22]},{"surah":64,"verses":[6]}],"verseLabel":"غافر: 22؛ التغابن: 6","question":"لماذا أُكِّد سبب هلاك الأمم بقوله ﴿ذَلِكَ بِأَنَّهُمْ كَانَتْ تَأْتِيهِمْ رُسُلُهُمْ بِالْبَيِّنَاتِ﴾؟","answer":"ليثبت أن أخذهم لم يكن بلا حجة؛ فقد تكرر مجيء الرسل بالبينات، ثم قابلوا ذلك بالكفر، فكان العذاب نتيجة إصرارهم بعد وضوح الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص290، تحت عنوان «نكتة التوكيد في قوله: ﴿بأنهم﴾»","url":""}]},{"id":"s40-42","number":42,"surah":40,"verses":[22],"references":[{"surah":40,"verses":[22]}],"verseLabel":"غافر: 22","question":"لماذا خُتم أخذ المكذبين بقوله ﴿إِنَّهُ قَوِيٌّ شَدِيدُ الْعِقَابِ﴾؟","answer":"لأن قوته تثبت أنه لا يعجزه أحد، وشدة عقابه تناسب من كفر وأصر بعد مجيء الرسل؛ فالوصفان يعللان سرعة الأخذ وحسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص294، تحت عنوان «نكتة ختم الآية بالاسمين الجليلين»","url":""}]},{"id":"s40-43","number":43,"surah":40,"verses":[23,24],"references":[{"surah":40,"verses":[23,24]}],"verseLabel":"غافر: 23–24","question":"لماذا ذُكر هامان وقارون مع فرعون في مواجهة موسى؟","answer":"لأنهم أبرز أعوان منظومة الكفر: فرعون رأس السلطة، وهامان شريكه في التدبير، وقارون صاحب المال المؤثر؛ فاجتمع الملك والتخطيط والثروة في مقاومة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص302، تحت عنوان «نكتة ذكر (هامان) و(قارون) مع ﴿فرعون﴾»","url":""}]},{"id":"s40-156","number":156,"surah":40,"verses":[23,24],"references":[{"surah":40,"verses":[23,24]}],"verseLabel":"غافر: 23–24","question":"ما دلالة ترتيب ﴿فِرْعَوْنَ وَهَامَانَ وَقَارُونَ﴾؟","answer":"بدأ بفرعون لأنه صاحب الأمر والملك، ثم هامان لقربه منه وتأثيره في القرار، ثم قارون لكونه حليفًا بالمال والمكانة؛ فجاء الترتيب بحسب قوة الموقع في المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص302، تحت عنوان «دلالة الترتيب بين هذه الأسماء»","url":""}]},{"id":"s40-44","number":44,"surah":40,"verses":[24],"references":[{"surah":40,"verses":[24]}],"verseLabel":"غافر: 24","question":"لماذا نكّروا ﴿سَاحِرٌ﴾ في اتهام موسى؟","answer":"للتقليل من شأنه وجعله واحدًا من السحرة، وصرف الأنظار عن المعجزة الظاهرة التي لا يقدر عليها السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص302–303، تحت عنوان «نكتة الاتهام بالسحر، وتنكير ﴿ساحر﴾»","url":""}]},{"id":"s40-157","number":157,"surah":40,"verses":[24],"references":[{"surah":40,"verses":[24]}],"verseLabel":"غافر: 24","question":"لماذا وصفوه بـ﴿كَذَّابٌ﴾ بصيغة المبالغة؟","answer":"ليصوروا ـ زورًا ـ أن الكذب عادته المتكررة، لا خبرًا واحدًا؛ فبالغوا في التشويه لأنهم عجزوا عن مواجهة حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص303، تحت عنوان «نكتة المبالغة في قولهم: ﴿كذاب﴾»","url":""}]},{"id":"s40-45","number":45,"surah":40,"verses":[25],"references":[{"surah":40,"verses":[25]}],"verseLabel":"غافر: 25","question":"لماذا قُيِّد قتل الأبناء بأنهم أبناء ﴿الَّذِينَ آمَنُوا مَعَهُ﴾؟","answer":"لبيان أن المقصود معاقبة المؤمنين بموسى والانتقام منهم في أبنائهم؛ فالقتل صار أداة لترهيب الآباء ومحاربة الدعوة، لا إجراءً عامًا منفصلًا عن إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص309، تحت عنوان «غرض التعبير بالاسم الموصول وصلته ﴿الذين آمنوا معه﴾»","url":""}]},{"id":"s40-46","number":46,"surah":40,"verses":[26],"references":[{"surah":40,"verses":[26]}],"verseLabel":"غافر: 26","question":"لماذا قال فرعون لقومه ﴿أَنْ يُبَدِّلَ دِينَكُمْ﴾ فأضاف الدين إليهم؟","answer":"تظاهر بالغيرة على عقيدتهم واستثار خوفهم من زوال مألوفهم ليكسب موافقتهم على قتل موسى؛ فجعل نفسه حارسًا لدينهم وهو المستبد بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص323، تحت عنوان «نكتة إضافة الدين إلى ضمير المخاطبين»","url":""}]},{"id":"s40-47","number":47,"surah":40,"verses":[26],"references":[{"surah":40,"verses":[26]}],"verseLabel":"غافر: 26","question":"ما دلالة تقديم تبديل الدين على إظهار الفساد في حجة فرعون؟","answer":"قدم أمر الدين لأنه أساس اجتماع القوم وما يرونه صلاحًا لنظامهم، ثم ذكر فساد الأرض ليضم إليه الخوف على حياتهم. بهذا الترتيب يصوغ فرعون حجته بما يستميلهم، مع أن دعواه الحرص على الدين تخدم بقاء سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص327، تحت عنوان «نكتة تقديم خوفه من تبديله الدين على إظهاره الفساد»","url":""}]},{"id":"s40-48","number":48,"surah":40,"verses":[27],"references":[{"surah":40,"verses":[27]}],"verseLabel":"غافر: 27","question":"ما سر الجمع بين ﴿بِرَبِّي وَرَبِّكُمْ﴾ في استعاذة موسى؟","answer":"إضافة الرب إلى موسى تستحضر رعايته وحفظه، ثم إضافته إلى المخاطبين تقرر أنه ربهم أيضًا وإن أنكروه؛ فمن اعتصم برب الجميع لا تخرجه قدرة فرعون من حمايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص334، تحت عنوان «معنى الواو في قوله: ﴿وربكم﴾ ونكتة الإضافة فيه»","url":""}]},{"id":"s40-49","number":49,"surah":40,"verses":[27],"references":[{"surah":40,"verses":[27]}],"verseLabel":"غافر: 27","question":"لماذا استعاذ موسى من ﴿كُلِّ مُتَكَبِّرٍ﴾ ولم يخص فرعون بالذكر؟","answer":"لتعم الاستعاذة كل من اتصف بالتكبر وأراد الشر، فيظهر أن الخطر صفة وطريق لا شخص واحد، ويدخل فيها فرعون وهامان وغيرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص335، تحت عنوان «نكتة دخول ﴿كل﴾»","url":""}]},{"id":"s40-158","number":158,"surah":40,"verses":[27],"references":[{"surah":40,"verses":[27]}],"verseLabel":"غافر: 27","question":"لماذا خُصّ المتكبر بأنه ﴿لَا يُؤْمِنُ بِيَوْمِ الْحِسَابِ﴾؟","answer":"لأن الإيمان بالحساب أقوى ما يردع عن البطش؛ فإذا جحده المتكبر زال عنه خوف الجزاء، فتمادى في الظلم والعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص338، تحت عنوان «نكتة الاقتصار على عدم الإيمان بيوم الحساب»","url":""}]},{"id":"s40-50","number":50,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا عُرِّف مؤمن آل فرعون بأنه ﴿رَجُلٌ﴾ من غير ذكر اسمه؟","answer":"لإبراز رجولته وشجاعته في الموقف، فالعبرة بما قام به من نصرة الحق لا باسمه؛ وتنكير اللفظ يعظم قدر هذا الموقف المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص342، تحت عنوان «دلالة التعبير بلفظ ﴿رجل﴾ ونكتة تنكيره»","url":""}]},{"id":"s40-159","number":159,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا قُدِّم وصفه بأنه ﴿مِنْ آلِ فِرْعَوْنَ﴾ على قوله ﴿يَكْتُمُ إِيمَانَهُ﴾؟","answer":"لتثبت نسبته إلى آل فرعون قبل بيان إيمانه الخفي، فيعظم أثر شهادته عليهم؛ فهو رجل من داخل جماعتهم لا وافد من خصومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص343–344، تحت عنوان «نكتة تقديم الوصف ﴿من آل فرعون﴾ على قوله: ﴿يكتم إيمانه﴾»","url":""}]},{"id":"s40-160","number":160,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا قيل عن مؤمن آل فرعون ﴿يَكْتُمُ إِيمَانَهُ﴾ بالفعل المضارع؟","answer":"لتصوير كتمان يتجدد ويستمر تحت ضغط الخوف، حتى جاءت اللحظة الحاسمة فتكلم؛ فالمضارع يحضر حاله وهو يوازن بين إخفاء إيمانه وإعلان النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص345، تحت عنوان «نكتة العدول عن الوصف بالمفرد إلى الوصف بالجملة الفعلية»","url":""}]},{"id":"s40-51","number":51,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا بنى مؤمن آل فرعون حجته على احتمالين: ﴿إِنْ يَكُ كَاذِبًا﴾ و﴿إِنْ يَكُ صَادِقًا﴾؟","answer":"ليخاطب قومه بإنصاف يفتح لهم باب التفكير: إن كذب فعليه كذبه، وإن صدق نالهم بعض ما يتوعدهم به. وقدّم ما يوافق ظنهم ليطمئنوا إلى عدله ثم ينتبهوا إلى الخطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص354–355، تحت عنوان «بلاغة التعبير بالجمل الشرطية»","url":""}]},{"id":"s40-161","number":161,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا قال ﴿يُصِبْكُمْ بَعْضُ الَّذِي يَعِدُكُمْ﴾ ولم يقل «كل»؟","answer":"لأن وقوع بعض الوعيد وحده يكفي لإبطال اطمئنانهم ودعوتهم إلى الحذر، وفي اللفظ إنصاف ولطف في المحاورة يبعدانه عن التحيز لموسى في ظاهر خطابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص360، تحت عنوان «نكتة ذكر لفظة ﴿بعض﴾»","url":""}]},{"id":"s40-52","number":52,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"ما سر تقديم احتمال كذب موسى على احتمال صدقه؟","answer":"قدم فرض الكذب ليبعد عنهم ظن أنه يريد الانتصار لموسى، ويظهر بمظهر المهتم بأمر قومه. وهذا التلطف يهيئهم لسماع فرض الصدق وما يترتب عليه من خطر عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص357، تحت عنوان «علة تقديم فرضية الكذب على الصدق»","url":""}]},{"id":"s40-53","number":53,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"لماذا ذُيِّلت حجة مؤمن آل فرعون بقوله ﴿إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ مُسْرِفٌ كَذَّابٌ﴾؟","answer":"لتقرر قاعدة تحسم الاحتمال: صاحب الإسراف والكذب لا يؤيده الله بالبينات ولا يهديه إلى هذا البيان؛ وفيها تقوية ضمنية لصدق موسى بعد ظهور حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص362–363، تحت عنوان «بلاغة التذييل في جملة الفاصلة، ونكتة فصلها»","url":""}]},{"id":"s40-162","number":162,"surah":40,"verses":[28],"references":[{"surah":40,"verses":[28]}],"verseLabel":"غافر: 28","question":"بمن عرّض مؤمن آل فرعون في قوله ﴿مُسْرِفٌ كَذَّابٌ﴾؟","answer":"عرّض بفرعون من غير مواجهة مباشرة؛ فإسرافه في القتل والفساد، وكذبه في دعوى الربوبية، يجعلان الوصفين ألصق به من موسى الذي جاء بالبينات.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص368، تحت عنوان «بلاغة التعريض في التعبير بالوصفين»","url":""}]},{"id":"s40-54","number":54,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"لماذا كرر مؤمن آل فرعون نداء ﴿يَا قَوْمِ﴾ في خطابه؟","answer":"ليجدد تنبيههم كلما انتقل إلى حجة أو تحذير جديد، ويؤكد قربه منهم وإخلاص نصحه، ولا سيما بعد مقاطعة فرعون له ومحاولة صرفهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص391، تحت عنوان «غرض تكرار النداء بـ﴿يا قوم﴾»","url":""}]},{"id":"s40-55","number":55,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"ما غرض سؤال المؤمن ﴿فَمَنْ يَنْصُرُنَا مِنْ بَأْسِ اللَّهِ إِنْ جَاءَنَا﴾؟","answer":"هو إنكار أن يقدر أحد على دفع عذاب الله؛ ساقه في صورة سؤال يهز ثقتهم بالملك والقوة ويفتح لهم فرصة النجاة بالتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص377، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s40-163","number":163,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"لماذا قال المؤمن ﴿يَنْصُرُنَا﴾ و﴿جَاءَنَا﴾ فأدخل نفسه مع قومه؟","answer":"ليبعد عنهم التهمة ويطمئن قلوبهم بأنه شريكهم في المصير، وأن تحذيره نصيحة لنفسه ولهم لا شماتة أو تعاليًا عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص379–380، تحت عنوان «بلاغة استعمال ضمير المتكلمين في ﴿ينصرنا﴾ و﴿جاءنا﴾»","url":""}]},{"id":"s40-56","number":56,"surah":40,"verses":[30,31],"references":[{"surah":40,"verses":[30,31]}],"verseLabel":"غافر: 30–31","question":"لماذا عبّر المؤمن عن سيرة المكذبين السابقة بلفظ ﴿دَأْبِ﴾؟","answer":"لأن الدأب عادة تتكرر وتستمر؛ فتكذيب الأمم وعنادها لم يكونا حادثة عابرة، ولذلك استحقوا جزاءً من جنس الطريق الذي لزموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص394، تحت عنوان «دلالة التعبير بالدأب ونوع الإضافة فيه»","url":""}]},{"id":"s40-57","number":57,"surah":40,"verses":[31],"references":[{"surah":40,"verses":[31]}],"verseLabel":"غافر: 31","question":"لماذا قيل ﴿قَوْمِ نُوحٍ﴾ ثم ذُكرت عاد وثمود من غير لفظ «قوم»؟","answer":"لأن عادًا وثمود اسمان لقبيلتين مشهورتين، أما نوح فهو اسم النبي فاحتاج إلى لفظ ﴿قوم﴾ لتعريف أمته به؛ فدل التعبير على المقصود بأوجز طريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص395–396، تحت عنوان «نكتة ذكر ﴿قوم﴾ مع ﴿نوح﴾ دون البقية»","url":""}]},{"id":"s40-164","number":164,"surah":40,"verses":[31],"references":[{"surah":40,"verses":[31]}],"verseLabel":"غافر: 31","question":"لماذا رُتِّب ذكر قوم نوح ثم عاد ثم ثمود؟","answer":"لترتيبهم بحسب تعاقبهم في التاريخ: بدأ بأقدم الأمم المذكورة ثم بمن تلاها، فتتابعت أمام السامع أمثلة سنة واحدة في المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص396، تحت عنوان «دلالة الترتيب بين الأقوام المذكورين»","url":""}]},{"id":"s40-58","number":58,"surah":40,"verses":[32,33],"references":[{"surah":40,"verses":[32,33]}],"verseLabel":"غافر: 32–33","question":"لماذا سُمّيت القيامة ﴿يَوْمَ التَّنَادِ﴾؟","answer":"لما يمتلئ به ذلك اليوم من نداءات الفزع والاستغاثة والتلاوم بين أهل النار؛ فالاسم يسمع القارئ صخب المشهد قبل أن يراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص408، تحت عنوان «نكتة التعبير بـ﴿يوم التناد﴾»","url":""}]},{"id":"s40-165","number":165,"surah":40,"verses":[32,33],"references":[{"surah":40,"verses":[32,33]}],"verseLabel":"غافر: 32–33","question":"لماذا أعقب ﴿يَوْمَ التَّنَادِ﴾ بقوله ﴿يَوْمَ تُوَلُّونَ مُدْبِرِينَ﴾؟","answer":"لينتقل من اسم اليوم الذي يوحي بالصياح إلى صورة حالهم فيه وهم يفرون مذعورين، ثم يرتدون إلى الجهة التي فروا منها؛ فتتدرج الصورة من الصوت إلى الحركة والعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص409–410، تحت عنوان «بلاغة التدرج في البيان بـ﴿يوم تولون مدبرين﴾»","url":""}]},{"id":"s40-59","number":59,"surah":40,"verses":[33],"references":[{"surah":40,"verses":[33]}],"verseLabel":"غافر: 33","question":"لماذا جُمع بين نفي العاصم من الله ونفي الهادي لمن أضله الله؟","answer":"ليربط التحذير بالدعوة: لا أحد يحمي من بأس الله إذا جاء، ولا أحد يرد إلى الهدى من أعرض عنه حتى أضله الله؛ فبادروا إلى قبول الهدى قبل فوات الحماية والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص414، تحت عنوان «توجيه العطف بالواو في جملة الفاصلة»","url":""}]},{"id":"s40-60","number":60,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"لماذا ذكّر مؤمن آل فرعون قومه بيوسف تحديدًا؟","answer":"لأن يوسف معروف في تاريخ مصر، وارتبط اسمه بالبينات والرخاء والنجاة من القحط؛ فذكّرهم برسول عرفوا أثره ليحتج عليهم من تاريخهم القريب منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص425، تحت عنوان «نكتة تذكيره لهم بيوسف عليه السلام»","url":""}]},{"id":"s40-166","number":166,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"لماذا حكى عنهم قولهم بعد يوسف ﴿لَنْ يَبْعَثَ اللَّهُ مِنْ بَعْدِهِ رَسُولًا﴾ بتنكير ﴿رَسُولًا﴾؟","answer":"لإظهار أنهم أنكروا بعثة أي رسول بعد يوسف، لا رسولًا بعينه؛ فالتنكير في سياق النفي يكشف عموم إنكارهم واستمرار شكهم في أصل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص431، تحت عنوان «نكتة تنكير ﴿رسولًا﴾»","url":""}]},{"id":"s40-61","number":61,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"ما سر التعبير بـ﴿حَتَّى إِذَا هَلَكَ﴾ عن وفاة يوسف؟","answer":"يحكي المؤمن الوفاة بلفظ الهلاك ليوهم قومه أنه لا يعظم يوسف تعظيمًا يحجب عنه النظر، فيبعد عن نصحه تهمة الانحياز لشخص النبي. وبذلك يقرب كلامه من صورة النصح المجرد والنظر في العاقبة، لا الانتقاص من حقيقة مقام يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص430، تحت عنوان «نكتة التعبير بالهلاك»","url":""}]},{"id":"s40-62","number":62,"surah":40,"verses":[34],"references":[{"surah":40,"verses":[34]}],"verseLabel":"غافر: 34","question":"ما دلالة وصف المرتاب بأنه ﴿مُسْرِفٌ مُرْتَابٌ﴾؟","answer":"يجمع الوصفان مجاوزة الحد والارتياب في الحق، ويقدم الإسراف لأنه يفضي إلى الشك ويغذيه. فليس الارتياب هنا نظرًا منصفًا مجردًا، بل ثمرة موقف يتجاوز صاحبه حد الاعتدال والإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص433–434، تحت عنوان «نكتة تقديم ﴿مسرف﴾ على ﴿مرتاب﴾، مع تنكيرهما»","url":""}]},{"id":"s40-63","number":63,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"لماذا قيل إن جدالهم ممقوت ﴿عِنْدَ اللَّهِ وَعِنْدَ الَّذِينَ آمَنُوا﴾؟","answer":"ليبين أن المؤمنين وافقوا بحكم إيمانهم ما يحبه الله ويبغضه، وأن بصيرتهم جعلتهم ينكرون الجدال الباطل كما هو ممقوت عنده سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص439، تحت عنوان «نكتة عطف ﴿الذين آمنوا﴾»","url":""}]},{"id":"s40-64","number":64,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"لماذا جُمع في وصف القلب بين ﴿مُتَكَبِّرٍ﴾ و﴿جَبَّارٍ﴾؟","answer":"لأن التكبر استعلاء يمنع قبول الحق، والتجبر قهر يحمل الناس على الباطل؛ فاجتمع فساد صاحبه في نفسه وفساده في معاملته للخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص442–443، تحت عنوان «نكتة وصفهم بهذين الوصفين»","url":""}]},{"id":"s40-167","number":167,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"لماذا قُدِّم وصف ﴿مُتَكَبِّرٍ﴾ على ﴿جَبَّارٍ﴾؟","answer":"لأن التكبر الباطن عن قبول الحق هو السبب، والتجبر الظاهر على الناس أثره ونتيجته؛ فقدم الأصل على ما ينشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص443، تحت عنوان «نكتة تقديم صفة التكبر على التجبر»","url":""}]},{"id":"s40-65","number":65,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36–37","question":"لماذا سمّى فرعون أبواب السماوات ﴿الْأَسْبَابَ﴾؟","answer":"لأن السبب ما يُتوصّل به إلى غاية، فصوّر أبواب السماوات طرقًا يريد بلوغها، مبالغًا في إيهام قومه بأنه يملك وسائل التحقق مما قاله موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص452، تحت عنوان «دلالة التعبير بـ﴿الأسباب﴾ مادة وصيغة»","url":""}]},{"id":"s40-168","number":168,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36–37","question":"ما الذي يصوره اختيار فرعون فعل ﴿أَطَّلِعَ﴾؟","answer":"يصوره متكلفًا الصعود والظهور على أمر غيبي، فيوهم قومه ببحث جاد، مع أن صيغة الفعل تكشف مبالغته في ادعاء القدرة على كشف ما وراء الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص453، تحت عنوان «دلالة التعبير بـ(أطلع) مادة وصيغة»","url":""}]},{"id":"s40-169","number":169,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36–37","question":"لماذا قال فرعون ﴿إِلَهِ مُوسَى﴾ فأضاف الإله إلى موسى؟","answer":"استهزاءً وإنكارًا أن يكون إله موسى إلهًا له وللناس؛ حصر النسبة في موسى ليبقي لنفسه دعوى الربوبية ويصور رسالة التوحيد كأنها اعتقاد خاص بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص454، تحت عنوان «نكتة إضافة الـ﴿إله﴾ إلى ﴿موسى﴾»","url":""}]},{"id":"s40-66","number":66,"surah":40,"verses":[37],"references":[{"surah":40,"verses":[37]}],"verseLabel":"غافر: 37","question":"لماذا كثّف فرعون المؤكدات في قوله ﴿وَإِنِّي لَأَظُنُّهُ كَاذِبًا﴾؟","answer":"ليبالغ في إقناع قومه بكذبة يريد تثبيتها، ويزيل ما قد يثيره طلب بناء الصرح من توهم أنه صدق موسى أو صار يشك في موقفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص455، تحت عنوان «فائدة تتابع المؤكدات في ﴿وإني لأظنه كاذبًا﴾»","url":""}]},{"id":"s40-170","number":170,"surah":40,"verses":[37],"references":[{"surah":40,"verses":[37]}],"verseLabel":"غافر: 37","question":"ما وجه الاحتراس في قوله ﴿وَإِنِّي لَأَظُنُّهُ كَاذِبًا﴾؟","answer":"لأن طلبه بلوغ أسباب السماوات قد يوحي بأنه يريد التحقق من صدق موسى؛ فاحترس بإعلان ظنه الكذب حتى يبقي قومه على الجحود ولا يفهموا من مشروعه ميلًا إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص456، تحت عنوان «بلاغة الاحتراس في قوله: ﴿وإني لأظنه كاذبًا﴾»","url":""}]},{"id":"s40-67","number":67,"surah":40,"verses":[29,38],"references":[{"surah":40,"verses":[29,38]}],"verseLabel":"غافر: 29؛ غافر: 38","question":"بماذا عرّض المؤمن حين قال ﴿أَهْدِكُمْ سَبِيلَ الرَّشَادِ﴾؟","answer":"عرّض بأن سبيل فرعون هو طريق الغي والضلال؛ قابل دعواه باللفظ نفسه، ثم أقام على رشاده دليلًا من حقيقة الدنيا والآخرة، من غير مواجهة فظة تصد قومه عن سماعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص470، تحت عنوان «بلاغة التعريض في الآية»","url":""}]},{"id":"s40-68","number":68,"surah":40,"verses":[39],"references":[{"surah":40,"verses":[39]}],"verseLabel":"غافر: 39","question":"لماذا سُمّيت الآخرة ﴿دَارُ الْقَرَارِ﴾؟","answer":"لأنها وحدها موطن الاستقرار الذي لا يزول ولا يضطرب؛ وإضافة الدار إلى القرار تخصها بالثبات الدائم في مقابل متاع الدنيا العابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص474، تحت عنوان «نكتة إضافة ﴿دار﴾ إلى ﴿القرار﴾»","url":""}]},{"id":"s40-69","number":69,"surah":40,"verses":[40],"references":[{"surah":40,"verses":[40]}],"verseLabel":"غافر: 40","question":"لماذا قُيد جزاء السيئة بقوله ﴿إِلَّا مِثْلَهَا﴾؟","answer":"ليقرر كمال العدل؛ فلا يزاد في عقوبة السيئة على قدرها، ولا يتجاوز الجزاء حد الفعل الذي استوجبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص477، تحت عنوان «دلالة التعبير بالمثلية في ﴿إلا مثلها﴾»","url":""}]},{"id":"s40-171","number":171,"surah":40,"verses":[40],"references":[{"surah":40,"verses":[40]}],"verseLabel":"غافر: 40","question":"ما الذي تصوره عبارة ﴿يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ﴾؟","answer":"تصور سعة نعيم الجنة واستمراره بلا نفاد ولا تضييق، فتقابل عدل العقوبة المحدودة بفضل المثوبة غير المحدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص484، تحت عنوان «بلاغة الكناية في قوله: ﴿بغير حساب﴾»","url":""}]},{"id":"s40-70","number":70,"surah":40,"verses":[40],"references":[{"surah":40,"verses":[40]}],"verseLabel":"غافر: 40","question":"لماذا صُرِّح بالذكر والأنثى في وعد العامل الصالح؟","answer":"يدفع التصريح توهم اختصاص الوعد بأحد الجنسين، ويؤكد أن الذكر والأنثى سواء في أصل قبول العمل الصالح وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص479، تحت عنوان «فائدة قوله: ﴿من ذكر أو أنثى﴾»","url":""}]},{"id":"s40-71","number":71,"surah":40,"verses":[41],"references":[{"surah":40,"verses":[41]}],"verseLabel":"غافر: 41","question":"لماذا قال مؤمن آل فرعون ﴿أَدْعُوكُمْ إِلَى النَّجَاةِ﴾ ولم يقل «إلى الجنة»؟","answer":"لأن النجاة تستثير غريزة الخلاص من الهلاك، وتشمل الفوز بالجنة والسلامة من النار، فهي أبلغ في تحريك قومه إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص491–492، تحت عنوان «سر العدول عن (الجنة) إلى ﴿النجاة﴾»","url":""}]},{"id":"s40-172","number":172,"surah":40,"verses":[41],"references":[{"surah":40,"verses":[41]}],"verseLabel":"غافر: 41","question":"كيف كانت دعوة قومه له ﴿إِلَى النَّارِ﴾ وهم لم يسموها كذلك؟","answer":"عبّر بمآل دعوتهم؛ فدعوتهم إلى الشرك طريق يفضي إلى النار، فكشف النتيجة المخيفة الكامنة وراء ما يعرضونه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص493، تحت عنوان «بلاغة المجاز في ﴿النار﴾»","url":""}]},{"id":"s40-72","number":72,"surah":40,"verses":[42],"references":[{"surah":40,"verses":[42]}],"verseLabel":"غافر: 42","question":"لماذا نفى المؤمن علمه بما يدعونه إلى الشرك به؟","answer":"لأن نفي العلم هنا نفي لأي حجة يمكن أن تثبت لذلك الشريك وجودًا أو استحقاقًا للعبادة؛ فالعقيدة لا تقوم بغير برهان، وغياب البرهان يكشف بطلان دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص498، تحت عنوان «سر التعبير بنفي العلم دون غيره»","url":""}]},{"id":"s40-73","number":73,"surah":40,"verses":[42],"references":[{"surah":40,"verses":[42]}],"verseLabel":"غافر: 42","question":"لماذا ختم المؤمن دعوته إلى الله باسمي ﴿الْعَزِيزِ الْغَفَّارِ﴾؟","answer":"ليجمع التخويف والترغيب: العزيز قادر على قهر الشرك وأهله، والغفار يفتح للمقلع عنه باب المغفرة؛ فاجتماعهما أليق بمقام الدعوة والإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص500، تحت عنوان «بلاغة التعبير بـ﴿العزيز الغفار﴾ دون غيرهما»","url":""}]},{"id":"s40-74","number":74,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا قال المؤمن ﴿تَدْعُونَنِي إِلَيْهِ﴾ بحرف ﴿إِلَى﴾؟","answer":"لأن دعوتهم غايتها حمله على الوصول إلى عبادة الشريك؛ فصور الشرك كوجهة يريدون سوقه إليها، مقابل دعوته إياهم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص504، تحت عنوان «سر التعبير بـ (إلى) دون اللام»","url":""}]},{"id":"s40-173","number":173,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا نُفيت عن الشريك ﴿دَعْوَةٌ﴾ لا مجرد الاستجابة؟","answer":"للمبالغة في نفي كل نفع يرجى منه؛ فليس له دعاء مستجاب في الدنيا ولا في الآخرة، ولا يستحق أصلًا أن يُدعى أو يُقصد بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص505، تحت عنوان «سر التعبير بالدعوة دون الاستجابة»","url":""}]},{"id":"s40-75","number":75,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا عُطف ﴿وَأَنَّ مَرَدَّنَا إِلَى اللَّهِ﴾ بعد نفي دعوة الشركاء؟","answer":"لينتقل من إبطال ما يرجى من الشركاء إلى إثبات المرجع الحقيقي للحساب والجزاء؛ فيظهر الفرق بين عاجز لا يستجيب ورب يملك المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص507، تحت عنوان «بلاغة عطف ﴿وأن مردنا إلى الله﴾»","url":""}]},{"id":"s40-174","number":174,"surah":40,"verses":[43],"references":[{"surah":40,"verses":[43]}],"verseLabel":"غافر: 43","question":"لماذا قال المؤمن ﴿مَرَدَّنَا﴾ بالجمع ولم يقل «مردي»؟","answer":"ليشمل نفسه وقومه جميعًا في الرجوع إلى الله، فيشعرهم أن التحذير نصح مشترك لا خصومة أو تشفٍ، وأن الحساب ينتظر الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص508، تحت عنوان «سر التعبير بالجمع ﴿مردنا﴾ دون الإفراد (مردي)»","url":""}]},{"id":"s40-76","number":76,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"متى سيتذكر قوم المؤمن قوله في ﴿فَسَتَذْكُرُونَ مَا أَقُولُ لَكُمْ﴾؟","answer":"سيتذكرونه حين يعاينون العذاب الذي حذرهم منه، فلا يعود التذكر نافعًا؛ وصيغة المستقبل تقرب الوعيد وتؤكد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص514–515، تحت عنوان «غرض الإخبار بـ﴿فستذكرون﴾»","url":""}]},{"id":"s40-175","number":175,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"لماذا أتبع المؤمن إنذار قومه بتفويض أمره إلى الله؟","answer":"لأنه أقام الحجة ثم أعرضوا، فانتقل من مجادلتهم إلى الاعتصام بالله وحمايته، جامعًا تهديدهم بالعاقبة وثقته بمن يحفظه من مكرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص517، تحت عنوان «بلاغة عطف التفويض على ما قبله»","url":""}]},{"id":"s40-77","number":77,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"لماذا قال المؤمن ﴿أُفَوِّضُ أَمْرِي إِلَى اللَّهِ﴾ ولم يقل «أتوكل»؟","answer":"لأن التفويض يدل على تسليم الأمر كله لله والرضا بما يقضيه بعد وقوع الأسباب، فيبلغ غاية الخضوع والاستسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص518، تحت عنوان «سر التعبير بالتفويض دون التوكل»","url":""}]},{"id":"s40-176","number":176,"surah":40,"verses":[44],"references":[{"surah":40,"verses":[44]}],"verseLabel":"غافر: 44","question":"كيف يعلل قوله ﴿إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ﴾ ثقة المؤمن في التفويض؟","answer":"لأن الله يرى حال عبده وحاجته ومكر خصومه، ويعلم ما يصلحه ويحفظه؛ فبصره الشامل هو سند الثقة بتدبيره ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص519–520، تحت عنوان «فائدة تذييل الآية بصفة ﴿بصير﴾ مادة وصيغة»","url":""}]},{"id":"s40-78","number":78,"surah":40,"verses":[45,46],"references":[{"surah":40,"verses":[45,46]}],"verseLabel":"غافر: 45–46","question":"كيف قابل السياق نجاة المؤمن بعقوبة آل فرعون؟","answer":"جاءت وقاية المؤمن ثمرة تفويضه، وجاء إحاطة العذاب بآل فرعون مصداقًا لتحذيره؛ فعاد كل جزاء إلى العمل الذي يناسبه في لف ونشر محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص526، تحت عنوان «بلاغة اللف والنشر»","url":""}]},{"id":"s40-177","number":177,"surah":40,"verses":[45,46],"references":[{"surah":40,"verses":[45,46]}],"verseLabel":"غافر: 45–46","question":"لماذا قيل ﴿وَحَاقَ بِآلِ فِرْعَوْنَ سُوءُ الْعَذَابِ﴾ ولم يقل «نزل»؟","answer":"لأن حاق يصور العذاب محيطًا بهم ملازمًا لا مهرب منه، فيقابل حفظ المؤمن إحاطة العقوبة بأعدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص527، تحت عنوان «سر التعبير بـ (حاق) دون نزل»","url":""}]},{"id":"s40-79","number":79,"surah":40,"verses":[46],"references":[{"surah":40,"verses":[46]}],"verseLabel":"غافر: 46","question":"ماذا يفيد ذكر ﴿غُدُوًّا وَعَشِيًّا﴾ في عرض آل فرعون على النار؟","answer":"يفيد تكرر عرضهم على النار واستمرار عذابهم في البرزخ؛ فذكر طرفي اليوم كناية عن الدوام قبل قيام الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص531، تحت عنوان «بلاغة ذكر الغدو والعشي»","url":""}]},{"id":"s40-178","number":178,"surah":40,"verses":[46],"references":[{"surah":40,"verses":[46]}],"verseLabel":"غافر: 46","question":"كيف تدل جملة ﴿النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا﴾ على عذاب قبل القيامة؟","answer":"لأن العرض جعل واقعًا قبل الأمر يوم تقوم الساعة بإدخالهم أشد العذاب؛ فميز السياق عذاب البرزخ عن عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص534، تحت عنوان «دلالة جملة: ﴿النار يعرضون عليها غدوًا وعشيًا﴾»","url":""}]},{"id":"s40-80","number":80,"surah":40,"verses":[47,48],"references":[{"surah":40,"verses":[47,48]}],"verseLabel":"غافر: 47–48","question":"لماذا ذكّر الضعفاء المستكبرين بتبعيتهم قبل طلب تخفيف النار؟","answer":"ليجعلوا طاعتهم لهم وسيلة تلزمهم بالنصرة، وفي ذلك توبيخ للرؤساء الذين أضلوهم ووعدوهم بالحماية في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص541، تحت عنوان «سر تقديم التبعية على طلب التخفيف»","url":""}]},{"id":"s40-179","number":179,"surah":40,"verses":[47,48],"references":[{"surah":40,"verses":[47,48]}],"verseLabel":"غافر: 47–48","question":"ماذا يكشف جواب المستكبرين ﴿إِنَّا كُلٌّ فِيهَا﴾؟","answer":"يكشف سقوط سلطانهم؛ فالجميع محبوس في النار، ولا يملك المستكبرون دفع شيء عن أنفسهم ولا عن أتباعهم، وقد حكم الله بين العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص546، تحت عنوان «غرض الإخبار بـ﴿إنا كل فيها﴾»","url":""}]},{"id":"s40-81","number":81,"surah":40,"verses":[49],"references":[{"surah":40,"verses":[49]}],"verseLabel":"غافر: 49","question":"لماذا طلب أهل النار من الخزنة أن يدعوا ﴿رَبَّكُمْ﴾؟","answer":"لشعورهم بالبعد والحرمان من الإجابة، فطلبوا وساطة من ظنوهم أقرب إلى الله، وفي إضافة الرب إلى الخزنة إظهار لانكسارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص553–554، تحت عنوان «نكتة تخصيص الخزنة بالخطاب»","url":""}]},{"id":"s40-180","number":180,"surah":40,"verses":[49],"references":[{"surah":40,"verses":[49]}],"verseLabel":"غافر: 49","question":"لماذا اقتصر أهل النار على طلب تخفيف يوم واحد؟","answer":"لشدة يأسهم من الخلاص، فغاية أملهم هدنة قصيرة من العذاب، وهذا يكشف هوله واستمراره فوق احتمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص555، تحت عنوان «سر اقتصارهم على طلب تخفيف يوم من العذاب»","url":""}]},{"id":"s40-82","number":82,"surah":40,"verses":[50],"references":[{"surah":40,"verses":[50]}],"verseLabel":"غافر: 50","question":"لماذا ذكّر الخزنة أهل النار بمجيء الرسل بالبينات؟","answer":"ليقرروا قيام الحجة عليهم وانتفاء العذر؛ فقد رفضوا أسباب النجاة حين كانت متاحة، ثم اعترفوا بذلك بقولهم بلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص559–563، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s40-181","number":181,"surah":40,"verses":[50],"references":[{"surah":40,"verses":[50]}],"verseLabel":"غافر: 50","question":"ما دلالة قول الخزنة لأهل النار ﴿فَادْعُوا﴾؟","answer":"هو أمر تهكم وتيئيس، لا وعد باستجابة؛ أي ادعوا بأنفسكم وقد فات زمن العمل، فلن يغير الدعاء حكمًا استحقوه بعد رد الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص564، تحت عنوان «دلالة الأمر في ﴿فادعوا﴾»","url":""}]},{"id":"s40-83","number":83,"surah":40,"verses":[50],"references":[{"surah":40,"verses":[50]}],"verseLabel":"غافر: 50","question":"لماذا ذُيل أمر أهل النار بالدعاء بقوله ﴿وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ﴾؟","answer":"لدفع توهم أن قول الخزنة ﴿فادعوا﴾ يفتح باب الإجابة؛ فالختام يقرر أن دعاءهم ضائع لا يبلغ غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص565، تحت عنوان «بلاغة الاحتراس أو التذييل في الآية»","url":""}]},{"id":"s40-84","number":84,"surah":40,"verses":[51,52],"references":[{"surah":40,"verses":[51,52]}],"verseLabel":"غافر: 51–52","question":"لماذا جاء وعد النصر مؤكدًا في ﴿إِنَّا لَنَنْصُرُ رُسُلَنَا وَالَّذِينَ آمَنُوا﴾؟","answer":"لتثبيت الرسول والمؤمنين بعد عرض مصارع المكذبين، وإزالة ما قد يداخل القلب من بطء النصر؛ فوعد الله حق لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص572–573، تحت عنوان «فائدة تتابع المؤكدات في قوله: ﴿إنا لننصر﴾»","url":""}]},{"id":"s40-182","number":182,"surah":40,"verses":[51,52],"references":[{"surah":40,"verses":[51,52]}],"verseLabel":"غافر: 51–52","question":"كيف يجمع وعد النصر بين الدنيا ويوم يقوم الأشهاد؟","answer":"نصر الدنيا يشمل ظهور الحجة ووجوه التأييد بحسب الحكمة، ثم يكتمل في الآخرة حين يشهد الخلق ظهور الحق وعقوبة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص574–576، تحت عنوان «دلالة الظرفية وفائدتها في قوله: ﴿في الحياة الدنيا﴾»","url":""}]},{"id":"s40-85","number":85,"surah":40,"verses":[51],"references":[{"surah":40,"verses":[51]}],"verseLabel":"غافر: 51","question":"ما سر تسمية القيامة ﴿يَوْمَ يَقُومُ الْأَشْهَادُ﴾؟","answer":"يسمى اليوم بما يبرز الشهادة العلنية للرسل والمؤمنين وظهور صدقهم. فتكون نصرتهم تشريفًا ظاهرًا أمام الخلائق، وفي المقابل فضيحة للمكذبين؛ وهذا أنسب بمقام الوعد بالنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص576–577، تحت عنوان «غرض التعبير عن اليوم الآخر بهذا الوصف»","url":""}]},{"id":"s40-86","number":86,"surah":40,"verses":[52],"references":[{"surah":40,"verses":[52]}],"verseLabel":"غافر: 52","question":"لماذا سميت النار ﴿سُوءَ الدَّارِ﴾؟","answer":"لأنها أسوأ مأوى يستقر فيه الإنسان؛ فإضافة السوء إلى الدار تجعل القبح ملازمًا لكل ما فيها ولا تترك موضعًا للطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص583، تحت عنوان «نوع الإضافة في قوله: ﴿سوء الدار﴾»","url":""}]},{"id":"s40-183","number":183,"surah":40,"verses":[52],"references":[{"surah":40,"verses":[52]}],"verseLabel":"غافر: 52","question":"لماذا قُدمت اللعنة على ﴿سُوءُ الدَّارِ﴾؟","answer":"ليرتقي الوعيد من الطرد من رحمة الله إلى الاستقرار في أشد العذاب؛ فجمع الحرمان من الرحمة وسوء المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص583، تحت عنوان «نكتة تقديم ﴿اللعنة﴾ على ﴿سوء الدار﴾»","url":""}]},{"id":"s40-87","number":87,"surah":40,"verses":[53,54],"references":[{"surah":40,"verses":[53,54]}],"verseLabel":"غافر: 53–54","question":"لماذا قُدم إيتاء موسى الهدى على توريث بني إسرائيل الكتاب؟","answer":"لأن إيتاء موسى النبوة والكتاب سابق في الوجود، وهو الأصل الذي نشأ عنه انتقال الهداية إلى بني إسرائيل؛ فقدم السبب على نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص590، تحت عنوان «نكتة تقديم الإيتاء على التوريث»","url":""}]},{"id":"s40-184","number":184,"surah":40,"verses":[53,54],"references":[{"surah":40,"verses":[53,54]}],"verseLabel":"غافر: 53–54","question":"ما الصورة في قوله ﴿وَأَوْرَثْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ﴾؟","answer":"صوّر بقاء الكتاب بينهم وانتقاله من جيل إلى جيل بالميراث الذي يستقر في يد الوارث، وفيه امتنان بتمكينهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص590، تحت عنوان «بلاغة الاستعارة في قوله: ﴿وأورثنا﴾»","url":""}]},{"id":"s40-88","number":88,"surah":40,"verses":[54],"references":[{"surah":40,"verses":[54]}],"verseLabel":"غافر: 54","question":"ماذا يجمع وصف الكتاب بأنه ﴿هُدًى وَذِكْرَى﴾؟","answer":"يجمع الإرشاد إلى الحق والتذكير الذي يحفظه حيًا في النفوس، وتنكير الوصفين يعظم قدر هذا الهدى والتذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص592، تحت عنوان «الموقع النحوي لقوله: ﴿هدى وذكرى﴾ ودلالة تنكيرهما»","url":""}]},{"id":"s40-89","number":89,"surah":40,"verses":[55],"references":[{"surah":40,"verses":[55]}],"verseLabel":"غافر: 55","question":"لماذا قُدِّم الصبر على الاستغفار والتسبيح في توجيه النبي ﷺ؟","answer":"لأن الصبر هو الحاجة الأولى أمام أذى المكذبين وانتظار النصر، ثم جاء الاستغفار والتسبيح زادًا يثبت القلب ويستدعي معونة الله حتى يتحقق وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص601–602، تحت عنوان «نكتة تقديم الأمر بالصبر على الأمر بالاستغفار والتسبيح»","url":""}]},{"id":"s40-90","number":90,"surah":40,"verses":[55],"references":[{"surah":40,"verses":[55]}],"verseLabel":"غافر: 55","question":"لماذا قُدِّم العشي على الإبكار في قوله ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِيِّ وَالْإِبْكَارِ﴾؟","answer":"لأن المقام جاء بعد الاستغفار؛ والعشي ختام أعمال النهار فيناسب مراجعة النفس وطلب المغفرة، ثم يأتي الإبكار بدايةً ليوم جديد بالطاعة، فيحيط الذكر بطرفي اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص605–606، تحت عنوان «نكتة تقديم العشي على الإبكار»","url":""}]},{"id":"s40-91","number":91,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"ما الباعث الحقيقي لجدال الذين يجادلون في آيات الله بغير حجة؟","answer":"ليس معهم برهان يطلبون به الحق، وإنما يدفعهم كبر داخلي إلى منازعة الهدى وطلب التعاظم؛ فالقصر يفضح الدافع المستتر وراء جدالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص612، تحت عنوان «بلاغة القصر ونوعه وغرضه»","url":""}]},{"id":"s40-185","number":185,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"لماذا صُوِّر الكبر كأنه مستقر ﴿فِي صُدُورِهِمْ﴾؟","answer":"للدلالة على تمكنه في باطنهم ورسوخه في نفوسهم، حتى صار منشأ أفكارهم وجدالهم؛ فليست المشكلة شبهة عابرة بل داء داخلي يحجبهم عن قبول الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص613، تحت عنوان «دلالة الظرفية المجازية ﴿في صدورهم﴾»","url":""}]},{"id":"s40-92","number":92,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"لماذا خُتم الأمر بالاستعاذة باسمي الله ﴿السَّمِيعُ الْبَصِيرُ﴾؟","answer":"لأن المستعيذ يلجأ إلى من يسمع أقوال خصومه ويرى أفعالهم ولا يخفى عليه خطرهم؛ فختم الآية بالاسمين يطمئنه إلى كمال الحفظ والنصر والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص617، تحت عنوان «نكتة تذييل الآية الكريمة بهذين الاسمين الجليلين»","url":""}]},{"id":"s40-93","number":93,"surah":40,"verses":[57],"references":[{"surah":40,"verses":[57]}],"verseLabel":"غافر: 57","question":"ما دلالة الاحتجاج بأن خلق السماوات والأرض أكبر من خلق الناس؟","answer":"يلزم المنكرين بما يقرون به: من خلق السماوات والأرض، وهما أعظم من الناس، لا يعجز عن إعادتهم. فتقام الحجة على الأصل الذي يسلمونه، ويكشف إنكار البعث بعده أنهم لم يعملوا نظرهم فيما اعترفوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص627، تحت عنوان «فن الإلجاء في الآية»","url":""}]},{"id":"s40-94","number":94,"surah":40,"verses":[58],"references":[{"surah":40,"verses":[58]}],"verseLabel":"غافر: 58","question":"لماذا قُدِّم ﴿الْأَعْمَى﴾ أولًا، ثم قُدِّم المؤمنون على المسيء؟","answer":"بدأ بالأعمى لمناسبة السياق الذي يعرض حال الكافر، ثم قدم المؤمنين في المقابلة الثانية تشريفًا واهتمامًا بهم؛ فتغير الترتيب تبعًا لمقصد كل موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص632، تحت عنوان «نكتة تقديم كل من الأعمى والذين آمنوا على مقابلهما»","url":""}]},{"id":"s40-196","number":196,"surah":40,"verses":[58],"references":[{"surah":40,"verses":[58]}],"verseLabel":"غافر: 58","question":"لماذا جُدِّد النفي في ﴿وَلَا الْمُسِيءُ﴾ بعد قوله ﴿وَمَا يَسْتَوِي﴾؟","answer":"لتوكيد انتفاء المساواة وتنبيه السامع إلى المقابلة الثانية استقلالًا؛ فلا يتوهم أن نفي المساواة اقتصر على الأعمى والبصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص635، تحت عنوان «نكتة النفي بـ (لا) بعد سبق النفي بـ﴿ما﴾»","url":""}]},{"id":"s40-95","number":95,"surah":40,"verses":[57,58,59],"references":[{"surah":40,"verses":[57,58,59]}],"verseLabel":"غافر: 57–59","question":"ما سر تكرار ﴿أَكْثَرَ النَّاسِ﴾ مع اختلاف نفي العلم في الأولى ونفي الإيمان في الثانية؟","answer":"ورد نفي العلم بعد الاحتجاج بعظم خلق السماوات والأرض؛ فالمقام يقتضي معرفة قدرة الخالق على الإعادة. وورد نفي الإيمان بعد التصريح بمجيء الساعة؛ فالمطلوب هناك التصديق بما دل عليه البرهان. وبذلك يناسب كل ختام القضية التي قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص680–681، تحت عنوان «بيان المتشابه في استعمال الفعل المضارع المنفي»","url":""}]},{"id":"s40-96","number":96,"surah":40,"verses":[59],"references":[{"surah":20,"verses":[15]},{"surah":40,"verses":[59]}],"verseLabel":"غافر: 59؛ طه: 15","question":"لماذا توالت المؤكدات في قوله ﴿إِنَّ السَّاعَةَ لَآتِيَةٌ لَا رَيْبَ فِيهَا﴾؟","answer":"لأن الخطاب يواجه من ينكرون البعث، فاحتاج الخبر إلى توكيد متتابع بـ﴿إن﴾ واللام ونفي الريب، حتى يواجه جحودهم ويثبت حتمية الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص642، تحت عنوان «فائدة تتابع المؤكدات في صدر الآية»","url":""}]},{"id":"s40-97","number":97,"surah":40,"verses":[60],"references":[{"surah":40,"verses":[60]}],"verseLabel":"غافر: 60","question":"لماذا قيل ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ﴾ بدل «إن تدعوني أستجب لكم»؟","answer":"لأن صيغة الطلب تدعو العباد مباشرة إلى ما ينفعهم وتعدهم بالاستجابة في عبارة موجزة مشوقة، بدل تعليق الوعد على شرط بارد؛ فهي أبلغ في الحث وإظهار اللطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص658، تحت عنوان «دلالة استعمال أسلوب الطلب دون أسلوب الشرط»","url":""}]},{"id":"s40-98","number":98,"surah":40,"verses":[60],"references":[{"surah":40,"verses":[60]}],"verseLabel":"غافر: 60","question":"كيف جمعت آية ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ﴾ بين الترغيب والوعيد من غير تكرار؟","answer":"ذكر الدعاء والاستجابة أولًا، ثم العبادة ودخول جهنم، فدل كل طرف على ما حذف من الآخر: للدعاء والعبادة قبول وثواب، ولتركهما واستكبار صاحبه وعيد؛ فجمع الإيجاز الترغيب والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص662، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s40-99","number":99,"surah":40,"verses":[60],"references":[{"surah":40,"verses":[60]}],"verseLabel":"غافر: 60","question":"لماذا اختير وصف المستكبرين عن العبادة بأنهم سيدخلون جهنم ﴿دَاخِرِينَ﴾؟","answer":"لأن الدخور ذل وصغار؛ فينقلب استكبارهم في الدنيا هوانًا ظاهرًا في الآخرة، ويكشف الجزاء بطلان الكبر الذي منعهم من الخضوع لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص662، تحت عنوان «دلالة التعبير بـ﴿داخرين﴾ مادة وصيغة»","url":""}]},{"id":"s40-100","number":100,"surah":40,"verses":[61],"references":[{"surah":40,"verses":[61]}],"verseLabel":"غافر: 61","question":"لماذا قُدِّم الليل على النهار في تعداد نعم الله؟","answer":"لأن الظلام هو الحالة الأصلية العامة، والنور حالة تطرأ عليه، ولأن السكون في الليل يهيئ الإنسان لما يعقبه من حركة النهار؛ فناسب أن يبدأ بما يمهد لما بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص674، تحت عنوان «نكتة تقديم ذكر الليل على النهار»","url":""}]},{"id":"s40-101","number":101,"surah":40,"verses":[61],"references":[{"surah":40,"verses":[61]}],"verseLabel":"غافر: 61","question":"ما دلالة وصف النهار بأنه ﴿مُبْصِرًا﴾؟","answer":"أسند الإبصار إلى النهار مع أن المبصرين هم الناس فيه، فهو مجاز عقلي لعلاقة الزمان. ويبرز هذا الإسناد شدة صلاحية النهار للإبصار والعمل، حتى كأنه هو الذي يبصر، فيعظم الامتنان بهذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص672، تحت عنوان «بلاغة المجاز في إسناد الإبصار إلى النهار»","url":""}]},{"id":"s40-102","number":102,"surah":40,"verses":[61],"references":[{"surah":40,"verses":[61]}],"verseLabel":"غافر: 61","question":"لماذا عُمِّم فضل الله على الناس بعد ذكر نعمتي الليل والنهار؟","answer":"ليجعل الليل والنهار مثالين لفيض أوسع من النعم التي تقوم عليها حياة الناس، فينتقل الذهن من نعمتين مشهودتين إلى استحضار عموم فضل الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص676، تحت عنوان «بلاغة التذييل في جملة ﴿إن الله لذو فضل على الناس﴾»","url":""}]},{"id":"s40-103","number":103,"surah":40,"verses":[62,63],"references":[{"surah":40,"verses":[62,63]}],"verseLabel":"غافر: 62–63","question":"لماذا قيل بعد إنكار انصرافهم عن التوحيد ﴿كَذَلِكَ يُؤْفَكُ الَّذِينَ كَانُوا بِآيَاتِ اللَّهِ يَجْحَدُونَ﴾؟","answer":"لبيان أن انصرافهم ليس ناشئًا عن خفاء الدليل، بل هو شأن كل من يجحد آيات الله؛ فالتشبيه يلحقهم بسلسلة المكذبين ويكشف أن الجحود هو الذي صرفهم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص692، تحت عنوان «بلاغة التشبيه بالكاف في ﴿كذلك﴾»","url":""}]},{"id":"s40-104","number":104,"surah":40,"verses":[62],"references":[{"surah":40,"verses":[62]}],"verseLabel":"غافر: 62","question":"كيف تتدرج الأخبار من الربوبية والخلق إلى توحيد الله؟","answer":"تبدأ بأنه رب المخاطبين، ثم تعمم أنه خالق كل شيء، فتفضي المقدمتان إلى النتيجة: من انفرد بالتدبير والخلق انفرد باستحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص685، تحت عنوان «بلاغة الترقي في سرد الأخبار»","url":""}]},{"id":"s40-197","number":197,"surah":40,"verses":[62],"references":[{"surah":40,"verses":[62]}],"verseLabel":"غافر: 62","question":"لماذا فُصلت كلمة التوحيد ﴿لَا إِلَهَ إِلَّا هُوَ﴾ عما قبلها؟","answer":"لأنها نتيجة مستقلة مستأنفة لما سبق من إثبات الربوبية والخلق؛ فجاء الفصل ليبرز الحكم الحاسم الذي تثمره تلك الأدلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص688، تحت عنوان «نكتة فصل كلمة التوحيد»","url":""}]},{"id":"s40-105","number":105,"surah":40,"verses":[61,64],"references":[{"surah":40,"verses":[61,64]}],"verseLabel":"غافر: 61، 64","question":"لماذا استقلت آية ﴿اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا﴾ عن سابقتها؟","answer":"لأنها تستأنف دليلًا وامتنانًا جديدًا بتهيئة المكان بعد تهيئة الزمان، فتأخذ نعمتا الأرض والسماء عناية مستقلة مع اتصال الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص698، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s40-106","number":106,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"ما أثر المقابلة بين الأرض والسماء في تعداد النعم؟","answer":"تجمع ما تحت الإنسان وما فوقه في صورة مكان كامل مهيأ لحياته؛ أرض تحمل وتستقر، وسماء تظل وتحفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص700، تحت عنوان «بلاغة الطباق بين لفظتي ﴿الأرض﴾ و(السماء)»","url":""}]},{"id":"s40-198","number":198,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"ما الصورة في وصف السماء بأنها ﴿بِنَاءً﴾؟","answer":"تشبهها بسقف محكم مرفوع فوق الناس، فيوحي اللفظ بالنظام والحماية وإحكام الصنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص702، تحت عنوان «بلاغة التشبيه في حال السماء»","url":""}]},{"id":"s40-107","number":107,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"لماذا ذُكر إحسان صورة الإنسان بعد جعل الأرض قرارًا والسماء بناء؟","answer":"لينتقل الامتنان من تهيئة المكان إلى تهيئة ساكنه؛ فكما أحسن الله بيئة الإنسان أحسن خلقه وهيئته، فاجتمع جمال المسكن وإتقان الساكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص703–704، تحت عنوان «نكتة عطف تصوير الخلقة على جعل السماء والأرض»","url":""}]},{"id":"s40-186","number":186,"surah":40,"verses":[64],"references":[{"surah":40,"verses":[64]}],"verseLabel":"غافر: 64","question":"لماذا ذُكر رزق الإنسان من الطيبات بعد إحسان صورته؟","answer":"ليكتمل الامتنان: خلقه الله في أحسن هيئة ثم أمده بما يحفظ حياته ويلائم فطرته من الرزق الطيب، فجمع له حسن الخلقة وكمال الإمداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص705، تحت عنوان «فائدة عطف قوله: ﴿ورزقكم من الطيبات﴾ على ما تقدمها»","url":""}]},{"id":"s40-108","number":108,"surah":40,"verses":[65],"references":[{"surah":40,"verses":[65]}],"verseLabel":"غافر: 65","question":"لماذا جاء الأمر ﴿فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ﴾ بعد قوله ﴿هُوَ الْحَيُّ لَا إِلَهَ إِلَّا هُوَ﴾؟","answer":"لأن من له الحياة الكاملة الدائمة وينفرد بالألوهية هو وحده المستحق للدعاء والعبادة؛ فالأمر نتيجة لما قبله، والإخلاص يمنع إشراك غيره فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص714، تحت عنوان «معنى الفاء في قوله: ﴿فادعوه﴾»","url":""}]},{"id":"s40-109","number":109,"surah":40,"verses":[66],"references":[{"surah":40,"verses":[66]}],"verseLabel":"غافر: 66","question":"لماذا جمع الرسول ﷺ بين قوله ﴿نُهِيتُ﴾ وقوله ﴿وَأُمِرْتُ﴾؟","answer":"ليبين أن الدين لا يكتمل بمجرد ترك الشرك، بل لا بد معه من الانقياد لرب العالمين؛ فاجتمع في الإعلان براءة من الباطل واستسلام للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص730، تحت عنوان «بلاغة الطباق بين ﴿نهيت﴾ و(أمرت)»","url":""}]},{"id":"s40-110","number":110,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"لماذا اختير لفظ ﴿تراب﴾ عند بدء الحديث عن خلق الإنسان؟","answer":"لأن التراب يذكّر الإنسان بضعف أصله وهوان مادته؛ فهو هشّ تذروه الرياح، فيوقظه ذلك إلى معرفة قدره والتواضع والانقياد لخالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص738، تحت عنوان «نكتة اختيار مفردة ﴿تراب﴾»","url":""}]},{"id":"s40-187","number":187,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"ما دلالة تكرار ﴿ثم﴾ بين أطوار خلق الإنسان؟","answer":"تصوّر ﴿ثم﴾ كلَّ طور مرحلةً مستقلة يعقبها غيرها بعد زمن، فتستحضر تدرّج الخلق من الأصل الأول إلى اكتمال الإنسان وشيخوخته. وفي تكرارها تنبيه إلى عناية الله بالإنسان عبر مراحله ودعوة إلى شكر هذه النعم والخضوع لخالقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص738–739، تحت عنوان «براعة استعمال حرف التراخي وتكراره»","url":""}]},{"id":"s40-188","number":188,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"لماذا خُتم عرض أطوار الإنسان بقوله ﴿ولعلكم تعقلون﴾؟","answer":"لأن تعاقب تلك الأطوار دليل ظاهر على قدرة الله ووحدانيته وعلى إمكان البعث؛ فجاء الختام ليدعو الإنسان إلى إعمال العقل في خلقه، حتى يقوده النظر السليم إلى توحيد الله وعبادته لا إلى الأوهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص751–752، تحت عنوان «دلالة التعبير بمفردة العقل»","url":""}]},{"id":"s40-111","number":111,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"ما سر إفراد ﴿طِفْلًا﴾ مع جمع المخاطبين؟","answer":"يجوز حمل الإفراد على إرادة كل واحد من المخاطبين: يخرج كل واحد طفلًا. ويجوز أن يكون ﴿طفلًا﴾ اسم جنس يشمل الجمع؛ فيؤدي اللفظ المفرد معنى المرحلة المشتركة التي يمر بها الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص741، تحت عنوان «نكتة إفراد لفظ ﴿طفلًا﴾»","url":""}]},{"id":"s40-112","number":112,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"لماذا جاء قوله ﴿ومنكم من يتوفى من قبل﴾ وسط ذكر أطوار العمر؟","answer":"جاء احتراسًا من توهّم أن كل إنسان يبلغ الشيخوخة أو الأجل المسمّى؛ فبعض الناس يُتوفّى قبل تلك المراحل، وبذلك يظل تمام العمر خاضعًا للأجل الذي قدّره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص748، تحت عنوان «بلاغة الاحتراس»","url":""}]},{"id":"s40-113","number":113,"surah":40,"verses":[68],"references":[{"surah":36,"verses":[82]},{"surah":40,"verses":[68]}],"verseLabel":"غافر: 68؛ يس: 82","question":"ماذا تقصر ﴿إِنَّمَا﴾ في قوله ﴿فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"تقصر طريق تحقق المقضي على نفاذ أمر الله بلا معالجة ولا عجز ولا تأخر؛ فمتى تعلقت إرادته بشيء وجد على الفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص761، تحت عنوان «معنى (إنما) في جملة القصر»","url":""}]},{"id":"s40-114","number":114,"surah":40,"verses":[68],"references":[{"surah":40,"verses":[68]}],"verseLabel":"غافر: 68","question":"لماذا فُصل قوله ﴿هو الذي يحيي ويميت﴾ عما قبله؟","answer":"لأنه استئناف يقرر حقيقة عامة بعد تفصيل خلق الإنسان؛ فالذي أنشأ أطواره هو المتصرف في حياته وأجله، فينتقل السياق من عرض المراحل إلى أصل القدرة على الإحياء والإماتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص756، تحت عنوان «علة فصل الجملة عما قبلها»","url":""}]},{"id":"s40-115","number":115,"surah":40,"verses":[69,70],"references":[{"surah":40,"verses":[69,70]}],"verseLabel":"غافر: 69–70","question":"ما غرض قوله ﴿ألم تر إلى الذين يجادلون في آيات الله﴾؟","answer":"الاستفهام للتعجيب من حالهم وإنكار انصرافهم عن آيات الله الواضحة ومحاولتهم طمسها؛ وفيه تقرير لشناعة جدالهم وتحذير ووعيد لمن يجادل في الحق بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص769، تحت عنوان «معنى الهمزة في جملة ﴿ألم تر﴾، وغرضها»","url":""}]},{"id":"s40-189","number":189,"surah":40,"verses":[69,70],"references":[{"surah":40,"verses":[69,70]}],"verseLabel":"غافر: 69–70","question":"لماذا انتقل السياق من ذكر جدالهم في آيات الله إلى تكذيبهم بالكتاب؟","answer":"لأن التكذيب هو منشأ ذلك الجدال؛ فذكره يكشف أنهم لم يطلبوا الحق، بل ردّوا القرآن وما جاءت به الرسل مع أن الكتب المنزلة دلائل تقود إلى الإيمان، فكان جحودهم بها أصل انصرافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص775–776، تحت عنوان «براعة الانتقال من ذكر الجدال إلى ذكر التكذيب»","url":""}]},{"id":"s40-116","number":116,"surah":40,"verses":[71,72],"references":[{"surah":40,"verses":[71,72]}],"verseLabel":"غافر: 71–72","question":"ما الذي يصوره قوله ﴿يُسْحَبُونَ فِي الْحَمِيمِ﴾ من حال المكذبين؟","answer":"يصور جرَّهم بعنف في حال من الهوان؛ فالسحب يجمع الإيلام بالإهانة، ويعاملهم معاملة من سقطت كرامته. وجاء الفعل مضارعًا ليستحضر المشهد ويصور تجدد السحب أمام الناظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص784، تحت عنوان «بلاغة استعمال مفردة ﴿يسحبون﴾ مادة وصيغة»","url":""}]},{"id":"s40-190","number":190,"surah":40,"verses":[71,72],"references":[{"surah":40,"verses":[71,72]}],"verseLabel":"غافر: 71–72","question":"لماذا جاء ﴿ثُمَّ فِي النَّارِ يُسْجَرُونَ﴾ بعد سحبهم في الحميم؟","answer":"تفيد ﴿ثم﴾ انتقالهم بعد الحميم إلى مرحلة أخرى من العذاب، كما تفيد الارتقاء إلى ما هو أشد؛ فالإحراق بالنار فوق ما سبق من السحب والتعذيب بالماء الحار. وفي هذا التتابع تصوير لطول مراحل العذاب وتنوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص785، تحت عنوان «نوع التراخي ودلالته في قوله: ﴿ثم في النار يسجرون﴾»","url":""}]},{"id":"s40-191","number":191,"surah":40,"verses":[71,72],"references":[{"surah":40,"verses":[71,72]}],"verseLabel":"غافر: 71–72","question":"ما الذي يصوره لفظ ﴿يُسْجَرُونَ﴾ في عذاب المكذبين؟","answer":"السجر يدل على الإيقاد والاشتعال والتأجج؛ فيصور طرحهم في النار وإحراقهم بها، حتى تصير أجسامهم وقودًا يزيدها اشتعالًا. فاللفظ يجمع بين كونهم محروقين وكونهم مادة لإيقاد النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص787، تحت عنوان «دلالة استعمال مفردة السجر»","url":""}]},{"id":"s40-117","number":117,"surah":40,"verses":[71],"references":[{"surah":40,"verses":[71]}],"verseLabel":"غافر: 71","question":"ما سر تخصيص الأعناق بذكر الأغلال؟","answer":"التصريح بالأعناق، مع أن الغل يكون فيها عادة، يزيد تصوير الإذلال؛ فقد كانت موضع رفع الرؤوس والإعراض عن الحق، فتصير موضع القيد والجر. وبذلك تقابل هيئة العقوبة هيئة التكبر التي كانوا عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص782، تحت عنوان «نكتة التصريح بالقيد»","url":""}]},{"id":"s40-118","number":118,"surah":40,"verses":[73,74],"references":[{"surah":40,"verses":[73,74]}],"verseLabel":"غافر: 73–74","question":"ماذا يضيف قيد ﴿مِنْ دُونِ اللَّهِ﴾ إلى سؤال المشركين عن آلهتهم؟","answer":"يحدد أن المسؤول عنهم معبوداتهم التي اتخذوها بديلًا من الله، فيسبق إقرارهم بضياعها تقريع صريح على أصل شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص797، تحت عنوان «نكتة التقييد بالجار والمجرور ﴿من دون﴾ ودلالتهما»","url":""}]},{"id":"s40-119","number":119,"surah":40,"verses":[73,74],"references":[{"surah":40,"verses":[73,74]}],"verseLabel":"غافر: 73–74","question":"لماذا قالوا بعد ﴿ضَلُّوا عَنَّا﴾: ﴿بَلْ لَمْ نَكُنْ نَدْعُو مِنْ قَبْلُ شَيْئًا﴾؟","answer":"يحتمل كلامهم أنهم ارتدوا إلى الكذب فأنكروا شركهم بعد أن اعترفوا بغياب آلهتهم، فلم تمنعهم أهوال الآخرة من المكابرة. ويحتمل أنهم انتقلوا إلى الاعتراف بأن عبادتهم ضاعت، وأن ما عبدوه لم يكن شيئًا يُعتد به ولا يملك نفعًا؛ وهو ندم جاء بعد فوات زمن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص799–800، تحت عنوان «نوع ﴿بل﴾ ودلالتها»","url":""}]},{"id":"s40-120","number":120,"surah":40,"verses":[75],"references":[{"surah":40,"verses":[75]}],"verseLabel":"غافر: 75","question":"لماذا قُيِّد الفرح في قوله ﴿تَفْرَحُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ﴾؟","answer":"لأن الفرح ليس مذمومًا كله؛ فمنه فرح مشروع بفضل الله ورحمته. فجاء قيد ﴿بغير الحق﴾ ليحدد أن سبب العقوبة هو الفرح بالباطل الذي يصرف عن الحق، ويدفع توهّم أن الفرح محرم على المؤمنين بإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص809، تحت عنوان «نكتة تقييد الأفعال»","url":""}]},{"id":"s40-121","number":121,"surah":40,"verses":[76],"references":[{"surah":40,"verses":[76]}],"verseLabel":"غافر: 76","question":"لماذا قيل ﴿فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾ ولم يقل «فبئس مدخلهم»؟","answer":"لأن المثوى هو محل الإقامة والاستقرار، فهو أدل على دوام العذاب من مجرد المدخل الذي لا يستلزم البقاء. ولذلك ناسب ذكر الخلود، وكان أشد في التهديد؛ فالنار ليست بابًا يعبرونه بل مقامًا يستقرون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج51، ص815–816، تحت عنوان «بلاغة استعمال مفردة ﴿مثوى﴾ دون (مدخل)»","url":""}]},{"id":"s40-122","number":122,"surah":40,"verses":[77],"references":[{"surah":40,"verses":[77]}],"verseLabel":"غافر: 77","question":"هل يقتصر ﴿وَعْدَ اللَّهِ﴾ هنا على نصر المؤمنين؟","answer":"لا؛ فاللفظ يشمل ما وعد الله به المؤمنين من النصر والتمكين، وما أوعد به الكافرين من الإذلال والجزاء، فيحمل للنبي ﷺ التثبيت والتسلية من الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص14، تحت عنوان «نكتة استعمال مفردة (الوعد)»","url":""}]},{"id":"s40-123","number":123,"surah":40,"verses":[77],"references":[{"surah":40,"verses":[77]}],"verseLabel":"غافر: 77","question":"هل يتوقف تحقق وعيد المكذبين على أن يراه النبي ﷺ في حياته؟","answer":"لا؛ فصيغة ﴿فَإِمَّا نُرِيَنَّكَ﴾ تفتح احتمال أن يرى النبي ﷺ بعض ما وُعدوا به، واحتمال أن يتوفاه الله قبل ذلك، لكن الانتقام منهم واقع في الحالين؛ فلا تتوقف صدقية الوعيد على مشاهدته في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص16، تحت عنوان «بلاغة التعبير بالجملة الشرطية باستعمال (إما)»","url":""}]},{"id":"s40-124","number":124,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"لماذا قُدِّم الرسل الذين قصَّهم الله على الذين لم يقصصهم؟","answer":"لأن المثبت يُقدَّم على المنفي، ولأن تعريف النبي ﷺ ببعض الرسل كان تسليةً له وتثبيتًا، أما عدم تعريفه بالباقين فله حكمة ربانية؛ إذ لا كمال في كشف ما لا حاجة إلى معرفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص33، تحت عنوان «نكتة تقديم ﴿قصصنا﴾ على ﴿لم نقصص﴾»","url":""}]},{"id":"s40-125","number":125,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"لماذا انتقل التعبير من ﴿بِإِذْنِ اللَّهِ﴾ إلى ﴿فَإِذَا جَاءَ أَمْرُ اللَّهِ﴾؟","answer":"لأن ما سيُظهره الله بإذنه ليس استجابةً لاقتراح المعاندين، بل آيات عقاب يقضي بها على تكذيبهم؛ فسُمّي ﴿أَمْرُ اللَّهِ﴾ تعريضًا بحتمية الجزاء وتحذيرًا من عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص38–39، تحت عنوان «نكتة العدول عن مجيء الإذن إلى الأمر»","url":""}]},{"id":"s40-192","number":192,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"ما الذي يبرزه قوله ﴿قُضِيَ بِالْحَقِّ﴾ عند مجيء أمر الله؟","answer":"يبرز أن الفصل سيُظهر صدق الرسول وبطلان مكذبيه، وأن الجزاء قائم على العدل؛ وفي تخصيص الحق تعريض بالمبطلين وإنذار بأن خصومتهم ستنتهي بحكم يخسرون عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص39–40، تحت عنوان «بلاغة ذكر ﴿قضي بالحق﴾ دون غيره»","url":""}]},{"id":"s40-126","number":126,"surah":40,"verses":[79,80],"references":[{"surah":40,"verses":[79,80]}],"verseLabel":"غافر: 79–80","question":"ما سر تقديم الركوب على الأكل في تعداد منافع الأنعام؟","answer":"قدم الركوب لأنه من أهم منافع الأنعام في قطع المسافات الواسعة، وهو المقصود الأبرز في سياق ذكر الحمل وبلوغ الحاجات. ثم جاء الأكل ضمن وجوه الانتفاع المتنوعة، فناسب الترتيب الغرض الذي يمهد له السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص51، تحت عنوان «نكتة تقديم الركوب على الأكل»","url":""}]},{"id":"s40-127","number":127,"surah":40,"verses":[80],"references":[{"surah":40,"verses":[80]}],"verseLabel":"غافر: 80","question":"هل تدل ﴿حَاجَةً﴾ على غرض واحد من الأنعام؟","answer":"لا؛ فتَنكيرها يشمل أي حاجة دنيوية تتحقق بها مصلحة الناس، فيتسع الامتنان لما يبلغونه على الأنعام من منافع ومقاصد، ولا ينحصر في غرض بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص56، تحت عنوان «نكتة تنكير لفظ ﴿حاجة﴾ في السياق»","url":""}]},{"id":"s40-193","number":193,"surah":40,"verses":[80],"references":[{"surah":40,"verses":[80]}],"verseLabel":"غافر: 80","question":"لماذا عُبِّر عن الحاجات المستقرة في النفس بأنها ﴿فِي صُدُورِكُمْ﴾؟","answer":"لأن الصدور تحيط بالقلوب، والقلوب موضع المقاصد؛ فعُبِّر بالمحل الأوسع عن مستقر الرغبات الخفية، مبالغةً في إبراز أهمية ما يعقد الإنسان قلبه على بلوغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص56، تحت عنوان «بلاغة الكناية عن القلوب بالصدور»","url":""}]},{"id":"s40-128","number":128,"surah":40,"verses":[79,80],"references":[{"surah":40,"verses":[79,80]}],"verseLabel":"غافر: 79–80","question":"ما دلالة الجمع بين حمل الناس على الأنعام في البر وحملهم على الفلك في البحر؟","answer":"يجمع الامتنان بين وسيلتي الحمل في البر والبحر، وقُدِّم الحمل على الأنعام لاتصال الكلام بمنافعها، ثم ذُكرت الفلك ليعم التيسير الطريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص57، تحت عنوان «نكتة تقديم الحمل على الأنعام على الحمل على الفلك»","url":""}]},{"id":"s40-129","number":129,"surah":40,"verses":[81],"references":[{"surah":40,"verses":[81]}],"verseLabel":"غافر: 81","question":"لماذا جاء قوله تعالى: ﴿وَيُرِيكُمْ آيَاتِهِ﴾ بعد تفصيل منافع الأنعام؟","answer":"ليعمم بعد ذكر النعم المفصلة: فآيات الله لا تنحصر في الأنعام، بل تشمل كل ما يدل على وحدانيته وقدرته، وفي ذلك تجديد للتذكير بسائر النعم والدلائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص60، تحت عنوان «نكتة ما يفيد التذييل في قوله: ﴿ويريكم آياته﴾»","url":""}]},{"id":"s40-194","number":194,"surah":40,"verses":[81],"references":[{"surah":40,"verses":[81]}],"verseLabel":"غافر: 81","question":"ماذا يفيد الاستفهام في قوله تعالى: ﴿فَأَيَّ آيَاتِ اللَّهِ تُنْكِرُونَ﴾؟","answer":"هو استفهام إنكاري توبيخي؛ لأن آيات الله ظاهرة لا يكاد ينكرها ذو عقل، فجاء ليكشف أن جحودها بعد مشاهدتها سفه ومكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص61–62، تحت عنوان «بلاغة الاستفهام في قوله: ﴿فأي آيات الله﴾»","url":""}]},{"id":"s40-130","number":130,"surah":40,"verses":[82],"references":[{"surah":40,"verses":[82]}],"verseLabel":"غافر: 82","question":"ماذا يضيف قوله تعالى: ﴿وَآثَارًا فِي الْأَرْضِ﴾ إلى مشهد الأمم السابقة؟","answer":"يجعل آثار قوتهم وعمرانهم قائمة في الأرض المعهودة للمخاطبين، فيرون بأعينهم بقايا حضارات من سبقهم؛ فتغدو الآثار شاهدًا حاضرًا على ما انتهوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص74، تحت عنوان «فائدة الظرفية ﴿في الأرض﴾»","url":""}]},{"id":"s40-131","number":131,"surah":40,"verses":[83],"references":[{"surah":40,"verses":[83]}],"verseLabel":"غافر: 83","question":"ماذا يصوّر قوله تعالى: ﴿فَرِحُوا بِمَا عِنْدَهُمْ مِنَ الْعِلْمِ﴾ من حال المكذبين؟","answer":"يصوّر شدة اعتدادهم بما ورثوه من معتقدات باطلة حتى تمسكوا بها، وجادلوا الرسل، وأعرضوا عن البينات الواضحة؛ فالفرح كناية عن رضا أغلق عليهم باب قبول الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص79–80، تحت عنوان «بلاغة الكناية في التعبير بالفرح»","url":""}]},{"id":"s40-195","number":195,"surah":40,"verses":[83],"references":[{"surah":40,"verses":[83]}],"verseLabel":"غافر: 83","question":"لماذا سُمِّي ما عند المكذبين ﴿عِلْمًا﴾ مع أنه ضلال؟","answer":"سُمِّي علمًا على سبيل التهكم بهم؛ لأنهم زعموا الجهل علمًا وفرحوا به، فجاء اللفظ الذي يوحي بالتعظيم في مقام التحقير ليكشف غرورهم وسوء تقديرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص80، تحت عنوان «بلاغة فن التهكم في السياق المحكم»","url":""}]},{"id":"s40-132","number":132,"surah":40,"verses":[83],"references":[{"surah":40,"verses":[83]}],"verseLabel":"غافر: 83","question":"ما سر مقابلة فرحهم بعلمهم بحيق ما كانوا به يستهزئون؟","answer":"كان فرحهم بما عندهم باعثًا على الاستهزاء بالوعيد، فجاء ﴿حاق بهم﴾ ليصور إحاطة ما استهانوا به من العذاب. وبذلك ينقلب الأمن المتوهم والاعتداد بالنفس إلى مصير لا يجدون منه منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص83، تحت عنوان «بلاغة الاستعارة في ﴿وحاق بهم﴾»","url":""}]},{"id":"s40-133","number":133,"surah":40,"verses":[84,85],"references":[{"surah":40,"verses":[84,85]}],"verseLabel":"غافر: 84–85","question":"لماذا جمعوا عند رؤية العذاب بين ﴿آمَنَّا بِاللَّهِ وَحْدَهُ﴾ و﴿وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ﴾؟","answer":"يكشف الطباق بين الإيمان والكفر انقلاب موقفهم كاملًا عند معاينة العذاب: أثبتوا التوحيد ونفوا ما كانوا عليه من الشرك. لكنه يفضح أيضًا تأخر هذا الرجوع؛ فقد جاء إيمان اضطرار بعد استقرار الكفر، فلم يمحُه حين نزل البأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص94، تحت عنوان «بلاغة الطباق في الجمع بين الإيمان والكفر»","url":""}]},{"id":"s40-134","number":134,"surah":40,"verses":[84],"references":[{"surah":40,"verses":[84]}],"verseLabel":"غافر: 84","question":"لماذا قيل ﴿آمَنَّا بِاللَّهِ وَحْدَهُ﴾ مع أن الإيمان بالله يُفهم منه التوحيد؟","answer":"جاءت كلمة ﴿وحده﴾ لتؤكد إيمانهم الجازم بالله وإفراده بالعبادة، وتنفي صراحة ما كانوا عليه من الشرك؛ فلا يبقى في اعترافهم احتمال إقرار بالله مع إثبات شركاء له.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص94، تحت عنوان «نكتة التعبير بلفظ ﴿وحده﴾»","url":""}]},{"id":"s40-135","number":135,"surah":40,"verses":[85],"references":[{"surah":40,"verses":[85]}],"verseLabel":"غافر: 85","question":"لماذا جُعل عدم نفع الإيمان بعد نزول العذاب سنةً لله في عباده؟","answer":"ليبيّن أن الأمر ليس حالة عارضة تخص هؤلاء، بل حكم ثابت سبق في الأمم: الإيمان النافع هو إيمان الاختيار قبل ظهور البأس، أما ما يأتي بعد انكشاف العذاب فإيمان اضطرار لا يُقبل؛ وقد ذكر المصدر قوم يونس استثناءً من نزول العذاب بعد ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص98–99، تحت عنوان «نكتة فصل قوله: ﴿سُنَّتَ اللَّهِ﴾»","url":""}]},{"id":"s40-136","number":136,"surah":40,"verses":[78,85],"references":[{"surah":40,"verses":[78,85]}],"verseLabel":"غافر: 78، 85","question":"لماذا عُبّر عن زمن انكشاف الخسارة بكلمة ﴿هُنَالِكَ﴾؟","answer":"استعير اسم المكان للزمان ليجعل لحظة ظهور الخسران كأنها موضع شاخص يقف عنده الناس؛ فتغدو العاقبة حاضرة مرئية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص42، تحت عنوان «بلاغة استعارة اسم الإشارة المكاني للظرف الزماني»","url":""}]},{"id":"s40-199","number":199,"surah":40,"verses":[78,85],"references":[{"surah":40,"verses":[78,85]}],"verseLabel":"غافر: 78، 85","question":"لماذا قُدِّم القضاء بالحق على خسارة المبطلين؟","answer":"لأن الخسارة نتيجة الحكم الفاصل، فرتبها النظم بعد القضاء ترتيب السبب والمسبب، وأظهر أن الهلاك ثمرة بطلانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص43، تحت عنوان «نكتة تقديم القضاء على الخسارة»","url":""}]},{"id":"s40-200","number":200,"surah":40,"verses":[6],"references":[{"surah":40,"verses":[6]}],"verseLabel":"غافر: 6","question":"ما الذي تحسمه عبارة ﴿حَقَّتْ كَلِمَتُ رَبِّكَ﴾ قبل التصريح بأنهم أصحاب النار؟","answer":"«حقَّ القول» و«حقَّت الكلمة» تعبيران قرآنيان يدلان على ثبوت العذاب ووجوبه على من استحقه، لا على مجرد وقوع قولٍ أو صدور حكم. فجاء التعبير ليصور أن الكفر المتتابع أوصلهم إلى حكم ثابت لا مدفع له، ثم كشفت الجملة التالية مضمون تلك الكلمة: ﴿أَنَّهُمْ أَصْحَابُ النَّارِ﴾.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، ما معنى «حق القول» و«حقت الكلمة»؟ – تدارس القرآن الكريم.","url":""}]},{"id":"s40-201","number":201,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36، 37","question":"ما دلالة ﴿أَسْبَابَ السَّمَاوَاتِ﴾، وهل طلب فرعون بناء الصرح بحثًا عن الحقيقة أم تمويهًا على قومه؟","answer":"الأسباب هي الوسائل والطرق الموصلة إلى الغاية، فزعم فرعون أنه يريد بلوغ طرق السماوات والاطلاع إلى إله موسى. ولم يكن طلبه ناشئًا عن بحث مخلص؛ فقد كان يجحد ما استيقنته نفسه، وإنما اتخذ الصرح وسيلة للسخرية والتلبيس وإدامة سلطانه، ولذلك عقب النظم بأن سوء عمله زُيّن له وأن كيده في تباب.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، ما معنى «أسباب السماوات»، وهل كان فرعون موحدًا؟ – تدارس القرآن الكريم.","url":""}]},{"id":"s40-202","number":202,"surah":40,"verses":[45],"references":[{"surah":40,"verses":[45]}],"verseLabel":"غافر: 45","question":"ما سر جمع ﴿سَيِّئَاتِ مَا مَكَرُوا﴾ وإفراد ﴿سُوءُ الْعَذَابِ﴾ في آية واحدة؟","answer":"«السيئة» عمل قبيح مخصوص، وتُجمع على «سيئات»؛ ومكر آل فرعون اشتمل على أعمال وخطط قبيحة متعددة، فناسبه الجمع. أما «السوء» فأعم من السيئة، ويقع على كل ما يسوء من فعل أو عذاب، وهو اسم مصدر يشمل القليل والكثير ولا يُجمع إلا عند إرادة الأنواع؛ فناسب إحاطة العذاب بهم أن يقال ﴿سوء العذاب﴾.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين السوء والسيئة في قوله «سيئات ما مكروا... سوء العذاب» – تدارس القرآن الكريم.","url":""}]},{"id":"s40-203","number":203,"surah":40,"verses":[58],"references":[{"surah":40,"verses":[58]}],"verseLabel":"غافر: 58","question":"ما دلالة زيادة التاء في ﴿قَلِيلًا مَا تَتَذَكَّرُونَ﴾، مع ورود «تذكّرون» محذوفة التاء في مواضع أخرى؟","answer":"زيادة المبنى هنا تلائم زيادة زمن التأمل؛ فآية غافر لا تقتصر على المقارنة البديهية بين الأعمى والبصير، بل تنتقل إلى الإيمان والعمل الصالح والإساءة، وهي قضية تحتاج إلى نظر أطول وتذكّر أعمق. أما المقارنة التي يُدرك جوابها فورًا، مثل عدم استواء الأعمى والبصير، فيناسبها اللفظ الأخف: «تذكّرون».","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين «تذكرون» و«تتذكرون» – تدارس القرآن الكريم.","url":""}]},{"id":"s40-204","number":204,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"ما سر الانتقال من ﴿ثُمَّ مِنْ عَلَقَةٍ﴾ إلى الجملة الفعلية ﴿ثُمَّ يُخْرِجُكُمْ طِفْلًا﴾؟","answer":"المعطوف الحقيقي هو الفعل ﴿يخرجكم﴾ على الفعل الأول ﴿خلقكم﴾، أما «من تراب ثم من نطفة ثم من علقة» فمتعلقات متتابعة بالفعل الأول تصف مواد الخلق ومراحله. وبالعودة إلى الفعل بعد هذه المتعلقات يستأنف النظم الحدث الرئيس: خلقكم، ثم يخرجكم طفلًا؛ فتنتظم المراحل مع بقاء البناء النحوي محكمًا.","sources":[{"label":"فاضل السامرائي، سورة غافر، الآية 67: من أمثلة العطف في القرآن – بوابة إسلاميات.","url":""}]},{"id":"s40-205","number":205,"surah":40,"verses":[78,85],"references":[{"surah":40,"verses":[78,85]}],"verseLabel":"غافر: 78، 85","question":"ما سر ختم المشهد الأول بـ﴿وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ﴾، وختم السورة بـ﴿وَخَسِرَ هُنَالِكَ الْكَافِرُونَ﴾؟","answer":"الفاصلة الأولى سبقتها عبارة ﴿قُضِيَ بِالْحَقِّ﴾، ومقابل الحق الباطل، فكان الأنسب ﴿المبطلون﴾. أما ختام السورة فسبقته عبارة ﴿فَلَمْ يَكُ يَنْفَعُهُمْ إِيمَانُهُمْ﴾، ومقابل الإيمان الكفر، فكان الأنسب ﴿الكافرون﴾. هكذا تنبثق كل فاصلة من المعنى الأقرب إليها، ولا تؤدي إحداهما دقة الأخرى في موضعها.","sources":[{"label":"فاضل السامرائي، دلالة اختلاف الفاصلة بين «المبطلون» و«الكافرون» في سورة غافر – بوابة إسلاميات.","url":""}]},{"id":"s40-206","number":206,"surah":40,"verses":[79,81],"references":[{"surah":40,"verses":[79,81]}],"verseLabel":"غافر: 79، 81","question":"ما سر التعبير بـ﴿جَعَلَ لَكُمُ الْأَنْعَامَ﴾ في غافر، وبـ﴿خَلَقْنَا لَهُمْ... أَنْعَامًا﴾ في يس؟","answer":"الخلق ابتداءً أدل على العناية والامتنان من مجرد جعل الموجود مسخرًا للانتفاع، وقد فُصّلت النعم في يس بملك الأنعام وتذليلها والمآكل والمشارب، ثم خُتمت بالدعوة إلى الشكر: ﴿أفلا يشكرون﴾؛ فناسبها ﴿خلقنا لهم﴾. أما غافر فسياق عرض الآيات وإنكارها، وتكرر فيه فعل «جعل»، فناسبه ﴿جعل لكم﴾ ثم ﴿فأي آيات الله تنكرون﴾.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين «خلقنا لهم» في يس و«جعل لكم» في غافر – تدارس القرآن الكريم.","url":""}]},{"id":"s40-207","number":207,"surah":40,"verses":[15],"references":[{"surah":40,"verses":[15]}],"verseLabel":"غافر: 15","question":"ما سر حذف الياء من ﴿يَوْمَ التَّلَاقِ﴾، وما الصورة التي يرسمها هذا الحذف ليوم القيامة؟","answer":"من سنن التعبير القرآني أن يُقتطع من اللفظ ما يناسب قِصر الحدث أو عدم جريانه على صورته الكاملة. والتلاقي يوم القيامة ليس كتلاقي الدنيا؛ فلا طول مكث ولا تبادل للأشواق والأحاديث، بل فرار وشغل بالحساب، فاقتُطعت الياء لتناسب هذا التلاقي المقتضب، مع ملاءمة الحذف لفواصل الآيات.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص166–167، مبحث «ما سر حذف الياء من التلاق؟»؛ وانظر النص المنقول من الكتاب – تدارس القرآن الكريم.","url":""}]},{"id":"s40-208","number":208,"surah":40,"verses":[17],"references":[{"surah":40,"verses":[17]}],"verseLabel":"غافر: 17","question":"ما دلالة تقديم الجزاء على نفي الظلم في ﴿الْيَوْمَ تُجْزَى كُلُّ نَفْسٍ... لَا ظُلْمَ الْيَوْمَ﴾، مع تقديم نفي الظلم في سورة يس؟","answer":"سياق غافر قائم على العقيدة والحساب والجزاء، فناسب أن يبدأ بما هو محور المقام: جزاء كل نفس بما كسبت، ثم ينفي الظلم. أما سورة يس فبرز فيها ظلم الجماعات للرسل والرجل المؤمن ومنع حق الفقراء والخصومة بين الناس، فناسب أن يتقدم فيها نفي الظلم. فالتقديم في الموضعين تابع للغرض الغالب في السياق.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، سر اختلاف ترتيب الجزاء ونفي الظلم في غافر ويس – باحث.","url":""}]},{"id":"s40-209","number":209,"surah":40,"verses":[29],"references":[{"surah":40,"verses":[29]}],"verseLabel":"غافر: 29","question":"ما سر اختيار ﴿سَبِيلَ الرَّشَادِ﴾ في دعوى فرعون ودعوة المؤمن، وما الفرق بين الرُّشد والرَّشد والرشاد؟","answer":"الرُّشد بالضم يستعمل في أمور الدنيا والآخرة، والرَّشد بالفتح يغلب في شؤون الآخرة، أما الرشاد فهو طريق القصد والصواب والصلاح، وهو نقيض الضلال. لذلك جاءت كلمة ﴿الرشاد﴾ مع «السبيل»؛ لأنها تصف الطريق الموصل إلى الصواب، فادعاه فرعون زورًا، ثم بيّن المؤمن سبيله الحق.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص140، مبحث «الفرق بين الرُّشد والرَّشد والرشاد»؛ وانظر النص الموثق من الكتاب.","url":""}]},{"id":"s40-210","number":210,"surah":40,"verses":[35],"references":[{"surah":40,"verses":[35]}],"verseLabel":"غافر: 35","question":"ما السر الدقيق في ﴿عَلَى كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ﴾ بدل «على قلب كل متكبر جبار»؟","answer":"الترتيب القرآني يجمع دلالتين في آن واحد: أن الطبع يشمل قلب المتكبر كله فلا يترك منه موضعًا، وأنه يشمل قلوب كل المتكبرين الجبارين. أما تقديم «قلب» على «كل» فيؤدي عموم أصحاب القلوب، لكنه لا يُظهر بالقوة نفسها استيعاب الطبع لأجزاء القلب كله؛ فكان النظم المختار أوسع دلالة.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، سر قوله «على كل قلب متكبر جبار» – تدارس القرآن الكريم.","url":""}]},{"id":"s40-211","number":211,"surah":40,"verses":[55],"references":[{"surah":40,"verses":[55]}],"verseLabel":"غافر: 55","question":"ما سر تعريف الزمن في ﴿بِالْعَشِيِّ وَالْإِبْكَارِ﴾، مع تنكيره في مواضع مثل «بكرةً وعشيًّا»؟","answer":"التعريف في «العشي والإبكار» يفيد الجنس والاستمرار والتجدد، أي التسبيح في هذه الأوقات على وجه الدوام، لا في صباح أو مساء مخصوصين. أما «بكرةً وعشيًّا» فيناسب وقتًا أو أيامًا معينة يحددها السياق. ولأن الأمر للنبي بالتسبيح غير مقيد بأيام، جاء الزمن معرفًا.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين «بكرة وعشيًا» و«بالعشي والإبكار» – تدارس القرآن الكريم.","url":""}]},{"id":"s40-212","number":212,"surah":40,"verses":[56],"references":[{"surah":40,"verses":[56]}],"verseLabel":"غافر: 56","question":"ما سر ختم الاستعاذة من مجادلة البشر بـ﴿السَّمِيعُ الْبَصِيرُ﴾، وختم الاستعاذة من نزغ الشيطان بـ«السميع العليم»؟","answer":"المجادلون في غافر بشر تُسمع أقوالهم وتُرى أفعالهم، فناسبهم ﴿السميع البصير﴾. أما نزغ الشيطان ووسوسته فهما خفيان لا يُريان، وإنما يعلمهـما الله، فناسبهما «السميع العليم». وجاء في غافر ضمير الفصل والتعريف: ﴿إنه هو السميع البصير﴾ لتوكيد انفراده بكمال السمع والبصر في سياق كشف خائنة الأعين وما تخفي الصدور.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين «السميع البصير» في غافر و«السميع العليم» – تدارس القرآن الكريم، وانظر تفصيل التوكيد والقصر في الآية.","url":""}]},{"id":"s40-213","number":213,"surah":40,"verses":[66],"references":[{"surah":40,"verses":[66]}],"verseLabel":"غافر: 66","question":"ما سر تذكير الفعل في ﴿لَمَّا جَاءَنِيَ الْبَيِّنَاتُ﴾، وتأنيثه في مواضع ﴿جَاءَتْهُمُ الْبَيِّنَاتُ﴾؟","answer":"التذكير والتأنيث جائزان من جهة النحو لأن «البينات» جمع غير حقيقي التأنيث، لكن الاختيار البياني مرتبط بالدلالة. إذا أريد بالبينات الأمر والنهي وأحكام الدين غلب التذكير، وهو المناسب هنا لاقترانها بـ﴿نُهِيتُ﴾ و﴿أُمِرْتُ﴾؛ وإذا أريد بها الآيات الدالة على صدق النبوة والمعجزات جاء الفعل مؤنثًا.","sources":[{"label":"فاضل السامرائي، الفرق بين «جاءهم البينات» و«جاءتهم البينات» – باحث.","url":""}]},{"id":"s40-214","number":214,"surah":40,"verses":[68],"references":[{"surah":40,"verses":[68]}],"verseLabel":"غافر: 68","question":"ما سر اختلاف البناء بين ﴿فَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾ وقوله في يس: ﴿إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"آية يس جملة اسمية: «أمره» مبتدأ و«أن يقول» خبره، وبينهما جملة شرطية اعتراضية حُذف جوابها لدلالة ما حولها عليه. أما آية غافر فشرط صريح: ﴿إذا قضى﴾، وجوابه ﴿فإنما يقول﴾، واقترنت الفاء بالجواب وجوبًا. فليس الاختلاف مجرد تنويع لفظي؛ بل كل صياغة محكومة ببنائها النحوي ودلالتها.","sources":[{"label":"فاضل السامرائي، سورة غافر، الآية 68: اللمسة البيانية في اختلافها عن آية يس – بوابة إسلاميات.","url":""}]},{"id":"s40-215","number":215,"surah":40,"verses":[78],"references":[{"surah":40,"verses":[78]}],"verseLabel":"غافر: 78","question":"ما سر اختيار ﴿فَإِذَا جَاءَ أَمْرُ اللَّهِ﴾ هنا، مع قوله في النحل ﴿أَتَى أَمْرُ اللَّهِ﴾؟","answer":"«أتى» أخف من «جاء» في الاستعمال القرآني، وقد ورد في النحل عن أمر اقترب ولم يقع بعد، بدليل ﴿فلا تستعجلوه﴾. أما آية غافر فتصوّر الأمر واقعًا بما يترتب عليه من القضاء بالحق وخسران المبطلين، فناسبها الفعل الأثقل ﴿جاء﴾؛ لأن المشهد تحقق وظهرت آثاره الحاسمة.","sources":[{"label":"فاضل السامرائي، سورة غافر، الآية 78: الفرق بين «أتى» و«جاء» – بوابة إسلاميات.","url":""}]},{"id":"s41-1","number":1,"surah":41,"verses":[1],"references":[{"surah":41,"verses":[1]}],"verseLabel":"عنوان السورة","question":"لماذا سُمّيت سورة فصلت بهذا الاسم؟","answer":"لأن السورة أبرزت وصف القرآن بأنه كتاب فُصّلت آياته: بُيّنت معانيه وأحكامه وطرائق هدايته، فصار هذا الوصف البارز اسمًا دالًا على مركزية البيان القرآني فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص108–109، تحت عنوان «أسماء السورة ومناسبة تسميتها»","url":""}]},{"id":"s41-2","number":2,"surah":41,"verses":[1],"references":[{"surah":41,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما دلالة تسمية السورة أيضًا بـ«حم السجدة»؟","answer":"يجمع الاسم بين افتتاحها بـ﴿حم﴾ وموضع السجدة فيها، فيميزها من سائر السور المفتتحة بالحرفين. ويصل ذكر السجدة اسم السورة بمشهد الخضوع لله الذي تقابله مواقف المعرضين عن آياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص108–109، تحت عنوان «أسماء السورة ومناسبة تسميتها»","url":""}]},{"id":"s41-3","number":3,"surah":41,"verses":[1],"references":[{"surah":41,"verses":[1]}],"verseLabel":"بناء السورة","question":"ما الخصيصة الأسلوبية في تكرر الحديث عن السآمة في سورة فصلت؟","answer":"تكرر الحديث عن السآمة في موضعين من السورة، وهو تكرار يرتبط بمحورها في كشف حال الإنسان حين يعرض عن الهدى أو يملّ؛ فيلفت القارئ إلى أثر الاستجابة للوحي في علاج هذا الاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص113، تحت عنوان «الخصائص الأسلوبية لسورة فصلت»","url":""}]},{"id":"s41-4","number":4,"surah":41,"verses":[1,2,3],"references":[{"surah":41,"verses":[1,2,3]}],"verseLabel":"فصلت: 1–3","question":"ماذا يفيد التعبير بالمصدر ﴿تَنْزِيلٌ﴾ في مطلع سورة فصلت؟","answer":"يجعل التنزيل كأنه حقيقة قائمة بذاتها مشحونة بالعظمة، ويؤكد أن القرآن منزل من الرحمن الرحيم؛ فتجتمع في اللفظ مهابة الوحي وصدق مصدره ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص118، تحت عنوان «دلالة التعبير بالمصدر ﴿تنزيل﴾»","url":""}]},{"id":"s41-5","number":5,"surah":41,"verses":[2],"references":[{"surah":41,"verses":[2]}],"verseLabel":"فصلت: 2","question":"لماذا خُصَّ الاسمان ﴿الرَّحْمَنِ الرَّحِيمِ﴾ بالذكر عند الحديث عن تنزيل القرآن؟","answer":"لأن إنزال القرآن من أعظم آثار رحمة الله: به يخرج الناس من ظلمات الجهل والضلال إلى نور الهداية، فناسب أن يُنسب التنزيل إلى الاسمين الدالين على الرحمة العامة والخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص122، تحت عنوان «توجيه تخصيص صفتي ﴿الرحمن الرحيم﴾ بالذكر»","url":""}]},{"id":"s41-6","number":6,"surah":41,"verses":[3],"references":[{"surah":41,"verses":[3]}],"verseLabel":"فصلت: 3","question":"ما سر اختيار ﴿فُصِّلَتْ آيَاتُهُ﴾ بدل «بُيّنت آياته»؟","answer":"التفصيل يزيد على أصل البيان بإظهار تميز المعاني والأحكام وترتيبها في مقاطع واضحة؛ فالآيات تبين القصص والمواعظ والتشريع دون اختلاط. وفي الصيغة معنى الإحكام وإعطاء كل معنى موضعه، فيجتمع وضوح الدلالة وحسن التنظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص124–125، تحت عنوان «بلاغة اختيار مفردة ﴿فصلت﴾ دون (بينت)»","url":""}]},{"id":"s41-7","number":7,"surah":41,"verses":[3],"references":[{"surah":41,"verses":[3]}],"verseLabel":"فصلت: 3","question":"لماذا جمع القرآن بين وصفه بأنه ﴿كِتَابٌ﴾ وأنه ﴿قُرْآنًا﴾؟","answer":"للدلالة على أنه محفوظ بطريقين متكاملين: مكتوب في السطور بوصفه كتابًا، ومتلوّ محفوظ في الصدور بوصفه قرآنًا؛ فتتآزر الكتابة والقراءة في حفظه وتبليغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص123، تحت عنوان «بلاغة الجمع بين لفظي ﴿كتاب﴾ و﴿قرآنًا﴾»","url":""}]},{"id":"s41-8","number":8,"surah":41,"verses":[3],"references":[{"surah":41,"verses":[3]}],"verseLabel":"فصلت: 3","question":"ماذا تضيف صيغة المضارع في قوله ﴿لِقَوْمٍ يَعْلَمُونَ﴾؟","answer":"تصور العلم صفة متجددة مستمرة فيهم، وتفتح باب الانتفاع لكل من يدخل في طريق التعلم والتدبر، لا لفئة انقضى علمها في زمن مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص128، تحت عنوان «نكتة التعبير بصيغة المضارع ﴿يعلمون﴾»","url":""}]},{"id":"s41-9","number":9,"surah":41,"verses":[4],"references":[{"surah":41,"verses":[4]}],"verseLabel":"فصلت: 4","question":"لماذا قُدّمت البشارة على النذارة في وصف القرآن ﴿بَشِيرًا وَنَذِيرًا﴾؟","answer":"لأن القرآن وُصف بأنه تنزيل من الرحمن الرحيم؛ فناسب مقتضى الرحمة أن تُفتح البشارة أولًا لترغيب العباد، ثم يأتي الإنذار لمن أعرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص130–131، تحت عنوان «نكتة تقديم ﴿بشيرًا﴾ على ﴿نذيرًا﴾»","url":""}]},{"id":"s41-10","number":10,"surah":41,"verses":[4],"references":[{"surah":41,"verses":[4]}],"verseLabel":"فصلت: 4","question":"ما دلالة قوله ﴿فَأَعْرَضَ أَكْثَرُهُمْ﴾ دون تعميم الإعراض عليهم جميعًا؟","answer":"يقيد الحكم بالأكثر فيثبت أن الإعراض لم يشمل الجميع، ويحفظ للمؤمنين موقعهم وإن قل عددهم. كما يمنع الاغترار بالكثرة؛ فقد يكون الحق مع القلة، فلا يجعل كثرة المعرضين دليلًا على صحة موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص132–133، تحت عنوان «دلالة التعبير بلفظ (أكثر)»","url":""}]},{"id":"s41-11","number":11,"surah":41,"verses":[4],"references":[{"surah":41,"verses":[4]}],"verseLabel":"فصلت: 4","question":"كيف نُفي السماع عن المعرضين في ﴿فَهُمْ لَا يَسْمَعُونَ﴾ مع سلامة آذانهم؟","answer":"نُفي عنهم سماع الانتفاع والقبول، لا وصول الصوت؛ لأنهم عطّلوا ثمرة السمع حتى صاروا كمن لا يسمع، وفي ذلك توبيخ لهم على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص134، تحت عنوان «بلاغة الكناية ودلالتها»","url":""}]},{"id":"s41-12","number":12,"surah":41,"verses":[5],"references":[{"surah":41,"verses":[5]}],"verseLabel":"فصلت: 5","question":"لماذا رتّب المعرضون موانعهم من أكنّة القلوب إلى وقر الآذان ثم الحجاب؟","answer":"رتبوها بحسب طريق وصول الوحي: القلب محل الفهم، والأذن سبيل الاستماع، والحجاب يمنع المواجهة والرؤية؛ فزعموا انسداد منافذ الإدراك كلها ليبالغوا في إعلان القطيعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص146–147، تحت عنوان «براعة ترتيب ذكر القلوب فالأسماع فالأبصار»","url":""}]},{"id":"s41-13","number":13,"surah":41,"verses":[5],"references":[{"surah":41,"verses":[5]}],"verseLabel":"فصلت: 5","question":"ما دلالة قول المعرضين ﴿فَاعْمَلْ﴾ بعد دعوى الحجاب بينهم وبين الرسول ﷺ؟","answer":"ليس أمرًا حقيقيًا، بل تهديد وتخلية: امضِ في دعوتك فسنبقى على طريقنا ونقابلك بالرفض، وفيه إعلان العناد بدل طلب البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص148، تحت عنوان «غرض الأمر ومقصده الدلالي»","url":""}]},{"id":"s41-123","number":123,"surah":41,"verses":[5],"references":[{"surah":41,"verses":[5]}],"verseLabel":"فصلت: 5","question":"لماذا أكّد المعرضون قولهم ﴿إِنَّنَا عَامِلُونَ﴾؟","answer":"ليظهروا شدة إصرارهم وثباتهم على موقفهم، وليجعلوا الجملة تحديًا في مقابلة دعوة الرسول ﷺ، لا مجرد إخبار عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص149، تحت عنوان «بلاغة توكيد الخبر»","url":""}]},{"id":"s41-14","number":14,"surah":41,"verses":[6],"references":[{"surah":41,"verses":[6]}],"verseLabel":"فصلت: 6","question":"ما الذي يحترز منه قوله بعد إثبات البشرية ﴿يُوحَى إِلَيَّ﴾؟","answer":"يمنع أن تُفهم المماثلة على الإطلاق؛ فهو يماثلهم في جنس البشرية، لكنه اختص عنهم بالوحي والرسالة، فتثبت البشرية من غير أن تُلغى منزلته النبوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص155–156، تحت عنوان «بلاغة الاحتراس بالوصف»","url":""}]},{"id":"s41-15","number":15,"surah":41,"verses":[6],"references":[{"surah":41,"verses":[6]}],"verseLabel":"فصلت: 6","question":"لماذا فُرّع الأمر ﴿فَاسْتَقِيمُوا إِلَيْهِ﴾ على تقرير وحدانية الله؟","answer":"لأن الإقرار بإله واحد يقتضي توجيه العبادة والقصد إليه وحده؛ فجاءت الفاء لتجعل الاستقامة أثرًا عمليًا مباشرًا للتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص157–158، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s41-16","number":16,"surah":41,"verses":[6],"references":[{"surah":41,"verses":[6]}],"verseLabel":"فصلت: 6","question":"لماذا عُطف الاستغفار على الاستقامة في ﴿فَاسْتَقِيمُوا إِلَيْهِ وَاسْتَغْفِرُوهُ﴾؟","answer":"لأن الاستقامة تصلح الطريق المقبل، والاستغفار يمحو تقصير الماضي وما يعرض في السير من زلل؛ فجمع الأمران بين الثبات على الحق وتنقية آثاره مما يشوبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص159، تحت عنوان «دلالة عطف الاستغفار على الاستقامة»","url":""}]},{"id":"s41-17","number":17,"surah":41,"verses":[7],"references":[{"surah":41,"verses":[7]}],"verseLabel":"فصلت: 7","question":"لماذا قُرن منع الزكاة بالكفر بالآخرة في وصف المشركين؟","answer":"لأن الإيمان بالجزاء هو الذي يدفع إلى البذل ومراقبة حق الله في المال؛ فمن جحد الآخرة هان عليه الشح ومنع الحقوق، فجمع الوصفان بين فساد الاعتقاد وأثره في السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص163، تحت عنوان «نكتة قرن منع الزكاة بالكفر بالآخرة»","url":""}]},{"id":"s41-18","number":18,"surah":41,"verses":[7],"references":[{"surah":41,"verses":[7]}],"verseLabel":"فصلت: 7","question":"ما فائدة تكرار ضمير ﴿هُمْ﴾ في ﴿وَهُمْ بِالْآخِرَةِ هُمْ كَافِرُونَ﴾؟","answer":"يقوي الحكم ويؤكد ذمهم، ويبرز شدة تعنتهم واختصاصهم الراسخ بالكفر بالآخرة؛ فكأن الوصف صار سمة ثابتة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص164، تحت عنوان «فائدة استعمال ضمير ﴿هم﴾ وتكراره»","url":""}]},{"id":"s41-19","number":19,"surah":41,"verses":[8],"references":[{"surah":41,"verses":[8]}],"verseLabel":"فصلت: 8","question":"ما سر وصف أجر المؤمنين بأنه ﴿غَيْرُ مَمْنُونٍ﴾؟","answer":"على التوجيه الذي يربط المن بالأذى في العطاء، يصف الأجر بأنه خال من الإذلال والتكدير. فالمؤمنون ينالون جزاءً يكرمهم، وتأتي العبارة في سياق ذم البخل لتقابل عطاء الناس الذي قد يصحبه المن بعطاء الله المكرم لعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص171، تحت عنوان «بلاغة ذكر مفردة ﴿ممنون﴾»","url":""}]},{"id":"s41-20","number":20,"surah":41,"verses":[9],"references":[{"surah":41,"verses":[9]}],"verseLabel":"فصلت: 9","question":"ما أثر اجتماع الاستفهام والتوكيد في قوله ﴿أَئِنَّكُمْ لَتَكْفُرُونَ﴾؟","answer":"يجعل الاستفهام إنكارًا وتعجيبًا من كفرهم، ثم يأتي التوكيد لا لتقوية خبر محتمل بل لتثبيت الفعل الشنيع الذي يُوبَّخون عليه؛ فكأن وقوعه مع وضوح دلائل الخالق أمر لا يكاد يُصدَّق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص175، تحت عنوان «دلالة التوكيد ونكتة إدخال الاستفهام عليه»","url":""}]},{"id":"s41-21","number":21,"surah":41,"verses":[9],"references":[{"surah":41,"verses":[9]}],"verseLabel":"فصلت: 9","question":"لماذا بدأ تفصيل الخلق بذكر الأرض قبل السماء؟","answer":"لأن الأرض أقرب إلى الإنسان وأظهر اتصالًا بمعاشه، فبدئ بالدليل المحسوس الذي يشاهده المخاطبون ثم ارتقي إلى خلق السماء، فتكون الحجة أقرب إلى إدراكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص177، تحت عنوان «علة تقديم ذكر خلق الأرض»","url":""}]},{"id":"s41-124","number":124,"surah":41,"verses":[9],"references":[{"surah":41,"verses":[9]}],"verseLabel":"فصلت: 9","question":"ما الذي توحي به عبارة ﴿خَلَقَ الْأَرْضَ فِي يَوْمَيْنِ﴾ مع قدرة الله على خلقها في لحظة؟","answer":"تدل على أن الخلق جرى بتقدير وحكمة وتدرج، لا لعجز أو احتياج إلى زمن؛ فذكر اليومين يعلّم أن الإحكام قد يظهر في ترتيب الأسباب والمراحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص178، تحت عنوان «بلاغة الكناية في الظرف»","url":""}]},{"id":"s41-22","number":22,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ما سر التعبير بالجعل مع الرواسي وبالخلق مع الأرض؟","answer":"الخلق يدل هنا على إنشاء الأرض، والجعل على تهيئة ما فيها وتحويله إلى هيئة تحقق الغرض منه. فاختير الجعل للرواسي لأنها تفصيل في إعداد الأرض لوظيفتها بعد ذكر أصل خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص184–185، تحت عنوان «نكتة استعمال الجعل دون الخلق»","url":""}]},{"id":"s41-23","number":23,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ما دلالة التصريح بأن الرواسي جُعلت ﴿مِنْ فَوْقِهَا﴾ مع أن ذلك مشاهد؟","answer":"لا يكتفي التعبير بإثبات الجبال، بل يصور ارتفاعها ظاهرًا فوق الأرض. وحرف ﴿من﴾ يستحضر ابتداء هذا العلو منها، فيلفت النظر إلى هيئة الرواسي المشاهدة بوصفها مظهرًا من مظاهر القدرة والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص186، تحت عنوان «براعة دخول حرف ﴿من﴾ على الظرف»","url":""}]},{"id":"s41-24","number":24,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"لماذا قُدّمت البركة في الأرض على تقدير أقواتها؟","answer":"لأن البركة أصل عام لنماء الخيرات واستمرارها، ثم جاء تقدير الأقوات أثرًا مفصلًا من آثارها؛ فقدم الأساس الشامل قبل ما يتفرع عنه من أرزاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص186، تحت عنوان «دلالة تقديم ذكر البركة على تقدير الأقوات»","url":""}]},{"id":"s41-125","number":125,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ماذا تضيف كلمة ﴿قَدَّرَ﴾ في قوله ﴿وَقَدَّرَ فِيهَا أَقْوَاتَهَا﴾؟","answer":"تفيد أن الأقوات وُزعت بمقادير محسوبة تفي بحاجات المخلوقات، فلا تجري الأرزاق عبثًا بل وفق علم وتدبير وإحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص187، تحت عنوان «دلالة استعمال مفردة ﴿قدّر﴾»","url":""}]},{"id":"s41-25","number":25,"surah":41,"verses":[9,10],"references":[{"surah":41,"verses":[9,10]}],"verseLabel":"فصلت: 9–10","question":"ما سر التعبير بأربعة أيام في تقدير الأقوات مع سبق ذكر خلق الأرض في يومين؟","answer":"الأربعة إجمال للمدة كلها، يدخل فيها اليومان المذكوران أولًا، وليست أربعة مضافة إليهما. وهذه فذلكة تجمع المراحل بعد تفصيل بعضها، ويدل عليها اتصال أعمال التهيئة بخلق الأرض وإتمام العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص190–191، تحت عنوان «بلاغة الفذلكة ودلالتها»","url":""}]},{"id":"s41-26","number":26,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ماذا تفيد كلمة ﴿سَوَاءً﴾ بعد ذكر خلق الأرض وتقدير أقواتها؟","answer":"تفيد تمام الأيام الأربعة واستواءها بلا زيادة ولا نقص: يومان لخلق الأرض ويومان لتقدير ما فيها، فتزيل توهم أن الأزمنة المذكورة متراكمة إلى أكثر من ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص191، تحت عنوان «دلالة لفظ ﴿سواء﴾»","url":""}]},{"id":"s41-126","number":126,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"لماذا خُتم تقدير الأقوات بقوله ﴿لِلسَّائِلِينَ﴾؟","answer":"يشمل اللفظ من يسأل رزقه طلبًا، ومن يتطلع إلى معرفة كيفية الخلق؛ فيصور الأقوات مهيأة لحاجات الخلق، ويجعل البيان جوابًا لمن يتدبر ويسأل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص191–192، تحت عنوان «بلاغة اختيار مفردة ﴿للسائلين﴾»","url":""}]},{"id":"s41-27","number":27,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"ما سر التعبير عن السماء بأنها كانت ﴿دُخَانٌ﴾؟","answer":"على التوجيه البلاغي الذي تعرضه الموسوعة، يشبه الدخان هيئة المادة قبل إحكامها، لما في صورته من لطف وتفرق. ثم يأتي إتمام السماوات ليبرز الانتقال من هذه الهيئة إلى خلق محكم مقدر، فتقرب الصورة معنى التكوين إلى الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص193–194، تحت عنوان «بلاغة التشبيه في لفظ ﴿دخان﴾»","url":""}]},{"id":"s41-28","number":28,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"ما الصورة التي يرسمها قوله للسماء والأرض ﴿ائْتِيَا﴾؟","answer":"يمثلهما بمخاطبَين يسمعان أمر خالقهما ويجيبان، فتجسد الصورة انقياد الكون كله وسرعة امتثاله لإرادة الله من غير عجز ولا امتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص194، تحت عنوان «توجيه الاستعارة والتمثيل في لفظ الإتيان»","url":""}]},{"id":"s41-127","number":127,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"لماذا قيل للسماء والأرض ﴿طَوْعًا أَوْ كَرْهًا﴾؟","answer":"للتعريض بالمشركين: فالسماء والأرض، على عظم خلقهما، منقادتان لأمر الله في كل حال، فكيف يتخلف الإنسان الضعيف عن طاعته؟ كما تؤكد العبارة أن إرادته نافذة لا يخرج عنها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص195، تحت عنوان «بلاغة التعريض بلفظ الكره والطوع»","url":""}]},{"id":"s41-29","number":29,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"لماذا قالت السماء والأرض ﴿أَتَيْنَا طَائِعِينَ﴾ بصيغة جمع العقلاء لا «طائعتين»؟","answer":"لأن الخطاب صوّرهما كعاقلين يسمعان الأمر ويجيبان عنه، فناسب أن يأتي جوابهما بصيغة جمع العقلاء؛ وفي ذلك تجسيد لكمال انقيادهما وسرعة امتثالهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص197، تحت عنوان «نكتة صيغة جمع الجماد بجمع العقلاء»","url":""}]},{"id":"s41-30","number":30,"surah":41,"verses":[11,12],"references":[{"surah":41,"verses":[11,12]}],"verseLabel":"فصلت: 11–12","question":"لماذا عادت السماء المفردة في قوله ﴿وَهِيَ دُخَانٌ﴾ ضميرَ جمع في ﴿فَقَضَاهُنَّ سَبْعَ سَمَاوَاتٍ﴾؟","answer":"ذُكرت السماء أولًا اسمَ جنسٍ للمادة العلوية وهي دخان، فلما قُضيت وفُصلت طبقاتها ظهرت حقيقتها المعدودة سبع سماوات، فعاد الضمير جمعًا إلى ما آل إليه ذلك الجنس بعد التفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص202–203، تحت عنوان «عود الضمير في فعل القضاء»","url":""}]},{"id":"s41-31","number":31,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"لماذا عبّر عن تدبير كل سماء بقوله ﴿وَأَوْحَى﴾؟","answer":"لأن الوحي يدل على إلقاء خفي سريع؛ فصوّر ما أودعه الله في كل سماء من نظام وتكاليف وتدبير كأمر نافذ يصل إليها بلا إبطاء، ويشمل ما أوحاه إلى ملائكتها وما أجراه في أجرامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص204، تحت عنوان «دلالة فعل الوحي مادة وصيغة»","url":""}]},{"id":"s41-128","number":128,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"ماذا تضيف كلمة ﴿كُلِّ﴾ في قوله ﴿فِي كُلِّ سَمَاءٍ﴾؟","answer":"تفيد استغراق السماوات جميعًا: لكل سماء نظامها وأمرها الخاص، فلا تُترك واحدة منها بلا تدبير يناسب خلقها ووظيفتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص205، تحت عنوان «دلالة ﴿كل﴾ مضافًا إلى السماء»","url":""}]},{"id":"s41-129","number":129,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"ماذا يشمل لفظ ﴿أَمْرَهَا﴾ في قوله ﴿وَأَوْحَى فِي كُلِّ سَمَاءٍ أَمْرَهَا﴾؟","answer":"يشمل ما خص الله به كل سماء من الشؤون والتدبير، وما فيها من أوامر الملائكة وتكاليفهم، وما أودعه في أجرامها من نظام؛ فجاء اللفظ جامعًا لأسرارها ووظائفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص205، تحت عنوان «نكتة التعبير بلفظ الأمر»","url":""}]},{"id":"s41-32","number":32,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"لماذا جمع قوله ﴿وَزَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَحِفْظًا﴾ بين الزينة والحفظ؟","answer":"ليبين أن لهذه المصابيح وظيفتين متكاملتين: فهي جمال للناظرين وحراسة للسماء من استراق الشياطين؛ فاجتمع الحسن والمنفعة في خلق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص208، تحت عنوان «دلالة عطف الحفظ بالواو»","url":""}]},{"id":"s41-33","number":33,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"لماذا خُتم وصف خلق السماوات والأرض بقوله ﴿ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ﴾؟","answer":"لأن هذا النظام الهائل يحتاج قدرة لا تُغلب وعلمًا يحيط بكل تفصيل؛ فالعزة تناسب إحكام السلطان والتنفيذ، والعلم يناسب دقة المقادير والسنن التي جرى عليها الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص210، تحت عنوان «سر إيثار لفظي ﴿العزيز العليم﴾»","url":""}]},{"id":"s41-34","number":34,"surah":41,"verses":[13],"references":[{"surah":41,"verses":[13]}],"verseLabel":"فصلت: 13","question":"كيف سُمّي عذاب عاد ﴿صَاعِقَةً﴾ مع أن الذي أهلكهم ريح؟","answer":"استعيرت الصاعقة لكل عذاب شديد مهلك يأتي بغتة؛ فالمراد هنا هول الريح المدمرة وأثرها الصاعق، لا الصاعقة الكهربائية خاصة، وبذلك يجتمع عذاب عاد وثمود تحت صورة الهلاك المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص216–217، تحت عنوان «بلاغة الاستعارة في لفظ الصاعقة»","url":""}]},{"id":"s41-35","number":35,"surah":41,"verses":[13],"references":[{"surah":41,"verses":[13]}],"verseLabel":"فصلت: 13","question":"لماذا جُمعت عاد وثمود في إنذار واحد بـ﴿صَاعِقَةً مِثْلَ صَاعِقَةِ عَادٍ وَثَمُودَ﴾ مع اختلاف أداة هلاكهما؟","answer":"لأن التشبيه في جنس العذاب المهلك المفاجئ لا في أداته؛ فالريح صعقت عادًا، والصيحة صعقت ثمود، واتحدت العاقبة التي ينبغي أن يخافها المكذبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص217، تحت عنوان «علة الوصف بـ﴿مثل﴾»","url":""}]},{"id":"s41-36","number":36,"surah":41,"verses":[14],"references":[{"surah":41,"verses":[14]}],"verseLabel":"فصلت: 14","question":"ما الصورة التي يرسمها مجيء الرسل ﴿مِنْ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ﴾؟","answer":"تصور الرسل وقد أحاطوا بأقوامهم دعوةً وإنذارًا من كل جهة، فلم يتركوا سبيلًا للنصح إلا سلكوه؛ وتشمل كذلك تتابع الرسل في حاضرهم ومن مضى قبلهم، فتقوم الحجة من الجهات والأزمنة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص226، تحت عنوان «بلاغة الاستعارة في الجملة»","url":""}]},{"id":"s41-37","number":37,"surah":41,"verses":[14],"references":[{"surah":23,"verses":[24]},{"surah":41,"verses":[14]}],"verseLabel":"فصلت: 14؛ المؤمنون: 24","question":"لماذا قال المكذبون ﴿لَوْ شَاءَ رَبُّنَا لَأَنْزَلَ مَلَائِكَةً﴾ باسم الرب مضافًا إليهم؟","answer":"أرادوا أن يوهموا أن ربهم الذي يتولاهم لو أراد هدايتهم لاختار لهم ملائكة، فاتخذوا معنى الربوبية حجة على اعتراضهم، مع أن من تمام ربوبيته أن يختار لرسالته من يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص230، تحت عنوان «وجه إيثار اسم الرب مضافًا»","url":""}]},{"id":"s41-38","number":38,"surah":41,"verses":[15],"references":[{"surah":41,"verses":[15]}],"verseLabel":"فصلت: 15","question":"ما أثر الرد على تفاخر عاد ﴿مَنْ أَشَدُّ مِنَّا قُوَّةً﴾ بقوله ﴿هُوَ أَشَدُّ مِنْهُمْ قُوَّةً﴾؟","answer":"جاء الرد من جنس عبارتهم ليقلب الموازنة عليهم: إن كانوا يزعمون القوة، فالذي خلقهم أشد منهم قوة بلا قياس؛ فاستعمال التفضيل يجاري دعواهم ثم يهدم غرورهم من داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص247، تحت عنوان «توجيه استخدام أفعل التفضيل»","url":""}]},{"id":"s41-39","number":39,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]}],"verseLabel":"فصلت: 16","question":"لماذا وُصفت الريح التي أهلكت عاد بأنها ﴿صَرْصَرًا﴾؟","answer":"لأن الكلمة تستحضر ريحًا شديدة البرودة والصوت، وتكرار حروفها يحاكي صريرها وقسوتها؛ فكانت عقوبة تناسب قومًا اغتروا بقوتهم، إذ حطمتهم قوة لا يملكون دفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص254، تحت عنوان «سر الوصف بـ﴿صرصرًا﴾»","url":""}]},{"id":"s41-40","number":40,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]},{"surah":54,"verses":[19]}],"verseLabel":"فصلت: 16؛ القمر: 19","question":"لماذا وُصفت أيام عذاب عاد في فصلت بأنها ﴿أَيَّامٍ نَحِسَاتٍ﴾؟","answer":"لأن الشؤم أحاط بهم في تلك الأيام بما نزل فيها من عذاب متتابع، فوصف الأيام بالنحس من جهة ما وقع فيها، وكانت أيامًا متعددة لأن الريح استمرت عليهم زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص255، تحت عنوان «سر وصف الأيام بالنحسات»","url":""}]},{"id":"s41-130","number":130,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]},{"surah":54,"verses":[19]}],"verseLabel":"فصلت: 16؛ القمر: 19","question":"ماذا يضيف وصف يوم عذاب عاد في سورة القمر بأنه ﴿نَحْسٍ مُسْتَمِرٍّ﴾؟","answer":"يصور النحس ممتدًا لا ينقطع خلال اليوم، أو متصل الأثر حتى يبلغ العذاب غايته؛ فليس شؤمًا عابرًا بل زمنًا استمر عليهم بالهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص504–505، تحت عنوان «بلاغة الوصف في قوله ﴿مستمر﴾»","url":""}]},{"id":"s41-41","number":41,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]}],"verseLabel":"فصلت: 16","question":"لماذا قيل عن عذاب الآخرة بعد خزي الدنيا إنه ﴿أَخْزَى﴾؟","answer":"لأن خزي الآخرة أشد وأدوم: يجمع انكشاف الذل أمام الخلق مع العذاب الذي لا ينقطع، فجاء اسم التفضيل ليبين أن ما ذاقوه في الدنيا أهون من الفضيحة الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص259، تحت عنوان «سر التعبير بصيغة التفضيل»","url":""}]},{"id":"s41-42","number":42,"surah":41,"verses":[17],"references":[{"surah":41,"verses":[17]}],"verseLabel":"فصلت: 17","question":"كيف يصوّر قوله ﴿فَاسْتَحَبُّوا الْعَمَى عَلَى الْهُدَى﴾ اختيار ثمود للضلال؟","answer":"يجعل الضلال عمًى يحجب الحق، ويجعل الإيمان هدى يُبصر به الطريق؛ ثم يصورهم وكأنهم وازنوا بين النور والعمى فاختاروا العمى عن قصد، فتظهر بشاعة قرارهم ومسؤوليتهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص268، تحت عنوان «بلاغة الاستعارة في الجملة»","url":""}]},{"id":"s41-43","number":43,"surah":41,"verses":[17],"references":[{"surah":41,"verses":[17]}],"verseLabel":"فصلت: 17","question":"لماذا وُصف عذاب ثمود بأنه ﴿عَذَابِ الْهُونِ﴾ بعد استحبابهم العمى؟","answer":"لأنهم تكبروا على الهدى واختاروا الضلال عمدًا، فجاء عذابهم مهينًا مذلًا؛ فالهون لا يصف الألم وحده، بل يضيف إليه الخزي المقابل لاستعلائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص270، تحت عنوان «بلاغة وصف العذاب بالهون»","url":""}]},{"id":"s41-44","number":44,"surah":41,"verses":[16,17,18],"references":[{"surah":41,"verses":[16,17,18]}],"verseLabel":"فصلت: 16–18","question":"لماذا أعقب عذاب عاد وثمود بقوله ﴿وَنَجَّيْنَا الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ﴾؟","answer":"ليكتمل مشهد العدل: فالعذاب لا يعم الجميع بلا تمييز، بل يهلك المكذبين وينجي المؤمنين؛ فجاء العطف بعد قصة الهلاك ليبرز المصير المقابل مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص275، تحت عنوان «بلاغة العطف بالواو»","url":""}]},{"id":"s41-45","number":45,"surah":41,"verses":[19],"references":[{"surah":41,"verses":[19]}],"verseLabel":"فصلت: 19","question":"لماذا سُمّي المحشورون إلى النار ﴿أَعْدَاءَ اللَّهِ﴾؟","answer":"لأنهم عارضوا رسله وآياته واتخذوا الشيطان وليًا، فجمعهم الاسم في معسكر واحد من العداوة مهما اختلفت أقوامهم، وأضافهم إلى اسم الله لتفظيع من عادوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص282، تحت عنوان «سر إيثار لفظ الأعداء جمعًا مضافًا»","url":""}]},{"id":"s41-46","number":46,"surah":41,"verses":[20],"references":[{"surah":41,"verses":[20]}],"verseLabel":"فصلت: 20","question":"ما سر إفراد ﴿سَمْعُهُمْ﴾ وجمع ﴿أَبْصَارُهُمْ﴾ و﴿جُلُودُهُمْ﴾؟","answer":"السمع مصدر، والمصدر لا يجمع على نحو جمع أسماء الأعضاء، بخلاف الأبصار والجلود. وتذكر الموسوعة أيضًا أن وظيفة السمع تتقارب بين الناس، بينما تختلف الأنظار، فناسب ذلك الإفراد في الأول والجمع في الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص291–292، تحت عنوان «نكتة إفراد السمع»","url":""}]},{"id":"s41-47","number":47,"surah":41,"verses":[20],"references":[{"surah":41,"verses":[20]}],"verseLabel":"فصلت: 20","question":"ما دلالة ذكر الجلود مع السمع والأبصار في الشهادة عليهم؟","answer":"ذكرت هذه الجوارح لأن شهادتها تستوعب ما باشره الإنسان من أعمال؛ فالجلود متصلة باللمس، ويدخل إدراك الذوق في جملة ذلك على التوجيه المذكور. وذكرها مع السمع والأبصار يجعل الشهادة من بدن الإنسان نفسه على ما اجترحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص290–291، تحت عنوان «دلالة اصطفاء بعض الجوارح»","url":""}]},{"id":"s41-48","number":48,"surah":41,"verses":[20,21],"references":[{"surah":41,"verses":[20,21]}],"verseLabel":"فصلت: 20–21","question":"ما سر تخصيصهم الجلود بالسؤال ﴿لِمَ شَهِدْتُمْ عَلَيْنَا﴾ دون السمع والأبصار؟","answer":"لأن الجلود أعم اتصالًا بما باشرته الأعضاء من أعمال؛ وهي غطاء الجسد، وقد تكون شاهدة على أعمال اشترك فيها السمع والبصر. وتذكر الموسوعة توجيهًا آخر على القول بأن الجلود كناية عن الفروج، فتخصيصها بالعتاب راجع إلى شدة جناية ما كُنّي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص298–299، تحت عنوان «بلاغة الكناية في جلودهم، وسر تخصيصها بالعتاب»","url":""}]},{"id":"s41-49","number":49,"surah":41,"verses":[21],"references":[{"surah":41,"verses":[21]}],"verseLabel":"فصلت: 21","question":"لماذا لم تجب الجلود عن سؤال ﴿لِمَ شَهِدْتُمْ عَلَيْنَا﴾ بذكر السبب، بل قالت ﴿أَنْطَقَنَا اللَّهُ﴾؟","answer":"لأنهم سألوا عن الدافع إلى الشهادة، فصرفهم الجواب إلى الحقيقة الأهم: الجلود لا تملك الامتناع أصلًا، وإنما نطقت بقدرة الله؛ فصحح جوابها وهمهم قبل أن يجيب توقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص302، تحت عنوان «بلاغة الأسلوب الحكيم في تلقي المخاطب بغير ما يترقبه»","url":""}]},{"id":"s41-131","number":131,"surah":41,"verses":[21],"references":[{"surah":41,"verses":[21]}],"verseLabel":"فصلت: 21","question":"لماذا قالت الجلود ﴿أَنْطَقَنَا اللَّهُ الَّذِي أَنْطَقَ كُلَّ شَيْءٍ﴾ بالاسم الموصول؟","answer":"لتجعل صلته دليل الجواب: الذي تتعلق قدرته بإنطاق كل شيء لا يعجزه إنطاق الجلود، وفي ذلك توبيخ لهم وتعريض بأن إنكارهم شهادة جوارحهم إنكار لسعة قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص303، تحت عنوان «سر وصف الاسم الجليل بالاسم الموصول ﴿الذي﴾»","url":""}]},{"id":"s41-50","number":50,"surah":41,"verses":[21],"references":[{"surah":41,"verses":[21]}],"verseLabel":"فصلت: 21","question":"ما صلة التذكير بخلقهم ﴿أَوَّلَ مَرَّةٍ﴾ بإنطاق جلودهم وشهادتها؟","answer":"ينقلهم من دهشة نطق الجلود إلى أصل أجسادهم: فالذي أنشأها أول مرة قادر على إعادتها وعلى أن يجعلها تتكلم، فتجتمع في العبارة حجة البعث وحجة إمكان شهادة الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص306، تحت عنوان «سر التقييد بالظرف ﴿أول مرة﴾، وسر التعبير به مضافًا»","url":""}]},{"id":"s41-51","number":51,"surah":41,"verses":[22],"references":[{"surah":41,"verses":[22]}],"verseLabel":"فصلت: 22","question":"لماذا أعيد ذكر السمع والأبصار والجلود بعد أن شهدت عليهم؟","answer":"لتجديد استحضار الجوارح التي توهموا أنها تستر أعمالهم، وتأكيد أن الشهادة أحاطت بأدوات الإدراك والفعل التي باشرت المعصية؛ فتتكرر الصدمة بتسمية الشهود مرة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص314، تحت عنوان «فائدة الإطناب بإعادة ذكر السمع والأبصار والجلود»","url":""}]},{"id":"s41-52","number":52,"surah":41,"verses":[22],"references":[{"surah":41,"verses":[22]}],"verseLabel":"فصلت: 22","question":"ما سر التعبير بـ﴿وَمَا كُنْتُمْ تَسْتَتِرُونَ﴾ عن ظنهم أن جوارحهم لا تشهد؟","answer":"الاستتار طلب الستر، ويبين النفي أنهم لم يتحفظوا من أعمالهم مخافة شهادة الجوارح؛ إذ لم يحسبوا لهذه الشهادة حسابًا. ويحتمل التركيب أنهم كانوا يستترون من الناس، لكن ذلك لا يسترهم عن سمعهم وأبصارهم وجلودهم التي تشهد عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص312، تحت عنوان «دلالة التعبير بـ﴿تستترون﴾، وسر صوغه مضارعًا»","url":""}]},{"id":"s41-53","number":53,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"لماذا أُشير إلى ظنهم الباطل بقول الله ﴿وَذَلِكُمْ ظَنُّكُمُ﴾؟","answer":"جيء باسم الإشارة للبعيد لتهويل ذلك الظن وإبعاده عن الحق، وجُمِع خطابهم لأن هذا الوهم كان جماعيًا؛ فالإشارة تستحضر أمامهم السبب الذي أوقعهم في الهلاك وتوبخهم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص322، تحت عنوان «الغرض من التعبير باسم الإشارة للبعيد، وضمير الجمع»","url":""}]},{"id":"s41-132","number":132,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"لماذا وُصف ظنهم بقوله ﴿الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ﴾ بعد ذكره؟","answer":"ليعيّن الظن المذموم الذي صار سبب هلاكهم، ويعيد نسبته إليهم توبيخًا؛ فلم يكن خاطرًا عابرًا، بل اعتقادًا سيئًا بالله بنوا عليه أمنهم من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص323، تحت عنوان «سر التقييد بالصفة ﴿الذي ظننتم﴾ اسمًا موصولًا»","url":""}]},{"id":"s41-54","number":54,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"كيف صوّر قوله ﴿أَرْدَاكُمْ﴾ أثر سوء الظن بالله؟","answer":"صوّر الظن كأنه قوة ألقت أصحابه في الهلاك، فنُسب الإرداء إليه لأنه السبب الذي جرأهم على المعاصي وأمّنهم من العقاب حتى أوقعهم في الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص324، تحت عنوان «الاستعارة والمجاز في قوله ﴿أرداكم﴾»","url":""}]},{"id":"s41-133","number":133,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"ماذا يفيد قوله ﴿فَأَصْبَحْتُمْ مِنَ الْخَاسِرِينَ﴾ بعد ﴿أَرْدَاكُمْ﴾؟","answer":"تفيد الفاء أن الخسران نتيجة مباشرة لذلك الظن، ويصوّر فعل ﴿أصبحتم﴾ انتقالهم إلى حال انكشف فيها الهلاك وصار وصفًا ثابتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص324، تحت عنوان «دلالة التعبير بالفعل ﴿فأصبحتم﴾»","url":""}]},{"id":"s41-55","number":55,"surah":41,"verses":[24],"references":[{"surah":41,"verses":[24]}],"verseLabel":"فصلت: 24","question":"لماذا كان جواب ﴿فَإِنْ يَصْبِرُوا﴾ هو ﴿فَالنَّارُ مَثْوًى لَهُمْ﴾؟","answer":"لأن صبرهم في الآخرة لا يغيّر مصيرهم ولا يخفف العقوبة؛ فالجملة الاسمية تثبت أن النار مقرهم في كل حال، صبروا على ألمها أو جزعوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص331، تحت عنوان «مناسبة جواب الشرط لفعل الشرط، ودلالة التعبير به اسمية»","url":""}]},{"id":"s41-134","number":134,"surah":41,"verses":[24],"references":[{"surah":41,"verses":[24]}],"verseLabel":"فصلت: 24","question":"لماذا قيل في طلبهم العتبى ﴿فَمَا هُمْ مِنَ الْمُعْتَبِينَ﴾؟","answer":"لنفي قبول معذرتهم نفيًا ثابتًا قاطعًا؛ فطلب الرضا بعد فوات زمن التوبة لا يخرجهم من النار، ولا يجعلهم ممن تُزال عنهم المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص334، تحت عنوان «سر التعبير بالجملة الشرطية المنفية جملة اسمية ﴿فما هم من المعتبين﴾»","url":""}]},{"id":"s41-56","number":56,"surah":41,"verses":[25],"references":[{"surah":41,"verses":[25]}],"verseLabel":"فصلت: 25","question":"لماذا أُسند تقييض قرناء السوء إلى ضمير العظمة في ﴿وَقَيَّضْنَا لَهُمْ﴾؟","answer":"لتهويل ما ينشأ عن هذا الجزاء من إحاطة الشر بهم، وتصوير الفعل الإلهي في مقام الجلال والهيبة؛ فيحذر السامع من الإعراض الذي يستجلب تسليط القرناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص341، تحت عنوان «سر الإسناد إلى الضمير الدال على التعظيم»","url":""}]},{"id":"s41-57","number":57,"surah":41,"verses":[25],"references":[{"surah":41,"verses":[25]}],"verseLabel":"فصلت: 25","question":"ما الغرض البلاغي من الإطناب بذكر ﴿أيديهم﴾، ﴿خلفهم﴾؟","answer":"يصور ذكر ما بين الأيدي وما خلف شمول التزيين وإحاطته بهم؛ فهم يصرفونهم إلى الشهوات ويزينون الباطل من جهات متعددة. ومن بيان ذلك أنهم هونوا شأن الآخرة مع تزيين الدنيا، فاجتمعت غواية العمل وفساد الاعتقاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص344، تحت عنوان «الغرض من الإطناب بذكر ﴿أيديهم﴾، ﴿خلفهم﴾»","url":""}]},{"id":"s41-58","number":58,"surah":41,"verses":[25],"references":[{"surah":41,"verses":[25]}],"verseLabel":"فصلت: 25","question":"ما سر تقديم الجن على الإنس في الأمم التي حقت عليها كلمة العذاب؟","answer":"قدّم الجن لأنهم أعرق في الإغواء على التوجيه المذكور، ولأن تقديمهم أبلغ في بيان أن قدرتهم الخفية لا تعصمهم من الحكم الإلهي. وفي ذلك أيضًا إبطال لتعظيم المشركين شأن الجن والاستعاذة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص348، تحت عنوان «نكتة تقديم ﴿الجن﴾ على (الإنس)»","url":""}]},{"id":"s41-59","number":59,"surah":41,"verses":[26],"references":[{"surah":41,"verses":[26]}],"verseLabel":"فصلت: 26","question":"ماذا يكشف نهي الكافرين ﴿لَا تَسْمَعُوا لِهَذَا الْقُرْآنِ﴾؟","answer":"يكشف خوفهم من أثر القرآن وعجزهم عن مقارعته بالحجة؛ فانتقلوا من الإعراض الشخصي إلى صد الناس عن الاستماع كيلا يصل البيان إلى قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص354، تحت عنوان «الغرض من التعبير بالنهي في مقول القول ﴿لا تسمعوا﴾»","url":""}]},{"id":"s41-135","number":135,"surah":41,"verses":[26],"references":[{"surah":41,"verses":[26]}],"verseLabel":"فصلت: 26","question":"لماذا لم يكتفوا بقولهم ﴿لَا تَسْمَعُوا﴾ بل أضافوا ﴿وَالْغَوْا فِيهِ﴾؟","answer":"لأن غرضهم لم يكن ترك السماع وحده، بل التشويش وقت التلاوة حتى يمنعوا غيرهم أيضًا من الفهم؛ فعطفوا إحداث الضجيج على الإعراض ليجمعوا بين صد أنفسهم وصد الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص356، تحت عنوان «دلالة العطف في ﴿والغوا فيه﴾»","url":""}]},{"id":"s41-60","number":60,"surah":41,"verses":[26],"references":[{"surah":41,"verses":[26]}],"verseLabel":"فصلت: 26","question":"ماذا تكشف كلمة ﴿لَعَلَّكُمْ﴾ في قولهم ﴿لَعَلَّكُمْ تَغْلِبُونَ﴾؟","answer":"تكشف أنهم لم يكونوا واثقين بالغلبة، وإنما يرجون أن يحقق لهم التشويش ما عجزت عنه الحجة؛ فتفضح الكلمة ضعف موقفهم وخوفهم من نفاذ القرآن إلى السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص358، تحت عنوان «الغرض من التعبير بـ(لعل)»","url":""}]},{"id":"s41-61","number":61,"surah":41,"verses":[27],"references":[{"surah":41,"verses":[27]}],"verseLabel":"فصلت: 27","question":"ما النكتة البلاغية في التعبير باسم التفضيل ﴿أسوأ﴾، ودلالة إضافته؟","answer":"في ﴿أسوأ﴾ تغليظ وتقبيح لأعمالهم؛ وقد يراد بها أعمالهم السيئة من غير مفاضلة، أو أسوأ أعمالهم الذي استوجب الوعيد، فيتأكد أن الجزاء مطابق لجنايتهم لا ظلم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص365–366، تحت عنوان «نكتة التعبير باسم التفضيل ﴿أسوأ﴾، ودلالة إضافته»","url":""}]},{"id":"s41-62","number":62,"surah":41,"verses":[28],"references":[{"surah":41,"verses":[28]}],"verseLabel":"فصلت: 28","question":"ما فائدة تفسير الجزاء بقوله ﴿النَّارُ لَهُمْ﴾ بعد قوله ﴿ذَلِكَ جَزَاءُ أَعْدَاءِ اللَّهِ﴾؟","answer":"يبدأ السياق بالإشارة إلى الجزاء لتهويله، ثم يعيّنه بقوله ﴿النار لهم﴾ حتى ينكشف بعد الإبهام؛ فتجتمع رهبة الانتظار مع التصريح بالمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص368، تحت عنوان «فصل قوله ﴿النار لهم﴾ عما قبلها»","url":""}]},{"id":"s41-63","number":63,"surah":41,"verses":[28],"references":[{"surah":41,"verses":[28]}],"verseLabel":"فصلت: 28","question":"لماذا قيل ﴿لَهُمْ فِيهَا دَارُ الْخُلْدِ﴾ بدل التصريح بأنهم خالدون؟","answer":"صُوّر الخلود كأن له دارًا مستقلة داخل النار، وهو تجريد يبالغ في ثبات الإقامة؛ فليست النار ممرًا عابرًا، بل مقر دائم لا انفصال لهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص369، تحت عنوان «الغرض من التعبير بأسلوب التجريد في ﴿لهم فيها دار الخلد﴾»","url":""}]},{"id":"s41-64","number":64,"surah":41,"verses":[29],"references":[{"surah":41,"verses":[29]}],"verseLabel":"فصلت: 29","question":"لماذا يقول أهل النار ﴿أَرِنَا الَّذَيْنِ أَضَلَّانَا﴾؟","answer":"لأنهم يريدون تعيين المضلين وتمكينهم منهم ليفرغوا فيهم غضبهم؛ فالطلب ليس معرفة مجردة، بل طلب إحضار ومواجهة بعد أن انقلب الاتباع عداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص378، تحت عنوان «الغرض من الزيادة في ﴿أرنا﴾»","url":""}]},{"id":"s41-136","number":136,"surah":41,"verses":[29],"references":[{"surah":41,"verses":[29]}],"verseLabel":"فصلت: 29","question":"ما الذي يصوره قولهم عن المضلين ﴿نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا﴾؟","answer":"هو كناية عن غاية الإذلال والقهر؛ فالذين كانوا أتباعًا يريدون وضع قادتهم في أسفل منزلة، والانتقام ممن يرون أنهم جرّوهم إلى العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص381، تحت عنوان «الغرض من التعبير بالكناية في ﴿نجعلهما تحت أقدامنا﴾»","url":""}]},{"id":"s41-65","number":65,"surah":41,"verses":[29],"references":[{"surah":41,"verses":[29]}],"verseLabel":"فصلت: 29","question":"ما سر تقديم الجن على الإنس عند تحديد المضلين؟","answer":"يراعي التقديم سبق الجن في الإضلال على هذا التوجيه، ويبين شمول القدرة الإلهية لهم مع خفائهم. ويرد كذلك على عادة الكافرين في تعظيم الجن والاستعاذة بهم، إذ لا يمنعهم ذلك من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص380، تحت عنوان «الغرض من البدء بالجن»","url":""}]},{"id":"s41-66","number":66,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"لماذا جمع قول المؤمنين ﴿رَبُّنَا اللَّهُ﴾ بين اسمي الربوبية والألوهية؟","answer":"لأن وصف الرب يذكّر بالتربية والرعاية والإحسان، واسم الله يقرر استحقاق العبادة وحده؛ فجمع الإقرار بين معرفة المنعم وإخلاص العبودية له.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص389، تحت عنوان «دلالة التعبير باسمي الربوبية والألوهية»","url":""}]},{"id":"s41-67","number":67,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"ماذا تضيف صيغة ﴿تَتَنَزَّلُ﴾ في تنزل الملائكة على المستقيمين؟","answer":"تصور تنزلًا متكررًا متدرجًا بحسب المواطن والحاجات؛ فالملائكة تتعاهد المؤمنين بالبشرى والتثبيت ولا يكون نزولها حادثة منقطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص394، تحت عنوان «بدعة التعبير بالفعل في قوله ﴿تتنزل﴾ دون (تنزل)»","url":""}]},{"id":"s41-68","number":68,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"ما سر تقديم نفي الخوف على نفي الحزن في بشارة الملائكة؟","answer":"يتعلق الخوف بما يستقبلونه من أهوال، ويتعلق الحزن بما خلفوه وما مضى. فبدأت البشارة بتأمينهم مما يواجههم، ثم أتبعت ذلك بتسكين حزنهم على ما تركوه، وجمعت لهم الطمأنينة من الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص397، تحت عنوان «سر الترتيب بالنهي بين الخوف والحزن في قوله ﴿ألا تخافوا ولا تحزنوا﴾»","url":""}]},{"id":"s41-69","number":69,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"ما دلالة الجمع بين نفي الخوف والحزن والبشارة بالجنة؟","answer":"نفي الخوف والحزن يرفع أسباب الضرر والغم، ثم تأتي البشارة بالجنة لتثبت الخير والنعيم. وهذا الترتيب يقدم إزالة ما يكدر النفس، حتى تتلقى البشارة وقد اطمأنت، فيكتمل لها الأمن والفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص398–399، تحت عنوان «دلالة ذكر البشارة بعد النهي عن الخوف والحزن»","url":""}]},{"id":"s41-70","number":70,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"ماذا تعني بشارة الملائكة للمؤمنين ﴿نَحْنُ أَوْلِيَاؤُكُمْ﴾؟","answer":"تعني القرب والنصرة والرعاية؛ فهم يتولون المؤمنين بما يأذن الله به من التثبيت والبشرى والمعونة، فتبدد الكلمة وحشة الانتقال إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص403، تحت عنوان «دلالة التعبير بالأولياء»","url":""}]},{"id":"s41-137","number":137,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"لماذا قالت الملائكة ﴿فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾؟","answer":"لتأكيد أن ولايتهم للمؤمنين ممتدة لا تنقطع بالموت؛ تبدأ بما يكون في الدنيا من التثبيت والحفظ، وتستمر في الآخرة بالبشرى والأمن، فأعيد حرف الجر لتستقل كل مرحلة بعنايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص407، تحت عنوان «دلالة الواو في قوله ﴿وفي الآخرة﴾»","url":""}]},{"id":"s41-71","number":71,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"ماذا توحي صيغة ﴿مَا تَشْتَهِي أَنْفُسُكُمْ﴾ في نعيم الجنة؟","answer":"تجعل الشهوة جامعة لكل ما تميل إليه النفوس من اللذات المتنوعة، وتصور الرغبات متجددة لا يحدها نوع ولا تنغصها حسرة أو حرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص410، تحت عنوان «دلالة التعبير بـ﴿تشتهي﴾»","url":""}]},{"id":"s41-138","number":138,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"لماذا قُدّم ﴿مَا تَشْتَهِي أَنْفُسُكُمْ﴾ على ﴿مَا تَدَّعُونَ﴾؟","answer":"لأن الاشتهاء أعم: يشمل ما يخطر بالقلب قبل أن يطلبه صاحبه، ثم يجيء الادعاء ليضمن ما يطلبونه صراحة؛ فانتقل التعبير من الرغبة الباطنة إلى السؤال الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص413، تحت عنوان «دلالة الترتيب بين ما يشتهون ويدعون»","url":""}]},{"id":"s41-72","number":72,"surah":41,"verses":[32],"references":[{"surah":41,"verses":[32]}],"verseLabel":"فصلت: 32","question":"لماذا نُسب هذا النزل إلى ﴿غَفُورٍ رَحِيمٍ﴾؟","answer":"لأن بلوغ الجنة يبدأ بمغفرة التقصير ويكتمل بالرحمة التي تمنح الفضل والنعيم؛ فاجتماع الوصفين يطمئن المؤمن إلى ستر الذنب ثم دوام الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص418–419، تحت عنوان «سر إيثار وصفي ﴿غفور رحيم﴾ دون غيرهما من الصفات»","url":""}]},{"id":"s41-73","number":73,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"ما دلالة الاستفهام في ﴿وَمَنْ أَحْسَنُ قَوْلًا﴾؟","answer":"هو استفهام يراد به النفي؛ فلا أحد أحسن قولًا ممن دعا إلى الله، وفي صيغة السؤال إشراك للسامع في الإقرار بهذه المنزلة وإثارة للتطلع إلى صفات صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص423، تحت عنوان «دلالة التعبير بالاستفهام في قوله ﴿ومن﴾»","url":""}]},{"id":"s41-139","number":139,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"لماذا جمع صاحب أحسن القول بين الدعوة إلى الله والعمل الصالح؟","answer":"لأن صدق الدعوة يظهر في موافقة العمل للقول؛ فالداعي يهدي غيره بكلامه ويزكي نفسه بفعله، وبهذا تجتمع قدوة البيان وقدوة السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص429–430، تحت عنوان «دلالة الواو في قوله ﴿وعمل﴾»","url":""}]},{"id":"s41-74","number":74,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"لماذا أكّد الداعي قوله ﴿إِنَّنِي مِنَ الْمُسْلِمِينَ﴾؟","answer":"ليعلن انتماءه إلى الإسلام اعتزازًا وثباتًا، ويرد على من قد يشكك في صدقه؛ فالدعوة والعمل الصالح صادران عن هوية إيمانية يصرح بها ولا يخفيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص433، تحت عنوان «دلالة التأكيد بـ(إن) في قوله ﴿إنني﴾»","url":""}]},{"id":"s41-140","number":140,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"لماذا قال ﴿مِنَ الْمُسْلِمِينَ﴾ بدل أن يقول: مسلم؟","answer":"ليجعل نفسه فردًا من جماعة المسلمين لا طالب تميز شخصي، وفيه تواضع وانتساب إلى الطريق الجامع الذي سلكه الأنبياء والمؤمنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص433، تحت عنوان «دلالة التعبير بقوله ﴿من المسلمين﴾»","url":""}]},{"id":"s41-75","number":75,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"ما دلالة نفي استواء الحسنة والسيئة مع وضوح تفاوتهما؟","answer":"نفي الاستواء يراد به تقرير تفضيل الحسنة على السيئة، ثم توجيه المخاطب إلى ما يقتضيه ذلك في المعاملة. فهو يثبت ميزان التفاضل الذي يبنى عليه الأمر بالدفع بالأحسن، ويؤكد أن العملين لا يستويان في القدر والأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص440، تحت عنوان «دلالة التعبير بنفي الاستواء في قوله ﴿ولا تستوي﴾»","url":""}]},{"id":"s41-76","number":76,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"ما سر التعبير بـ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ﴾ بدل «ادفع بالحسنة»؟","answer":"صيغة التفضيل تدعو إلى اختيار أعلى مراتب الإحسان عند مقابلة الإساءة، فلا يكتفى بأدنى حسنة ممكنة. وتبرز الموسوعة من ذلك مقابلة الجهل بالحلم والأذى بالعفو، لما لهذا الفضل الزائد من أثر في تهدئة العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص447، تحت عنوان «دلالة التعبير بصيغة التفضيل ﴿أحسن﴾»","url":""}]},{"id":"s41-77","number":77,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"كيف يصور قوله ﴿كَأَنَّهُ وَلِيٌّ حَمِيمٌ﴾ أثر دفع السيئة بالحسنة؟","answer":"يشبه التحول المتوقع من العداوة إلى المودة بحال عدو صار صديقًا شديد القرب؛ فتجعل ﴿كأن﴾ النتيجة الحاصلة في قوة المشهد المشاهد، من غير أن تزعم زوال العداوة فورًا في كل حالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص452، تحت عنوان «بلاغة التشبيه في قوله ﴿كأنه ولي حميم﴾»","url":""}]},{"id":"s41-141","number":141,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"لماذا جُمع في الصديق المتحوّل بين ﴿وَلِيٌّ﴾ و﴿حَمِيمٌ﴾؟","answer":"لأن الولي يفيد النصرة والقرب، والحميم يفيد صفاء المودة وشدتها؛ فالجمع يصور انقلاب العداوة إلى صداقة كاملة في الموقف والشعور.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص453، تحت عنوان «دلالة الجمع بين ﴿ولي﴾ و﴿حميم﴾»","url":""}]},{"id":"s41-78","number":78,"surah":41,"verses":[35],"references":[{"surah":41,"verses":[35]}],"verseLabel":"فصلت: 35","question":"لماذا قُصر نيل خصلة دفع السيئة بالحسنة على الصابرين؟","answer":"لأن مقابلة الإساءة بالإحسان تحتاج إلى كبح الغضب واحتمال الأذى ومجاهدة النفس؛ فجاء القصر ليبين أن هذه المرتبة لا تُنال بالتمني، بل بصبر متين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص459، تحت عنوان «براعة أسلوب القصر في الموضعين في الآية»","url":""}]},{"id":"s41-142","number":142,"surah":41,"verses":[35],"references":[{"surah":41,"verses":[35]}],"verseLabel":"فصلت: 35","question":"لماذا أضيف بعد الصابرين قوله ﴿وَمَا يُلَقَّاهَا إِلَّا ذُو حَظٍّ عَظِيمٍ﴾؟","answer":"ليبين أن الصبر المؤهل لهذه الخصلة توفيق ونصيب عظيم من الخير؛ فمن قدر على تحويل الإساءة إلى إحسان فقد جمع قوة النفس وحسن العاقبة، وهي منزلة نادرة رفيعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص464، تحت عنوان «دلالة ذكر ﴿ذو حظ عظيم﴾ بعد الصبر في قوله ﴿إلا الذين صبروا﴾»","url":""}]},{"id":"s41-79","number":79,"surah":41,"verses":[35],"references":[{"surah":41,"verses":[35]}],"verseLabel":"فصلت: 35","question":"ما سر الانتقال من جمع الصابرين إلى إفراد ﴿ذُو حَظٍّ عَظِيمٍ﴾؟","answer":"يفيد الانتقال من الجمع إلى الإفراد ندرة من يستوفي هذه المرتبة العالية؛ فالصابرون جماعة، أما من بلغ حظه العظيم من هذه الفضيلة فمتميز بينهم. وفي ذلك تنويه بكمال مرتبته في التوفيق والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص463، تحت عنوان «سر اختلاف التعبير في قوله ﴿إلا ذو﴾ عن سابقتها ﴿إلا الذين﴾»","url":""}]},{"id":"s41-80","number":80,"surah":41,"verses":[36],"references":[{"surah":41,"verses":[36]}],"verseLabel":"فصلت: 36","question":"ما مناسبة الأمر بالاستعاذة بالله بعد الأمر بدفع السيئة بالتي هي أحسن؟","answer":"بعد الأمر بكبح الغضب ومقابلة الإساءة بالإحسان، يوجه إلى الاستعاذة مما يثيره الشيطان من نزغ يصد عن هذا الخلق. فالصبر على أذى البشر والدفع بالأحسن يقترنان بالاعتصام بالله من وسوسة الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص468، تحت عنوان «دلالة التعبير بالواو في قوله ﴿وإما ينزغنك﴾»","url":""}]},{"id":"s41-81","number":81,"surah":41,"verses":[36],"references":[{"surah":7,"verses":[200]},{"surah":41,"verses":[36]}],"verseLabel":"فصلت: 36؛ الأعراف: 200","question":"ما سر التعبير هنا بـ﴿إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ﴾، وفي الأعراف ﴿إِنَّهُ سَمِيعٌ عَلِيمٌ﴾؟","answer":"زاد موضع فصلت ضمير الفصل وتعريف الصفتين لتقوية التوكيد والاختصاص، ومقامه تكليف بدفع السيئة بالتي هي أحسن وما يحتاج إليه من مقاومة دواعي الغضب. أما الأعراف فجاءت فيه الصفتان منكرتين دون ضمير الفصل في سياق الأمر بالعفو والإعراض عن الجاهلين؛ فالاختلاف يراعي مقدار التوكيد الذي يقتضيه كل مقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص480–481، تحت عنوان «دلالة الاتفاق والاختلاف مع الآية 200 من سورة الأعراف»","url":""}]},{"id":"s41-82","number":82,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"لماذا قُدّم الليل والنهار على الشمس والقمر في عداد آيات الله؟","answer":"لأن الليل والنهار آيتان لا يتجه إليهما وهم العبادة، فبدأ بهما لتقرير معنى الآية المخلوقة، ثم ألحق الشمس والقمر بهما لينزع عنهما ما توهمه المشركون من استحقاق السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص487، تحت عنوان «سر تقديم ﴿الليل والنهار﴾ على (الشمس والقمر)»","url":""}]},{"id":"s41-83","number":83,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"لماذا أُعيد النفي في ﴿وَلَا لِلْقَمَرِ﴾ بعد النهي عن السجود للشمس؟","answer":"لتأكيد منع السجود لكل واحد منهما استقلالًا، فلا يتوهم أن المنع مقصور على الجمع بينهما أو على الشمس وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص490، تحت عنوان «سر إعادة حرف النفي في قوله ﴿ولا للقمر﴾»","url":""}]},{"id":"s41-149","number":149,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"ماذا يحقق الأمر ﴿وَاسْجُدُوا لِلَّهِ الَّذِي خَلَقَهُنَّ﴾ بعد النهي؟","answer":"ينقل النظر من الآيات المخلوقة إلى خالقها، ويقرر أن التعظيم الحق لا يقف عند الشمس والقمر بل يتجه إلى من أوجدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص491، تحت عنوان «دلالة الأمر في قوله ﴿واسجدوا﴾»","url":""}]},{"id":"s41-84","number":84,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"لماذا قيل ﴿لِلَّهِ الَّذِي خَلَقَهُنَّ﴾ ولم يقل «للخالق»؟","answer":"لأن الصلة تستحضر فعل الخلق نفسه أمام السامع، فتقيم الحجة مباشرة على استحقاق الله للسجود: من خلق الشمس والقمر وسائر الآيات هو وحده الذي يعبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص494، تحت عنوان «سر التعبير بالصلة والموصول ﴿الذي خلقهن﴾ دون الخالق»","url":""}]},{"id":"s41-85","number":85,"surah":41,"verses":[38],"references":[{"surah":41,"verses":[38]}],"verseLabel":"فصلت: 38","question":"هل يقتصر تسبيح الملائكة على الليل والنهار المذكورين؟","answer":"لا؛ فذكر طرفي الزمن كناية عن استمرارهم في التسبيح دائمًا، لأن عبادتهم لا يحصرها ليل أو نهار، وإنما يراد استغراق الأوقات كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص504، تحت عنوان «بلاغة الكناية في ذكر الليل والنهار»","url":""}]},{"id":"s41-143","number":143,"surah":41,"verses":[38],"references":[{"surah":41,"verses":[38]}],"verseLabel":"فصلت: 38","question":"لماذا نُفيت السآمة عن تسبيح الملائكة في قوله ﴿لَا يَسْأَمُونَ﴾؟","answer":"لبيان أنهم لا يملون العبادة ولا يفترون عنها مهما دامت، بل يؤدونها برضا وإقبال؛ فتظهر عبوديتهم الكاملة ويصغر بجانبها استكبار المعرضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص505، تحت عنوان «سر التعبير بنفي السآمة في قوله ﴿لا يسأمون﴾»","url":""}]},{"id":"s41-86","number":86,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"ما دلالة تصوير الأرض قبل المطر بأنها ﴿خَاشِعَةً﴾؟","answer":"شبهت الأرض اليابسة الساكنة بإنسان خاشع منخفض، فاستعير لها وصف الخشوع لإبراز ذلها وسكونها قبل المطر. ثم يهيئ هذا التصوير لمقابلة حالها بما يظهر فيها من الحركة والنماء بعد نزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص515–516، تحت عنوان «بلاغة الاستعارة في ﴿خاشعة﴾»","url":""}]},{"id":"s41-87","number":87,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"ما الصورة التي يرسمها قوله عن الأرض ﴿اهْتَزَّتْ﴾ بعد نزول الماء؟","answer":"يصورها ككائن حي دبّت فيه الحركة بعد السكون؛ فالماء يوقظ ما خفي فيها من أسباب النبات، ويجعل بدء الحياة مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص516، تحت عنوان «بلاغة الاستعارة في ﴿اهتزت﴾»","url":""}]},{"id":"s41-144","number":144,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"ما الصورة التي يرسمها قوله عن الأرض ﴿وَرَبَتْ﴾؟","answer":"يصورها وهي تنتفخ وتعلو بما تشقه البذور وتنميه من النبات؛ فبعد حركة الحياة يظهر أثرها في الزيادة والارتفاع والنماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص516–517، تحت عنوان «بلاغة الاستعارة في ﴿وربت﴾»","url":""}]},{"id":"s41-88","number":88,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"لماذا خُتم دليل إحياء الأرض بقوله ﴿إِنَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾؟","answer":"ليعمم الحكم بعد المثال، فيقرر أن البعث فرد من قدرة لا يخرج عنها شيء، فلا يبقى مجال لتوهم العجز عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص523، تحت عنوان «موقع جملة ﴿إنه على كل شيء قدير﴾»","url":""}]},{"id":"s41-89","number":89,"surah":41,"verses":[40],"references":[{"surah":41,"verses":[40]}],"verseLabel":"فصلت: 40","question":"ما سر التعبير بالإلحاد في آيات الله، وما الصورة التي يرسمها اللفظ؟","answer":"أصل الإلحاد الميل والانحراف، فاستعير هنا للعدول عن الحق في الآيات بتحريفها وتكذيبها. وبذلك تتحول المخالفة المعنوية إلى صورة محسوسة لمن يميل عن الطريق المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص528–529، تحت عنوان «بلاغة الاستعارة في ﴿يلحدون﴾»","url":""}]},{"id":"s41-90","number":90,"surah":41,"verses":[40],"references":[{"surah":41,"verses":[40]}],"verseLabel":"فصلت: 40","question":"لماذا جُعل ﴿آمِنًا﴾ في مقابل من ﴿يُلْقَى فِي النَّارِ﴾ يوم القيامة؟","answer":"لإظهار التفاوت التام بين المصيرين؛ فالأمن لا يعني مجرد النجاة من النار، بل يشمل الطمأنينة والتكريم ودخول الجنة، فيقابل خوف الكافر وعذابه بحال المؤمن الآمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص538، تحت عنوان «نكتة جعل الأمن في مقابل الإلقاء في النار»","url":""}]},{"id":"s41-91","number":91,"surah":41,"verses":[40],"references":[{"surah":41,"verses":[40]}],"verseLabel":"فصلت: 40","question":"لماذا قيل للمعاندين ﴿اعملوا ما شئتم﴾؟","answer":"ليس الأمر إذنًا بالمعصية، بل تهديد بعد قيام الحجة ووضوح المصير؛ فقد تُرك لهم ظاهر الاختيار ليعلموا أنهم سيتحملون عاقبة ما اختاروه، فاشتد الوعيد بدل أن يكون في الكلام إباحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص541، تحت عنوان «غرض فعل الأمر ﴿اعملوا ما شئتم﴾»","url":""}]},{"id":"s41-92","number":92,"surah":41,"verses":[41],"references":[{"surah":41,"verses":[41]}],"verseLabel":"فصلت: 41","question":"ماذا يكشف وصف القرآن بأنه ﴿كتاب عزيز﴾؟","answer":"يكشف علو شأنه ومناعته المطلقة؛ فهو عزيز في مكانته وبيانه وهدايته وأثره، لا تنقصه معارضة ولا يستطيع أحد الإتيان بمثله. وجاء الوصف منكرًا لتفخيم هذه العزة وفتح النظر في وجوهها الكثيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص549، تحت عنوان «الغرض من تنكير ﴿عزيز﴾»","url":""}]},{"id":"s41-93","number":93,"surah":41,"verses":[42],"references":[{"surah":41,"verses":[42]}],"verseLabel":"فصلت: 42","question":"لماذا عُبّر عن عصمة القرآن بقوله ﴿من بين يديه ولا من خلفه﴾؟","answer":"لأن ذكر الأمام والخلف كناية عن جميع الجهات، فيصور أن الباطل لا يجد إلى القرآن منفذًا من أي ناحية. واختيرت الجهتان الأظهر في حركة الإنسان ونظره لتقوما مقام سائر الجهات في عبارة موجزة قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص555، تحت عنوان «تعليل الكناية في ﴿من بين يديه ولا من خلفه﴾»","url":""}]},{"id":"s41-94","number":94,"surah":41,"verses":[42],"references":[{"surah":41,"verses":[42]}],"verseLabel":"فصلت: 42","question":"ما دلالة وصف منزّل الكتاب بأنه ﴿حكيم حميد﴾؟","answer":"وصف المنزّل بالحكمة يلائم إحكام الكتاب وتنزهه عن الخلل، ووصفه بالحمد يلائم كماله وما في تنزيله من وجوه الخير التي يحمد عليها. فيربط الوصفان صفات القرآن بكمال مصدره، ويؤكدان عزته وتنزهه عن الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص558–559، تحت عنوان «نكتة اصطفاء ﴿حكيم حميد﴾ للفاصلة»","url":""}]},{"id":"s41-95","number":95,"surah":41,"verses":[43],"references":[{"surah":41,"verses":[43]}],"verseLabel":"فصلت: 43","question":"كيف تسلّي الآية الرسول ﷺ بقولها ﴿ما يقال لك إلا ما قد قيل للرسل من قبلك﴾؟","answer":"تحصر ما يواجهه في سنة سبقت مع الرسل: فليس التكذيب والأذى أمرًا جديدًا خاصًا به. وهذا يثبت قلبه ويهوّن عليه قول المعاندين، إذ يسير في طريق إخوانه من الرسل وتتشابه مواقف المكذبين منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص562، تحت عنوان «غرض التعبير بأسلوب القصر في ﴿ما يقال لك﴾»","url":""}]},{"id":"s41-96","number":96,"surah":41,"verses":[43],"references":[{"surah":41,"verses":[43]}],"verseLabel":"فصلت: 43","question":"كيف يرتبط قوله ﴿إن ربك لذو مغفرة وذو عقاب أليم﴾ بتسلية الرسول قبله؟","answer":"جاء تعليلًا لما قبله: فإذا كان الرسول يلقى ما لقيه الرسل فليصبر، لأن ربه يغفر لأوليائه وينصرهم، ويعاقب أعداءه وينتقم منهم. وهكذا يطمئنه الختام إلى أن مصير الفريقين بيد ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص567، تحت عنوان «موقع جملة ﴿إن ربك لذو مغفرة﴾ مما قبلها»","url":""}]},{"id":"s41-145","number":145,"surah":41,"verses":[43],"references":[{"surah":41,"verses":[43]}],"verseLabel":"فصلت: 43","question":"لماذا وُصف العقاب بأنه ﴿أليم﴾ لا شديد؟","answer":"لأن ﴿أليم﴾ تستحضر أثر العقاب في النفس والجسد معًا وعمق ما يحدثه من وجع؛ فهي لا تكتفي بوصف قوته، بل تنقل أثره الحسي والمعنوي في المعاقَب، ويلزم من ذلك شدة العقاب أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص570، تحت عنوان «نكتة اصطفاء ﴿أليم﴾»","url":""}]},{"id":"s41-97","number":97,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"ماذا يكشف افتراض ﴿ولو جعلناه قرآنًا أعجميًا﴾ عن حقيقة اعتراض المكذبين؟","answer":"يكشف أن اعتراضهم قائم على العناد لا على طلب البيان؛ فلو تحقق الفرض المخالف وجاء القرآن أعجميًا لاعترضوا على عدم تفصيله، كما اعترضوا عليه وهو عربي. وبذلك يصور الشرط تناقض حججهم وأنهم سيبحثون عن شبهة أيًّا كانت لغة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص573–574، تحت عنوان «دلالة التعبير بـ(لو) في ﴿ولو جعلناه﴾»","url":""}]},{"id":"s41-98","number":98,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"ما سر جمع القرآن للمؤمنين بين الهدى والشفاء، وتقديم الهدى؟","answer":"الهدى يرشد إلى الحق ويقي من الانحراف، والشفاء يعالج أمراض القلب وما أصابه من الشبه والشهوات. فتقديم الهدى يلائم الدلالة على العلاج قبل الانتفاع به، والجمع بين الوصفين يبين تكامل الإرشاد والإصلاح، دون أن تقتضي الواو وحدها ترتيبًا زمنيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص586–587، تحت عنوان «دلالة العطف في ﴿وشفاء﴾»","url":""}]},{"id":"s41-99","number":99,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"لماذا عُبِّر عن ضلالهم بقوله ﴿وَهُوَ عَلَيْهِمْ عَمًى﴾ بدل «وهو عليهم ضلال»؟","answer":"لأن العمى يحول المعنى المجرد إلى صورة محسوسة؛ فكما يحرم الأعمى رؤية الطريق، حرم هؤلاء أنفسهم إدراك نور القرآن بسبب عنادهم. وفي اللفظ مقابلة ظاهرة مع كونه هدى للمؤمنين، وزيادة في تصوير شدة حرمان الكافرين وتحقير حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص589، تحت عنوان «بلاغة الاستعارة التصريحية في لفظ ﴿عمى﴾»","url":""}]},{"id":"s41-100","number":100,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"ما وجه تمثيل غير المنتفعين بالقرآن بقوم ﴿يُنَادَوْنَ مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"يشبّه حالهم في الإعراض وعدم الفهم بحال من ينادى من مسافة بعيدة فلا يعي الكلام ولا يستجيب له. فالمسافة تمثل الفجوة التي أحدثوها بينهم وبين القرآن، مع أن بيانه حاضر قريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص591–592، تحت عنوان «بلاغة التمثيل في ﴿أولئك ينادون من مكان بعيد﴾»","url":""}]},{"id":"s41-101","number":101,"surah":41,"verses":[45],"references":[{"surah":41,"verses":[45]}],"verseLabel":"فصلت: 45","question":"لماذا وُصفت الكلمة بأنها ﴿سَبَقَتْ مِنْ رَبِّكَ﴾؟","answer":"وصفها بالسبق يبين أنها قضاء ثابت نافذ لا يتخلف ولا يتبدل. ونسبتها إلى الرب تستحضر معاني العناية واللطف؛ فإمهال المختلفين رحمة تفتح لهم زمن التوبة قبل الحساب، مع تعظيم مصدر الكلمة وتأكيد سلطانها على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص599، تحت عنوان «سر وصف ﴿كلمة﴾ بالجملة ﴿سبقت من ربك﴾»","url":""}]},{"id":"s41-102","number":102,"surah":41,"verses":[46],"references":[{"surah":41,"verses":[46]}],"verseLabel":"فصلت: 46","question":"ما دلالة مقابلة اللام في ﴿فَلِنَفْسِهِ﴾ بـ﴿فَعَلَيْهَا﴾ في قاعدة الجزاء؟","answer":"اللام تفيد اختصاص العامل بنفع عمله الصالح واستحقاقه ثوابه، وأما على فتصور تبعة الإساءة محمولة على صاحبها. فاختلاف الحرفين يلائم اختلاف الأثرين: نفع يعود إلى النفس وضرر يثقلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص611، تحت عنوان «بلاغة الطباق مع العدول في النظم»","url":""}]},{"id":"s41-103","number":103,"surah":41,"verses":[46],"references":[{"surah":41,"verses":[46]}],"verseLabel":"فصلت: 46","question":"ما سر التعبير بـ﴿الْعَبِيدِ﴾ في قوله ﴿وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ﴾؟","answer":"وصفهم بالعبيد يبرز ملك الله لهم وافتقارهم إليه، مع غناه عن ظلمهم؛ فهو يدبر شؤونهم ويقوم بمصالحهم. فتجيء إضافة نفي الظلم إليهم تقريرًا لعدله، وتذكيرًا بما تقتضيه عبوديتهم من الاعتراف بفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص615، تحت عنوان «سر التقييد بالجار والمجرور ﴿للعبيد﴾»","url":""}]},{"id":"s41-104","number":104,"surah":41,"verses":[47],"references":[{"surah":41,"verses":[47]}],"verseLabel":"فصلت: 47","question":"لماذا ذُكر خروج الثمرات والحمل والوضع بعد رد علم الساعة إلى الله؟","answer":"لأنها كلها أمور مستقبلية خفية لا يستطيع أحد أن يجزم بتفاصيل وقوعها؛ فكما اختص الله بعلم الساعة، أحاط وحده بموعد خروج كل ثمرة وما تحمل كل أنثى ومتى تضع. وبهذا ينتقل السياق من أعظم الغيب إلى دقائق تتكرر أمام الناس ليقرر شمول العلم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص626، تحت عنوان «وجه العطف بالواو»","url":""}]},{"id":"s41-105","number":105,"surah":41,"verses":[47],"references":[{"surah":41,"verses":[47]}],"verseLabel":"فصلت: 47","question":"لماذا أضيف الشركاء إلى الله في قوله يوم القيامة ﴿أَيْنَ شُرَكَائِي﴾؟","answer":"الإضافة جرت على زعم المشركين، لا على إثبات شريك لله؛ فهي تهكم وتقريع لهم على أن جعلوا من لا يستحق شريكًا لله. والمعنى: أين الذين زعمتم أنهم يشفعون لكم ويحفظونكم من العذاب؟","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص633، تحت عنوان «نكتة الإضافة إلى ياء المتكلم»","url":""}]},{"id":"s41-146","number":146,"surah":41,"verses":[47],"references":[{"surah":41,"verses":[47]}],"verseLabel":"فصلت: 47","question":"ما الذي يتضمنه قول المشركين يوم القيامة ﴿آذَنَّاكَ﴾؟","answer":"يتضمن إعلانهم وإقرارهم الصريح بأن لا أحد منهم يشهد بوجود شريك لله، بعد أن شهدت أحوالهم بعجز معبوداتهم. وجاء الفعل بصيغة الماضي في مقام الإقرار الحاضر ليؤكد تحققه من غير شك، فكان اعترافًا علنيًا ممزوجًا بالحسرة والندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص634، تحت عنوان «نكتة التعبير بقوله ﴿آذناك﴾ مادة وصيغة»","url":""}]},{"id":"s41-106","number":106,"surah":41,"verses":[48],"references":[{"surah":41,"verses":[48]}],"verseLabel":"فصلت: 48","question":"لماذا اختير لفظ ﴿مَحِيصٍ﴾ دون «مفر» أو «مهرب»؟","answer":"المحيص هو المكان الضيق الذي يُلجأ إليه فرارًا ممزوجًا بالخوف والنفور، ولذلك يصور ذعرهم وبحثهم المحموم عن موضع ينجيهم. وهو أنسب من المفر أو المهرب؛ لأنهما لا يستلزمان هذا الذعر دائمًا، ثم جاء اللفظ نكرة في سياق النفي ليعم كل مكان محتمل للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص644، تحت عنوان «دلالة التعبير بلفظ ﴿محيص﴾ مادة وصيغة»","url":""}]},{"id":"s41-107","number":107,"surah":41,"verses":[49],"references":[{"surah":41,"verses":[49]}],"verseLabel":"فصلت: 49","question":"ما دلالة الجمع بين عدم سآمة الإنسان من دعاء الخير وشدة يأسه عند مس الشر؟","answer":"تقابل الآية بين إلحاح الإنسان في طلب الخير وعدم اكتفائه به، وبين سرعة انكساره إذا أصابه الشر. فتفضح ضعف صبره وتعلقه بالعطاء؛ يطول أمله عند النعمة وينقطع رجاؤه عند البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص652، تحت عنوان «بلاغة المقابلة في الآية»","url":""}]},{"id":"s41-108","number":108,"surah":41,"verses":[49],"references":[{"surah":11,"verses":[9]},{"surah":41,"verses":[49]}],"verseLabel":"فصلت: 49؛ هود: 9","question":"لماذا أُتبع وصف الإنسان بأنه ﴿يَئُوسٌ﴾ بقوله ﴿قَنُوطٌ﴾؟","answer":"ليجمع بين انقطاع الرجاء في باطنه وظهور أثره عليه انكسارًا وتضاؤلًا؛ فالقنوط يكمل صورة اليأس ويكشف شدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص653، تحت عنوان «براعة إتباع اليأس بالقنوط»","url":""}]},{"id":"s41-109","number":109,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"ماذا يكشف التعبير بالماضي في ﴿أَذَقْنَاهُ رَحْمَةً﴾ عن اغترار الإنسان بالنعمة؟","answer":"يكشف أن ما ذاقه قد يكون قليل المدة سريع الانصرام، ولا برهان له على بقائه؛ ومع ذلك يسارع إلى الغرور والجحود كأن النعمة دائمة مضمونة، فتفضح الصيغة تناقض ثقته بنفسه مع هشاشة ما بين يديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص660، تحت عنوان «وجه التعبير بفعل الإذاقة ماضيًا»","url":""}]},{"id":"s41-110","number":110,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"ماذا يكشف قوله ﴿وَمَا أَظُنُّ السَّاعَةَ قَائِمَةً﴾ عن أثر النعمة في الإنسان المغرور؟","answer":"يكشف أن كثرة النعم لا تقوده إلى الشكر، بل تجدّد في نفسه وهم نفي البعث وتثبته عليه؛ فلا يستجيب لمن يذكّره بالآخرة، لأنه يقيس المستقبل على رخائه الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص664، تحت عنوان «سر التعبير بفعل الظن مضارعًا»","url":""}]},{"id":"s41-111","number":111,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"لماذا قال المغتر بالنعمة ﴿إِلَى رَبِّي﴾ ثم توقّع لنفسه الحسنى؟","answer":"لأنه فهم إحسان الله إليه في الدنيا على أنه دليل منزلة خاصة له عند ربه، فتوهم أن عنايته الدنيوية تضمن له حالًا أفضل في الآخرة إن وقع البعث؛ وبذلك حوّل النعمة من داعٍ للشكر إلى حجة موهومة على استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص666، تحت عنوان «سر إيثار لفظ الربوبية وإضافته إلى الياء»","url":""}]},{"id":"s41-112","number":112,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"لماذا وُصف العذاب بأنه ﴿غَلِيظٍ﴾؟","answer":"ليصور شدته وثقله وقسوته تصويرًا محسوسًا، فيقابل ما توهمه الكافر من الحسنى والكرامة بعاقبة بالغة الإيلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص672–673، تحت عنوان «نكتة وصف العذاب بالغليظ»","url":""}]},{"id":"s41-113","number":113,"surah":41,"verses":[51],"references":[{"surah":41,"verses":[51]}],"verseLabel":"فصلت: 51","question":"ما الذي تصوّره الكناية في قوله ﴿وَنَأَى بِجَانِبِهِ﴾؟","answer":"تصوّر إنسانًا يعطي النعمة جانبه وينصرف عن شكر المنعم في هيئة متكبر لا يكترث بما أُسدي إليه؛ فالإشاحة بالجانب تجعل الإعراض موقفًا مشاهدًا من الإهمال والغرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص680، تحت عنوان «بلاغة الكناية في ﴿بجانبه﴾»","url":""}]},{"id":"s41-114","number":114,"surah":41,"verses":[51],"references":[{"surah":41,"verses":[51]}],"verseLabel":"فصلت: 51","question":"لماذا وُصف دعاء الإنسان عند الضر بأنه ﴿عَرِيضٍ﴾؟","answer":"ليصوّر كثرة دعائه وتكراره بلا حد؛ فالعرض يستلزم امتدادًا وطولًا، وجاءت صيغة ﴿عريض﴾ مبالغةً تزيد صورة الإلحاح والتضرع عند الشدة وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص683، تحت عنوان «سر الوصف بلفظ ﴿عريض﴾ دلالة وصيغة»","url":""}]},{"id":"s41-115","number":115,"surah":41,"verses":[52],"references":[{"surah":41,"verses":[52]}],"verseLabel":"فصلت: 52","question":"لماذا سيقت الحجة للمكذبين على فرض: ﴿إِنْ كَانَ مِنْ عِنْدِ اللَّهِ ثُمَّ كَفَرْتُمْ بِهِ﴾؟","answer":"لأن الخطاب يجاري إنكارهم مؤقتًا ليستنزلهم إلى النظر في دلائل صدق القرآن؛ فيراجعون موقفهم بدل الإصرار عليه. فالفرض وسيلة لإلزامهم بالتأمل، لا تعبير عن شك في مصدر القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص690، تحت عنوان «وجه التعبير بـ﴿إن﴾ الشرطية»","url":""}]},{"id":"s41-147","number":147,"surah":41,"verses":[52],"references":[{"surah":41,"verses":[52]}],"verseLabel":"فصلت: 52","question":"ماذا يحقق السؤال: ﴿مَنْ أَضَلُّ مِمَّنْ هُوَ فِي شِقَاقٍ بَعِيدٍ﴾؟","answer":"ينفي أن يوجد أحد أشد ضلالًا ممن عادى القرآن بعد قيام دلائله، ويطرح الحكم في صورة سؤال يدعوهم إلى التفكير مع أنفسهم والرجوع عن غيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص692–693، تحت عنوان «بلاغة الاستفهام بـ﴿من﴾»","url":""}]},{"id":"s41-116","number":116,"surah":41,"verses":[52],"references":[{"surah":41,"verses":[52]}],"verseLabel":"فصلت: 52","question":"لماذا وُصفت معاداة الكافرين للقرآن بأنها ﴿شِقَاقٍ﴾؟","answer":"لأن الشقاق يجعل كل طرف في شق مقابل، فيصورهم وقد اختاروا جانب الخصومة والانفصال عن الحق وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص694، تحت عنوان «وجه التعبير بمفردة ﴿شقاق﴾»","url":""}]},{"id":"s41-117","number":117,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"لماذا عُبِّر عن دلائل الكون بلفظ ﴿الْآفَاقِ﴾ جمعًا؟","answer":"ليستوعب نواحي الكون وجهاته كلها وما فيها من آيات، فلا تُحصر الدلائل في مكان واحد أو فيما حول مكة؛ وبذلك يكون ظهورها أعم وأقوى في إقامة البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص700، تحت عنوان «وجه التعبير بلفظ ﴿الآفاق﴾ جمعًا»","url":""}]},{"id":"s41-148","number":148,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"لماذا ذُكرت آيات الآفاق قبل آيات الأنفس؟","answer":"لأن آيات الآفاق تعرض الدليل العام في الكون كله، ثم تُلحق بها الآيات الخاصة القريبة التي يجدها الإنسان في نفسه؛ فينتقل النظر من الشاهد الواسع إلى الشاهد المحسوس الملازم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص700، تحت عنوان «توجيه العطف بالواو»","url":""}]},{"id":"s41-118","number":118,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"إلى أي غاية ستظهر لهم آيات الله في الآفاق والأنفس؟","answer":"ستتتابع الآيات حتى يتضح لهم بلا موضع للشك أن ما جاء به الرسول هو الحق؛ فالمقصود أن تقود كثرة الدلائل ووضوحها إلى زوال الارتياب والتصديق بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص701–702، تحت عنوان «معنى ﴿حتى﴾»","url":""}]},{"id":"s41-119","number":119,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"ماذا يحقق الاستفهام في قوله تعالى: ﴿أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ﴾؟","answer":"يقرر أن شهادة الله كافية في إثبات صدق رسوله، فيثبته على اليقين ولا يترك لتكذيب المشركين وزنًا. ويحمل الاستفهام أيضًا إنكار طلبهم دليلًا بعد شهادة الله المحيطة بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص703، تحت عنوان «بلاغة الاستفهام بالهمزة»","url":""}]},{"id":"s41-120","number":120,"surah":41,"verses":[54],"references":[{"surah":41,"verses":[54]}],"verseLabel":"فصلت: 54","question":"لماذا افتُتحت خاتمة سورة فصلت بقوله ﴿أَلَا﴾؟","answer":"لإيقاظ السامع وجذب انتباهه إلى حقيقتين ختاميتين خطيرتين: شك المكذبين في لقاء ربهم، وإحاطة الله بكل شيء. فليست الآية خبرًا عابرًا، بل تذييل يجمع التحذير والتقرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص709، تحت عنوان «سر التعبير بـ﴿ألا﴾»","url":""}]},{"id":"s41-121","number":121,"surah":41,"verses":[54],"references":[{"surah":41,"verses":[54]}],"verseLabel":"فصلت: 54","question":"ما الصورة التي يرسمها قوله عن المكذبين ﴿فِي مِرْيَةٍ﴾؟","answer":"يصور شكهم وجدالهم كحفرة عميقة ألقوا أنفسهم فيها حتى أحاطت بهم وتعذر عليهم الخروج منها؛ وفي ذلك بيان لتمكن الشك من نفوسهم وبلوغه مبلغًا بعيدًا في إنكار البعث والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص710، تحت عنوان «نوع المجاز وبلاغته في قوله ﴿في مرية﴾»","url":""}]},{"id":"s41-122","number":122,"surah":41,"verses":[54],"references":[{"surah":41,"verses":[54]}],"verseLabel":"فصلت: 54","question":"كيف يرد ﴿أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُحِيطٌ﴾ على شكهم في لقاء ربهم؟","answer":"إذا كان علم الله وقدرته محيطين بكل شيء فلا يخفى عليه مكذب، ولا يعجزه بعث أو جزاء؛ فتسقط شبهة الإفلات من لقائه وحسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص713–714، تحت عنوان «سر التعبير بلفظ ﴿محيط﴾ مادة وصيغة»","url":""}]},{"id":"s42-1","number":1,"surah":42,"verses":[1],"references":[{"surah":42,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الشورى» مع أن لفظ الشورى لم يرد فيها إلا مرة واحدة؟","answer":"لا تتوقف مناسبة الاسم على كثرة تكرار اللفظ؛ فالشورى علامة بارزة على بناء الجماعة المؤمنة واجتماعها على الدين. وتصل الموسوعة الاسم بوحدة الأمة ومرجعيتها في الوحي، وبما تقتضيه الشورى من اجتماع وتوافق يمنع التفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص717–718، تحت عنوان «اسم السورة الكريمة ومناسبة تسميتها»","url":""}]},{"id":"s42-2","number":2,"surah":42,"verses":[1],"references":[{"surah":42,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما دلالة اجتماع الوحي ووحدة الدين والشورى في بناء سورة واحدة؟","answer":"يجمع بناء السورة بين مصدر الهداية وهو الوحي، ومقصدها وهو وحدة الدين، والمنهج العملي لاجتماع المؤمنين وهو الشورى. فالرجوع إلى الوحي يضبط الحكم، والشورى تعين على وحدة الجماعة، ويؤكد البعث مسؤولية الناس عن استجابتهم لهذا المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص718–719، تحت عنوان «المحور العام للسورة»","url":""}]},{"id":"s42-3","number":3,"surah":42,"verses":[1],"references":[{"surah":42,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما سر افتتاح السورة بالوحي وختمها به؟","answer":"يربط الافتتاح والخاتمة السورة بقضية الوحي: تبدأ ببيان أن الله يوحي إلى نبيه كما أوحى إلى السابقين، وتختم ببيان طرائق الوحي وما أوحاه إلى رسوله. فتعود الخاتمة إلى الأصل الذي قامت عليه دعوتها إلى الهداية ووحدة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص722، تحت عنوان «مناسبة مطلع السورة لخواتيمها»","url":""}]},{"id":"s42-4","number":4,"surah":42,"verses":[1,2],"references":[{"surah":42,"verses":[1,2]}],"verseLabel":"الشورى: 1–2","question":"لماذا اختص مطلع سورة الشورى بزيادة ﴿عسق﴾ بعد ﴿حم﴾؟","answer":"شاركت السورة سائر الحواميم في ﴿حم﴾، ثم تميزت عنها بزيادة ﴿عسق﴾؛ وفي زيادة الحروف مزيد تنبيه إلى تحدي العرب بالقرآن المؤلف من الحروف التي ينطقون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص726–727، تحت عنوان «سر اختصاص السورة دون الحواميم بـ﴿عسق﴾»","url":""}]},{"id":"s42-5","number":5,"surah":42,"verses":[1,2,3],"references":[{"surah":42,"verses":[1,2,3]}],"verseLabel":"الشورى: 1–3","question":"لماذا جاء قوله: ﴿كَذَلِكَ يُوحِي إِلَيْكَ﴾ مباشرة بعد ﴿حم عسق﴾؟","answer":"لأن المطلع بالحروف نبه إلى شأن القرآن، ثم استؤنف الكلام ببيان مصدره وغرض السورة: أنه وحي من الله متصل برسالات الأنبياء ودعوتهم إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص729، تحت عنوان «علة فصل قوله ﴿كذلك يوحي﴾ عما قبله»","url":""}]},{"id":"s42-146","number":146,"surah":42,"verses":[1,2,3],"references":[{"surah":42,"verses":[1,2,3]}],"verseLabel":"الشورى: 1–3","question":"ما دلالة التشبيه في قوله: ﴿كَذَلِكَ يُوحِي إِلَيْكَ﴾؟","answer":"يشبه هذا الوحي بما أوحاه الله إلى الأنبياء من قبل في أصل الدعوة إلى توحيده؛ فيقرر وحدة مصدر الرسالات وينوه بعظمة ما يوحى إلى النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص730، تحت عنوان «بيان التشبيه وغرضه في ﴿كذلك يوحي إليك﴾»","url":""}]},{"id":"s42-6","number":6,"surah":42,"verses":[3],"references":[{"surah":42,"verses":[3]}],"verseLabel":"الشورى: 3","question":"لماذا قيل: ﴿يُوحِي إِلَيْكَ﴾ بالمضارع؟","answer":"ليصور الوحي متجددًا مستمرًا، لا واقعة انقضت؛ وفي ذلك تثبيت للرسول ﷺ وتنويه بتتابع ما يوحى إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص731، تحت عنوان «دلالة التعبير بالفعل المضارع في ﴿يوحي﴾»","url":""}]},{"id":"s42-7","number":7,"surah":42,"verses":[3],"references":[{"surah":42,"verses":[3]}],"verseLabel":"الشورى: 3","question":"لماذا خُتم خبر الوحي باسمي الله ﴿الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"لأن العزيز لا يعجزه إنفاذ وحيه، والحكيم يضع الرسالة في موضعها ويشرع ما يصلح عباده؛ فالاسمان يقرران قوة مصدر الوحي وإحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص734، تحت عنوان «سر إيثار الاسمين الكريمين ﴿العزيز الحكيم﴾»","url":""}]},{"id":"s42-8","number":8,"surah":42,"verses":[3,4],"references":[{"surah":42,"verses":[3,4]}],"verseLabel":"الشورى: 3–4","question":"ما دلالة الانتقال من الوحي إلى تقرير ملك الله لما في السماوات والأرض؟","answer":"تقرير ملكه الشامل يثبت ما دل عليه وصفه بالعزيز الحكيم؛ فمن له السماوات والأرض لا تعجزه إرادة ولا يخرج شيء عن سلطانه. فالجملة تعلل كمال قدرته وحكمته، وتقرر أن الوحي صادر عن المالك المتصرف في الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص737، تحت عنوان «موقع جملة ﴿له ما في السماوات وما في الأرض﴾ مما قبلها، ودلالتها»","url":""}]},{"id":"s42-9","number":9,"surah":42,"verses":[4],"references":[{"surah":42,"verses":[4]}],"verseLabel":"الشورى: 4","question":"لماذا وُصف مالك السماوات والأرض بأنه ﴿الْعَلِيُّ الْعَظِيمُ﴾؟","answer":"لأن كمال ملكه يقتضي تنزهه عن أن يشبهه شيء؛ فالعلي منزه عن مماثلة خلقه، والعظيم مستحق لكل إجلال، وفي ذلك تعظيم لمصدر الوحي السابق ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص739، تحت عنوان «سر اصطفاء الاسمين الجليلين واقترانهما»","url":""}]},{"id":"s42-10","number":10,"surah":42,"verses":[4,5],"references":[{"surah":42,"verses":[4,5]}],"verseLabel":"الشورى: 4–5","question":"لماذا انتقل من وصف الله بـ﴿الْعَلِيُّ الْعَظِيمُ﴾ إلى قوله: ﴿تَكَادُ السَّمَاوَاتُ يَتَفَطَّرْنَ﴾؟","answer":"جاء مشهد تفطر السماوات تقريرًا محسوسًا لعظمته؛ فبعد أن ذكر العظمة وصفًا أرى أثرها في أعظم المخلوقات، وهي تكاد تتشقق هيبةً وإجلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص741، تحت عنوان «علة فصل قوله ﴿تكاد السماوات﴾»","url":""}]},{"id":"s42-11","number":11,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"ماذا تضيف كلمة ﴿تَكَادُ﴾ إلى مشهد تفطر السماوات؟","answer":"تقرب التفطر من الوقوع من غير أن تخبر بوقوعه؛ فتجعل السماوات في حال مستمرة من شدة الهيبة أمام عظمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص741–742، تحت عنوان «دلالة التعبير بالفعل ﴿تكاد﴾ مادة وصيغة»","url":""}]},{"id":"s42-12","number":12,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"لماذا جمع الملائكة بين تسبيح الله والاستغفار لمن في الأرض؟","answer":"لأنهم ينزهون الله إجلالًا لعظمته، ثم يستغفرون لعباده لما يرونه من تقصيرهم؛ فيجتمع تعظيم الخالق والشفقة على المخلوق في مشهد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص746، تحت عنوان «دلالة الواو في ﴿ويستغفرون﴾»","url":""}]},{"id":"s42-13","number":13,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"لماذا قيل: ﴿وَيَسْتَغْفِرُونَ لِمَنْ فِي الْأَرْضِ﴾ ولم يقل: للمؤمنين؟","answer":"جيء بالموصول العام ليتسع المعنى: فالاستغفار للمؤمنين، ويشمل العصاة منهم بطلب المغفرة، ويمكن أن يكون لغير المؤمن بطلب ما يوصله إلى أسباب المغفرة من الإيمان والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص747، تحت عنوان «الغرض من التعبير بالاسم الموصول (من)»","url":""}]},{"id":"s42-14","number":14,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"ماذا يضيف قوله: ﴿أَلَا إِنَّ اللَّهَ هُوَ الْغَفُورُ الرَّحِيمُ﴾ بعد استغفار الملائكة؟","answer":"يقرر أن قبول الاستغفار والمغفرة والرحمة كلها بيد الله، ويبشر بأن رحمته تزيد عباده فوق ما طلبته الملائكة لهم؛ فجاء التذييل تثبيتًا للرجاء بعد مشهد الهيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص747–748، تحت عنوان «موقع جملة ﴿ألا إن الله﴾ مما قبلها، ودلالتها»","url":""}]},{"id":"s42-15","number":15,"surah":42,"verses":[6],"references":[{"surah":42,"verses":[6]}],"verseLabel":"الشورى: 6","question":"لماذا وُصف الله بأنه ﴿حَفِيظٌ عَلَيْهِمْ﴾؟","answer":"لأن ﴿حفيظ﴾ صيغة مبالغة تصور إحاطته بكثرة المعبودين والعابدين وأعمالهم جميعًا؛ فلا يفوته شيء منها وسيجازي كلًا بما عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص755، تحت عنوان «دلالة التعبير بلفظ ﴿حفيظ﴾»","url":""}]},{"id":"s42-147","number":147,"surah":42,"verses":[6],"references":[{"surah":42,"verses":[6]}],"verseLabel":"الشورى: 6","question":"لماذا قوبل ﴿اللَّهُ حَفِيظٌ عَلَيْهِمْ﴾ بقوله للنبي ﷺ: ﴿وَمَا أَنْتَ عَلَيْهِمْ بِوَكِيلٍ﴾؟","answer":"ليثبت أن حسابهم وحفظ أعمالهم لله وحده، ويُسلي الرسول ﷺ بأن وظيفته البلاغ لا إجبارهم على الإيمان ولا تحمل تبعة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص755–756، تحت عنوان «معنى الواو ودلالتها في ﴿وما أنت عليهم﴾»","url":""}]},{"id":"s42-16","number":16,"surah":42,"verses":[3,7],"references":[{"surah":42,"verses":[3,7]}],"verseLabel":"الشورى: 3، 7","question":"لماذا قيل هنا: ﴿أَوْحَيْنَا إِلَيْكَ﴾ بالماضي بعد قوله أول السورة: ﴿يُوحِي إِلَيْكَ﴾؟","answer":"المضارع في المطلع يصور تجدد الوحي، أما الماضي هنا فيقرر تحقق إنزال هذا القرآن وثبوته، وإسناده إلى ضمير العظمة يعظم الوحي والموحي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص761، تحت عنوان «دلالة التعبير بالماضي ﴿أوحينا﴾، وإسناده إلى ضمير العظمة»","url":""}]},{"id":"s42-17","number":17,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا قُيّد القرآن بوصف ﴿عَرَبِيًّا﴾ في خطاب النبي ﷺ؟","answer":"لتعظيم شأن القرآن وبيان وضوحه وفصاحته للمخاطبين الأولين، وليكون أنسب بحال المنذَرين الذين يتلقونه بلغتهم ثم يبلغونه سائر الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص762، تحت عنوان «الغرض من تنكير المفعول به، وسر تقييده بالوصف ﴿عربيًا﴾»","url":""}]},{"id":"s42-18","number":18,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا تكرر فعل الإنذار في قوله: ﴿وَتُنْذِرَ يَوْمَ الْجَمْعِ﴾؟","answer":"لإفراد يوم القيامة بعناية وتهويل بعد الإنذار العام لأهل مكة ومن حولها؛ فإعادة الفعل تجعل ذلك اليوم مقصدًا مستقلًا للإنذار وتلفت إلى عظم أهواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص765–766، تحت عنوان «دلالة تكرار فعل الإنذار»","url":""}]},{"id":"s42-19","number":19,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا سميت القيامة ﴿يَوْمَ الْجَمْعِ﴾؟","answer":"لأنها تجمع الخلائق كلهم للحساب، وتجتمع فيها الأرواح بالأجساد وأهل الأرض بأهل السماء؛ فالإضافة تهول اليوم بما يحشده من الخلق والمصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص766–767، تحت عنوان «الغرض من الإضافة في ﴿يوم الجمع﴾»","url":""}]},{"id":"s42-148","number":148,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا أعقب ﴿يَوْمَ الْجَمْعِ﴾ بقوله: ﴿فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ﴾؟","answer":"لبيان نتيجة ذلك الجمع: يجتمع الناس في الموقف ثم لا تتساوى مصائرهم، بل ينقسمون فريقين بحسب الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص768، تحت عنوان «موقع جملة ﴿فريق في الجنة﴾ مما قبلها، ودلالته»","url":""}]},{"id":"s42-20","number":20,"surah":42,"verses":[7,8],"references":[{"surah":42,"verses":[7,8]}],"verseLabel":"الشورى: 7–8","question":"لماذا قيل: ﴿لَجَعَلَهُمْ أُمَّةً وَاحِدَةً﴾ ولم يقل: لخلقهم؟","answer":"لأن الخلق إيجادهم من العدم، أما الجعل هنا فتصييرهم بعد وجودهم مجتمعين على ملة واحدة؛ فاختير اللفظ الأدق لإظهار القدرة على توجيههم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص773، تحت عنوان «دلالة التعبير بالجعل مادة وصيغة»","url":""}]},{"id":"s42-21","number":21,"surah":42,"verses":[8],"references":[{"surah":42,"verses":[8]}],"verseLabel":"الشورى: 8","question":"ما سر التعبير بدخول من يشاء الله ﴿فِي رَحْمَتِهِ﴾؟","answer":"الرحمة هنا يراد بها الجنة على التوجيه المذكور، فأطلق اسم الرحمة وأريد محلها. وتصويرهم داخلين فيها، بدل الاكتفاء بذكر نيلها، يوحي بتمكنهم من النعيم وإحاطته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص775، تحت عنوان «بلاغة المجاز في الآية»","url":""}]},{"id":"s42-22","number":22,"surah":42,"verses":[8],"references":[{"surah":42,"verses":[8]}],"verseLabel":"الشورى: 8","question":"لماذا أُظهر وصف ﴿الظَّالِمُونَ﴾ بدل أن يقال: وهم ما لهم من ولي؟","answer":"لتسجيل سبب حرمانهم والوعيد عليهم؛ فوضع وصف الظلم مكان الضمير يعلن أن ظلمهم هو الذي أوردهم هذا المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص775–776، تحت عنوان «دلالة الواو والتعبير بالجملة الاسمية»","url":""}]},{"id":"s42-23","number":23,"surah":42,"verses":[6,9],"references":[{"surah":42,"verses":[6,9]}],"verseLabel":"الشورى: 6، 9","question":"لماذا عاد السياق إلى إنكار اتخاذ الأولياء بقوله: ﴿أَمِ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ﴾؟","answer":"ليجدد إنكار شركهم بعد عرض دلائل الوحي والملك والقدرة؛ فكأن كل حجة سبقت تستدعي سؤالًا توبيخيًا جديدًا: كيف بقي لهم بعد ذلك ولي من دون الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص780، تحت عنوان «معنى ﴿أم﴾ ودلالتها»","url":""}]},{"id":"s42-149","number":149,"surah":42,"verses":[6,9],"references":[{"surah":42,"verses":[6,9]}],"verseLabel":"الشورى: 6، 9","question":"ماذا يفيد القصر في قوله: ﴿فَاللَّهُ هُوَ الْوَلِيُّ﴾؟","answer":"يحصر الولاية الحقيقية الكاملة في الله؛ فتعريف الطرفين وضمير الفصل يبطلان ولاية ما اتخذوه من دونه، ويثبتان أنه وحده المتولي لعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص783، تحت عنوان «بلاغة أسلوب القصر، ودلالة ضمير الفصل في قوله ﴿فالله هو الولي﴾»","url":""}]},{"id":"s42-24","number":24,"surah":42,"verses":[9],"references":[{"surah":42,"verses":[9]}],"verseLabel":"الشورى: 9","question":"لماذا استُدل على ولاية الله بقوله: ﴿وَهُوَ يُحْيِي الْمَوْتَى﴾؟","answer":"لأن من يملك إعادة الخلق بعد الموت هو المستحق وحده للولاية والاعتماد؛ فأُدمج إثبات البعث في الرد على الشرك وهدم دعوى الأولياء العاجزين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص783، تحت عنوان «بلاغة الإدماج في قوله ﴿وهو يحيي الموتى﴾»","url":""}]},{"id":"s42-25","number":25,"surah":42,"verses":[10],"references":[{"surah":42,"verses":[10]}],"verseLabel":"الشورى: 10","question":"ما سر التعبير عن مرجع الاختلاف بقوله ﴿فَحُكْمُهُ إِلَى اللَّهِ﴾ دون «فالله يحكم فيه»؟","answer":"المصدر ﴿حكمه﴾ مجرد من الزمن، فيقرر رجوع الحكم إلى الله تقريرًا ثابتًا غير مقيد بحال معينة. والتعبير الخبري يتضمن طلب الاحتكام إلى ما أنزله، فيجعل لزوم هذا الرجوع أمرًا مقررًا مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص790، تحت عنوان «دلالة التعبير بالمصدر (حكمه)»","url":""}]},{"id":"s42-26","number":26,"surah":42,"verses":[10],"references":[{"surah":42,"verses":[10]}],"verseLabel":"الشورى: 10","question":"لماذا جاء التوكل ماضيًا في ﴿تَوَكَّلْتُ﴾ والإنابة مضارعة في ﴿أُنِيبُ﴾؟","answer":"لأن التوكل أصل ثابت استقر في القلب، فجاء بالماضي، أما الإنابة فهي رجوع يتجدد بتجدد الأحوال والأعمال، فجاءت بالمضارع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص793، تحت عنوان «دلالة التعبير بالماضي ﴿توكلت﴾، والمضارع ﴿أنيب﴾»","url":""}]},{"id":"s42-27","number":27,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا جُمعت أزواج الناس وأزواج الأنعام في آية واحدة؟","answer":"ليجمع الإيجاز بين استمرار نسل الإنسان وبين ما تقوم به معيشته من تناسل الأنعام ومنافعها؛ فالتزاوج نظام ممتد في العالم الحي لا نعمة منفصلة للإنسان وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص800، تحت عنوان «بلاغة واو العطف، ودورها الوظيفي في الإيجاز»","url":""}]},{"id":"s42-150","number":150,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا اختير فعل ﴿يَذْرَؤُكُمْ﴾ للتعبير عن التكاثر؟","answer":"لأن الذرء يدل على البث والتكثير، وجاء مضارعًا ليصور تجدد الأجيال واستمرار النماء عبر هذا النظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص802، تحت عنوان «بلاغة اختيار الذرء مادة وصيغة»","url":""}]},{"id":"s42-151","number":151,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"ماذا تضيف ﴿فِيهِ﴾ في قوله: ﴿يَذْرَؤُكُمْ فِيهِ﴾؟","answer":"تصور نظام التزاوج كأنه محيط تجري في داخله أسباب التكاثر والنماء؛ فليست الظرفية مكانًا حسيًا، بل تصويرًا لتمكن هذا النظام من حياة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص803، تحت عنوان «بلاغة حرف الظرفية»","url":""}]},{"id":"s42-28","number":28,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا قيل: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ﴾ بدل «ليس مثله شيء»؟","answer":"لأن التعبير يسلك طريق الكناية الأبلغ في نفي النظير: فإذا نُفي أن يكون لمثله مثل، كان نفي المماثلة عنه سبحانه أبلغ وأرسخ، من غير أن يثبت له مثلًا أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص805، تحت عنوان «بلاغة الكناية في جملة ﴿ليس كمثله شيء﴾»","url":""}]},{"id":"s42-29","number":29,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا جمع قوله: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾ بين النفي والإثبات؟","answer":"ليجمع أصل التنزيه كاملًا: ينفي عن الله مماثلة المخلوقات، ويثبت له صفات الكمال على الوجه اللائق به؛ فلا يؤدي التنزيه إلى تعطيل صفاته، ولا يؤدي إثباتها إلى تشبيهه بخلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص808، تحت عنوان «بلاغة الجمع بين جملتي النفي والإثبات»","url":""}]},{"id":"s42-30","number":30,"surah":42,"verses":[12],"references":[{"surah":42,"verses":[12]}],"verseLabel":"الشورى: 12","question":"لماذا أعقب ﴿لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ﴾ بذكر بسط الرزق وتقديره؟","answer":"لأن توسيع الرزق وتضييقه أثر مشاهد من آثار امتلاك تلك الخزائن؛ فانتقل من تقرير الملك العام إلى مثال يمسه الناس في حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص809–810، تحت عنوان «موقع جملة بسط الرزق وتقديره»","url":""}]},{"id":"s42-152","number":152,"surah":42,"verses":[12],"references":[{"surah":42,"verses":[12]}],"verseLabel":"الشورى: 12","question":"لماذا خُتم بسط الرزق وتقديره بقوله: ﴿إِنَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾؟","answer":"ليبين أن التوسعة والتضييق ليسا عشوائيين، بل يجريان بعلم كامل بأحوال العباد وما يصلحهم؛ فالعلم أساس هذا التقدير الحكيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص812، تحت عنوان «علة فصل جملة ﴿إنه بكل شيء عليم﴾»","url":""}]},{"id":"s42-31","number":31,"surah":42,"verses":[13],"references":[{"surah":3,"verses":[103]},{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13؛ آل عمران: 103","question":"لماذا قُيد النهي بقوله: ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾؟","answer":"ليحدد موطن التفرق المنهي عنه: الدين الذي شرعه الله وجمع عليه رسله؛ فالمخالفة المذمومة هي تمزيق وحدته والخروج عن أصوله الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص21، تحت عنوان «سر تقييد فعل ﴿تتفرقوا﴾ بقيد ﴿فيه﴾»","url":""}]},{"id":"s42-32","number":32,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا قيل للنبي ﷺ: ﴿وَالَّذِي أَوْحَيْنَا إِلَيْكَ﴾، وقيل في الرسل قبله: ﴿وَصَّى بِهِ﴾؟","answer":"لأن الوصية تؤكد أصل الدين الذي عُهد إلى الرسل بحفظه، أما الإيحاء إلى النبي ﷺ فينوه بتشريفه وبتفصيل الشريعة الكاملة التي أنزلت إليه، مع وحدة أصل الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص17، تحت عنوان «بلاغة استعمال ﴿أوحينا﴾ مادة وصيغة دون (وصينا)»","url":""}]},{"id":"s42-33","number":33,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا خُص نوح وإبراهيم وموسى وعيسى مع النبي ﷺ بالذكر؟","answer":"لأنهم أولو العزم وأصحاب الشرائع العظيمة التي اتبعتها الأمم؛ فذكرهم يبرز أن أصل الدين الجامع ثابت في أعظم الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص19، تحت عنوان «توجيه تخصيص هؤلاء المرسلين بالذكر»","url":""}]},{"id":"s42-34","number":34,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا عبّر عن العمل بالدين بقوله: ﴿أَقِيمُوا الدِّينَ﴾؟","answer":"شُبه الدين ببناء يقام مستقيمًا؛ فالإقامة ليست مجرد معرفته، بل حفظ أصوله والعمل بها وإظهاره من غير اعوجاج أو تعطيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص20، تحت عنوان «دلالة انتقاء مفردة ﴿أقيموا﴾ مادة وصيغة»","url":""}]},{"id":"s42-153","number":153,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا جُمع بين الأمر بـ﴿أَقِيمُوا الدِّينَ﴾ والنهي ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾؟","answer":"لأن إقامة الدين تحفظ استقامة العمل به، والنهي عن التفرق يحفظ وحدة أهله عليه؛ فاجتمع إصلاح المضمون وصيانة الجماعة من التمزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص21، تحت عنوان «نوع الواو في قوله ﴿ولا تتفرقوا﴾»","url":""}]},{"id":"s42-35","number":35,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا قيل: ﴿اللَّهُ يَجْتَبِي إِلَيْهِ﴾ ولم يكتف بقوله «يجتبي»؟","answer":"للدلالة على شرف المجتبى وقربه؛ فالاصطفاء ليس اختيارًا مجردًا، بل تقريب إلى الله وتشريف بمنزلة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص25، تحت عنوان «علة ذكر ﴿إليه﴾ دون الاكتفاء بالإطلاق»","url":""}]},{"id":"s42-154","number":154,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا عُطفت الهداية على الاجتباء في قوله: ﴿وَيَهْدِي إِلَيْهِ مَنْ يُنِيبُ﴾؟","answer":"لبيان طريقين من فضل الله: اجتباء خاص لمن يصطفيه، وهداية يوفق إليها من يرجع إليه ويطلب الحق؛ فالهداية أوسع، والاجتباء أخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص26، تحت عنوان «دلالة عطف الهداية على الاجتباء»","url":""}]},{"id":"s42-36","number":36,"surah":42,"verses":[13,14],"references":[{"surah":42,"verses":[13,14]}],"verseLabel":"الشورى: 13–14","question":"لماذا جاء خبر تفرق السابقين مباشرة بعد الأمر: ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾؟","answer":"ليحذر المخاطبين من تكرار طريق من قبلهم؛ فكأن السياق يقول: الزموا الوحدة، فقد تفرق السابقون مع قيام العلم، فلا تجعلوا تاريخهم يتكرر فيكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص31، تحت عنوان «نوع الواو ودلالتها على المحذوف»","url":""}]},{"id":"s42-37","number":37,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"لماذا كُشف سبب التفرق بقوله: ﴿بَغْيًا﴾؟","answer":"لأن البغي يجمع الظلم والحسد وطلب الاستعلاء؛ فاختياره يكشف أن اختلافهم لم ينشأ من نقص الدليل، بل من فساد الإرادة مع معرفة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص35، تحت عنوان «بلاغة استعمال مفردة ﴿بغيًا﴾»","url":""}]},{"id":"s42-155","number":155,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"ماذا يضيف قيد ﴿بَيْنَهُمْ﴾ بعد قوله: ﴿بَغْيًا﴾؟","answer":"يكشف أن البغي نشأ وتبادل داخل جماعتهم نفسها، مع أن وحدة العلم والدين كانت تقتضي الألفة؛ فزاد القيد قبح التفرق وفضح دوافعه الداخلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص35، تحت عنوان «دلالة تقييد البغي بشبه الجملة»","url":""}]},{"id":"s42-38","number":38,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"لماذا سُمّي قضاء الإمهال ﴿كَلِمَةً سَبَقَتْ مِنْ رَبِّكَ﴾؟","answer":"للدلالة على ثبات قضاء الله ونفاذه؛ فما سبق من وعده بالإمهال لا يتبدل، ولذلك تأخر الفصل إلى موعده المقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص37، تحت عنوان «دلالة التعبير بالكلمة»","url":""}]},{"id":"s42-39","number":39,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"لماذا قيل عن المتأخرين: ﴿أُورِثُوا الْكِتَابَ﴾؟","answer":"لأن الكتاب وصل إليهم من أسلافهم ميسرًا حاضرًا كالميراث؛ فالتعبير يقوي مؤاخذتهم حين شكوا مع سهولة طريق العلم وقيام الحجة بين أيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص41، تحت عنوان «نكتة استعمال مفردة ﴿أورثوا﴾ مادة وصيغة»","url":""}]},{"id":"s42-40","number":40,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"إلى ماذا يشير اسم الإشارة في قوله: ﴿فَلِذَلِكَ فَادْعُ﴾؟","answer":"يشير إلى الدين الواحد الذي شرعه الله وأوصى به رسله، وإلى ضرورة جمع الناس عليه بعد ما وقع من التفرق والشك؛ فالدعوة رد إلى الأصل الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص47، تحت عنوان «دلالة استعمال اسم الإشارة للبعيد»","url":""}]},{"id":"s42-156","number":156,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا قُدم ﴿فَلِذَلِكَ﴾ على الأمر ﴿فَادْعُ﴾؟","answer":"للعناية بسبب الدعوة وإبرازه قبل التكليف؛ فالتفرق والشك يجعلان رد الناس إلى الدين الحق غاية ملحة تتقدم في الذهن على فعل الدعوة نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص47، تحت عنوان «علة تقديم شبه الجملة على متعلقها»","url":""}]},{"id":"s42-41","number":41,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا عُطف ﴿وَاسْتَقِمْ كَمَا أُمِرْتَ﴾ على الأمر ﴿فَادْعُ﴾؟","answer":"لأن الداعي لا يكفي أن يبلغ الناس، بل يجب أن يكون ثابتًا على ما يدعو إليه؛ فتجتمع الدعوة بالقول والقدوة بالعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص48، تحت عنوان «نكتة عطف الأمر بالاستقامة على الأمر بالدعوة»","url":""}]},{"id":"s42-157","number":157,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا أتبع الدعوة والاستقامة بالنهي: ﴿وَلَا تَتَّبِعْ أَهْوَاءَهُمْ﴾؟","answer":"ليحميهما من ضغط المخالفين؛ فاتباع أهوائهم يفسد صدق الدعوة ويصرف عن الاستقامة، فجاء النهي سياجًا للثبات على الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص49–50، تحت عنوان «وجه عطف النهي ﴿ولا تتبع﴾ على الأمر ﴿فادع﴾»","url":""}]},{"id":"s42-42","number":42,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا انتقل من الدعوة إلى وحدة الدين إلى إعلان: ﴿آمَنْتُ بِمَا أَنْزَلَ اللَّهُ مِنْ كِتَابٍ﴾؟","answer":"لأن الإيمان بجميع الوحي تطبيق عملي لوحدة الدين، ورد على من فرقوا فصدقوا بعض الكتب وكفروا ببعض؛ فجمع الإعلان ما فرقه المختلفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص51، تحت عنوان «دلالة عطف الأمر (قل) على السابق»","url":""}]},{"id":"s42-158","number":158,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"ماذا يفيد تنكير ﴿كِتَابٍ﴾ في قوله: ﴿مِنْ كِتَابٍ﴾؟","answer":"يفيد العموم: أي آمنت بكل كتاب أنزله الله من غير تفريق؛ فتنسجم العبارة مع دعوة السورة إلى وحدة أصل الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص53، تحت عنوان «غرض تنكير ﴿كتاب﴾»","url":""}]},{"id":"s42-43","number":43,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا اقترن قوله: ﴿آمَنْتُ بِمَا أَنْزَلَ اللَّهُ﴾ بقوله: ﴿وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ﴾؟","answer":"ليجمع بين أصل الاعتقاد وأثره العملي؛ فالإيمان بالوحي يقتضي عدلًا لا يتبدل باختلاف المخاطبين، والعدل نفسه أمر من الله لا مصلحة بشرية عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص53، تحت عنوان «دلالة واو العطف في قوله ﴿وأمرت﴾»","url":""}]},{"id":"s42-44","number":44,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"ما سر التوازي بين ﴿اللَّهُ رَبُّنَا وَرَبُّكُمْ﴾ و﴿لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ﴾؟","answer":"وحدة الرب تدعو الفريقين إلى الاجتماع على الحق، ثم يقرر توزيع الأعمال أن كل فريق مسؤول عن كسبه وجزائه؛ فاجتمع مرجع واحد مع مسؤولية لا يحملها أحد عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص57، تحت عنوان «فائدة العطف بين الجملتين الاسميتين»","url":""}]},{"id":"s42-45","number":45,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا قيل: ﴿لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ﴾ مع أن المؤمنين يملكون الحجة؟","answer":"الحجة هنا المحاجة والخصومة، لا البرهان؛ فالمعنى أن الحق قد بُين ولم تبق فائدة في استمرار الجدل، لا أن أدلة الإيمان غائبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص57، تحت عنوان «بلاغة استعمال مفردة ﴿حجة﴾»","url":""}]},{"id":"s42-159","number":159,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"ما الكناية في قوله بعد انتهاء المحاجة: ﴿اللَّهُ يَجْمَعُ بَيْنَنَا﴾؟","answer":"الجمع كناية عن جمع الفريقين يوم القيامة للحكم والفصل واستيفاء الحقوق؛ فانتقل من جدل الدنيا الذي لا ينتهي إلى القضاء الذي يظهر فيه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص59، تحت عنوان «بلاغة الكناية في لفظ ﴿يجمع﴾»","url":""}]},{"id":"s42-46","number":46,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"ما الصورة في وصف حجة المحاجين بأنها ﴿دَاحِضَةٌ﴾؟","answer":"استعير الدحض، وهو الزلق عن موضع الثبات، لبطلان حجتهم؛ فكأنها تحاول الوقوف فلا تجد أرضًا تستقر عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص69، تحت عنوان «بلاغة الاستعارة في قوله ﴿داحضة﴾»","url":""}]},{"id":"s42-160","number":160,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"لماذا قيل: ﴿حُجَّتُهُمْ دَاحِضَةٌ عِنْدَ رَبِّهِمْ﴾ بوصف الربوبية؟","answer":"لزيادة توبيخهم؛ فحجتهم باطلة عند من خلقهم ورباهم وتولى أمرهم، ومع ذلك يحاجون في دينه ويعرضون عن هديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص70، تحت عنوان «دلالة التعبير بوصف الربوبية في ﴿ربهم﴾»","url":""}]},{"id":"s42-47","number":47,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"لماذا انتقل جزاء المحاجِّين من دحض حجتهم إلى غضب الله عليهم؟","answer":"لأن سقوط حجتهم فضيحة لهم في الدنيا، ثم يعقبه غضب الله جزاءً أخرويًا؛ فالعطف يجمع خسارتهم في موطن البرهان وخسارتهم عند الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص71، تحت عنوان «دلالة التعبير بالواو في ﴿وعليهم﴾»","url":""}]},{"id":"s42-161","number":161,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"ماذا يضيف قوله: ﴿وَلَهُمْ عَذَابٌ شَدِيدٌ﴾ بعد ذكر الغضب؟","answer":"يجعل العذاب نتيجة ثابتة مستقلة للغضب، لا حالة عابرة؛ فالجملة الاسمية مع العطف ترسّخ دوام الجزاء وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص72، تحت عنوان «دلالة الواو في ﴿ولهم عذاب﴾»","url":""}]},{"id":"s42-48","number":48,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"لماذا جُمع بين إنزال الكتاب وإنزال الميزان؟","answer":"لأن الكتاب يقرر منهج الحق، والميزان يترجم ذلك المنهج إلى عدل يضبط الحكم والمعاملة؛ فاجتماعهما يربط الوحي بإقامة القسط في واقع الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص82، تحت عنوان «دلالة العطف في قوله: ﴿والميزان﴾»","url":""}]},{"id":"s42-162","number":162,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"لماذا سُمِّي العدل ﴿الْمِيزَانَ﴾؟","answer":"لأن الميزان الحسي يميّز المقادير ويمنع الجور، فاستعير للعدل والشريعة اللذين تُوزن بهما الحقوق والأعمال وتستقيم بهما حياة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص82، تحت عنوان «بلاغة المجاز في التعبير بلفظ ﴿الميزان﴾»","url":""}]},{"id":"s42-49","number":49,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"لماذا جاء التنبيه على قرب الساعة بعد إنزال الكتاب والميزان؟","answer":"لأن الحساب هو الموطن الذي تظهر فيه ثمرة الالتزام بالكتاب والعدل، وفيه يوفّى كل إنسان ما قدّم؛ فجاء ذكر الساعة ليصل المنهج بعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص83، تحت عنوان «دور التعبير بالاستئناف»","url":""}]},{"id":"s42-163","number":163,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"ماذا يضيف قوله: ﴿وَمَا يُدْرِيكَ لَعَلَّ السَّاعَةَ قَرِيبٌ﴾ بعد ذكر الكتاب والميزان؟","answer":"يذيّل السياق بإنذار يوقظ من الغفلة: فالميزان الذي أُنزل لإقامة العدل سيعقبه ميزان الجزاء، ووقت الساعة مجهول قد يكون قريبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص86، تحت عنوان «بلاغة التذييل بقوله: ﴿وما يدريك لعل الساعة قريب﴾»","url":""}]},{"id":"s42-50","number":50,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"ما سر وصف الساعة المؤنثة بقوله ﴿قَرِيبٌ﴾؟","answer":"تذكر الموسوعة أن الساعة غير حقيقية التأنيث، فيجوز تذكير خبرها وتأنيثه، وأن المعنى يمكن أن يحمل على قرب وقتها أو مجيئها. وتذكر أيضًا استعمال العرب «قريب» استعمال الظرف الذي لا تلزمه علامة التأنيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص85–86، تحت عنوان «سر التعبير بقوله ﴿قريب﴾ دون (قريبة)»","url":""}]},{"id":"s42-51","number":51,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"لماذا يستعجل غير المؤمنين بالساعة؟","answer":"لا يستعجلونها طلبًا لوقوعها، بل سخريةً وإنكارًا؛ إذ يتخذون تأخرها ذريعة للتكذيب ويطلبونها طلب المستهزئ الذي لا يوقن بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص92، تحت عنوان «سر استعجال ﴿الذين لا يؤمنون﴾ وقوع الساعة»","url":""}]},{"id":"s42-164","number":164,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"كيف قابلت الآية بين مستعجلي الساعة والمشفقين منها بهذا الإيجاز؟","answer":"ذكرت من الكافرين استعجالهم الدال على إنكارهم، ومن المؤمنين إشفاقهم الدال على تصديقهم، فدل كل مذكور على المقابل المحذوف في الطرف الآخر؛ وهذا هو الاحتباك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص94، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s42-165","number":165,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"لماذا وُصف خوف المؤمنين من الساعة بالإشفاق؟","answer":"لأن الإشفاق خوفٌ ممزوج بعناية واستعداد، لا فزع مجرد؛ فهم يوقنون بالساعة فيحذرون حسابها ويعملون لما ينجيهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص95، تحت عنوان «سر التعبير بالإشفاق دون الخوف»","url":""}]},{"id":"s42-166","number":166,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"لماذا قيل عن المؤمنين: ﴿وَيَعْلَمُونَ أَنَّهَا الْحَقُّ﴾ بعد وصف إشفاقهم؟","answer":"ليبيّن أن خوفهم ثمرة يقين راسخ لا وهم عابر؛ فهم يستعدون للساعة لأنهم يعلمون حتم وقوعها وحقيقة ما فيها من حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص96، تحت عنوان «دلالة العطف في قوله: ﴿ويعلمون﴾»","url":""}]},{"id":"s42-52","number":52,"surah":42,"verses":[17,18],"references":[{"surah":42,"verses":[17,18]}],"verseLabel":"الشورى: 17–18","question":"لماذا قوبل قرب الساعة بوصف ضلال الممارين فيها بأنه بعيد؟","answer":"لأن الساعة قريبة الوقوع، لكن إنكارهم لها أبعدهم عن دلائل الحق؛ فبرزت المفارقة بين قرب الحقيقة وشدة بُعدهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص101، تحت عنوان «سر وصف الضلال بالبعيد»","url":""}]},{"id":"s42-53","number":53,"surah":42,"verses":[19],"references":[{"surah":42,"verses":[19]}],"verseLabel":"الشورى: 19","question":"ما دلالة الجمع بين اسمي الله ﴿الْقَوِيُّ الْعَزِيزُ﴾ بعد ذكر الرزق؟","answer":"يدل اقترانهما على أن عطاء الله صادر عن قدرة لا يعجزها شيء، وعن عزة لا يمانعها أحد؛ فلا يستطيع مخلوق منع رزقه أو نقض تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص110، تحت عنوان «دلالة الجمع بين وصفي القوة والعزة»","url":""}]},{"id":"s42-54","number":54,"surah":42,"verses":[19],"references":[{"surah":42,"verses":[19]}],"verseLabel":"الشورى: 19","question":"ما مناسبة وصف الله باللطف في سياق الرزق؟","answer":"لأن رزقه يصل إلى عباده بطرق دقيقة قد تخفى عليهم، ويهيئ لهم أسباب المعاش من حيث لا يشعرون؛ فالرزق مظهر ظاهر للطفه الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص108، تحت عنوان «سر لطف لفظة ﴿يرزق من يشاء﴾ عما قبلها»","url":""}]},{"id":"s42-55","number":55,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا سُمِّي العمل للآخرة ﴿حَرْثَ الْآخِرَةِ﴾؟","answer":"لأن العامل يزرع في الدنيا بطاعته ما يحصد ثمرته في الآخرة، كما يبذر الزارع البذر منتظرًا نماءه؛ فالتعبير يجسّد الصلة بين السعي والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص116، تحت عنوان «بلاغة المجاز في قوله: ﴿حرث الآخرة﴾»","url":""}]},{"id":"s42-167","number":167,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا عُبِّر عن السعي للدنيا بالحرث؟","answer":"لأن طالب الدنيا يبذل ويكدح ليحصل ثمرتها كما يحرث الزارع أرضه، غير أن حصاده محدود بحدود الدنيا وزوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص120، تحت عنوان «سر التعبير عن السعي للدنيا بالحرث»","url":""}]},{"id":"s42-56","number":56,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا وُعد مريد الآخرة بالزيادة في حرثه؟","answer":"لأن عمل الآخرة لا يرد إلى صاحبه بمقداره فقط، بل ينمّيه الله ويضاعف ثوابه؛ فجاء لفظ الزيادة ليفتح معنى الفضل المتجدد فوق أصل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص116–117، تحت عنوان «سر التعبير بلفظ الزيادة من حيث المادة والصيغة»","url":""}]},{"id":"s42-168","number":168,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا قيل لمريد الآخرة: ﴿نَزِدْ لَهُ فِي حَرْثِهِ﴾، ولمريد الدنيا: ﴿نُؤْتِهِ مِنْهَا﴾؟","answer":"لأن ﴿في﴾ توحي بنماء حرث الآخرة في داخله وتضاعفه، أما ﴿من﴾ فتفيد أن طالب الدنيا لا ينال إلا بعضًا منها؛ فالأول فضل متزايد والثاني نصيب محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص121، تحت عنوان «سر التعبير بـ(من) مع الدنيا و(في) مع الآخرة»","url":""}]},{"id":"s42-57","number":57,"surah":42,"verses":[21],"references":[{"surah":42,"verses":[21]}],"verseLabel":"الشورى: 21","question":"لماذا سُمِّي مشرِّعو الدين الباطل ﴿شُرَكَاءَ﴾؟","answer":"لأن طاعتهم في التشريع من دون الله جعلتهم بمنزلة من نازع الله حقه الخالص في التحليل والتحريم، وفي اللفظ تهكم يكشف بطلان هذه الشراكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص130، تحت عنوان «سر التعبير بلفظ ﴿شركاء﴾»","url":""}]},{"id":"s42-169","number":169,"surah":42,"verses":[21],"references":[{"surah":42,"verses":[21]}],"verseLabel":"الشورى: 21","question":"لماذا قيل عن أهل الدين الباطل: ﴿شَرَعُوا لَهُمْ﴾؟","answer":"لأنهم صاغوا أهواءهم في صورة أحكام تُتبع، فكأنهم حاكوا فعل الشارع الحق؛ وفي اختيار اللفظ تشنيع على جرأتهم في إضفاء صفة الدين على الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص131، تحت عنوان «سر التعبير بلفظ ﴿شرعوا﴾»","url":""}]},{"id":"s42-58","number":58,"surah":42,"verses":[21],"references":[{"surah":42,"verses":[21]}],"verseLabel":"الشورى: 21","question":"لماذا عُبِّر عن بطلان تشريع الشركاء بأنه مما ﴿لَمْ يَأْذَنْ بِهِ اللَّهُ﴾؟","answer":"لأن الإذن هو علامة المشروعية والسلطان، فإذا انتفى إذن الله سقط عن ذلك التشريع كل سند ديني، وبان أنه افتراء لا حق لأحد في إلزام الناس به.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص133، تحت عنوان «سر التعبير بالإذن»","url":""}]},{"id":"s42-59","number":59,"surah":42,"verses":[14,21],"references":[{"surah":42,"verses":[14,21]}],"verseLabel":"الشورى: 14، 21","question":"لماذا نُكِّرت ﴿كَلِمَةٌ﴾ في قوله: ﴿وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ﴾؟","answer":"للتعظيم والتهويل؛ فهي كلمة قاطعة نافذة اقتضت إمهالهم إلى الأجل، وعِظم أثرها يغني عن تعيين ألفاظها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص37، تحت عنوان «غرض تنكير ﴿كلمة﴾»","url":""}]},{"id":"s42-170","number":170,"surah":42,"verses":[14,21],"references":[{"surah":42,"verses":[14,21]}],"verseLabel":"الشورى: 14، 21","question":"ماذا تفيد إضافة ﴿كَلِمَةُ﴾ إلى ﴿الْفَصْلِ﴾؟","answer":"تفيد أنها الكلمة المعيّنة الحاسمة التي ينتهي بها النزاع ويتميز بها المحق من المبطل عند القضاء النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص135، تحت عنوان «دلالة إضافة ﴿كلمة﴾ إلى ﴿الفصل﴾»","url":""}]},{"id":"s42-171","number":171,"surah":42,"verses":[14,21],"references":[{"surah":42,"verses":[14,21]}],"verseLabel":"الشورى: 14، 21","question":"لماذا قيل: ﴿كَلِمَةُ الْفَصْلِ﴾ دون كلمة القضاء أو الحكم؟","answer":"لأن الفصل لا يكتفي بإصدار الحكم، بل يقطع الخصومة ويفرّق بين الحق والباطل بحيث لا يبقى بعده نزاع ولا التباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص135، تحت عنوان «سر التعبير بالفصل دون القضاء أو الحكم»","url":""}]},{"id":"s42-60","number":60,"surah":42,"verses":[16,21],"references":[{"surah":42,"verses":[16,21]}],"verseLabel":"الشورى: 16، 21","question":"لماذا وُصف عذاب المحاجِّين في الله بأنه ﴿شَدِيدٌ﴾؟","answer":"لأن محاجتهم جاءت بعد الاستجابة للحق وقيام الحجة، فناسب عنادهم القوي وصف العذاب بالشدة التي تشمل قوة الإيلام وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص73–74، تحت عنوان «سر وصف العذاب بالشديد دون المهين والأليم والعظيم»","url":""}]},{"id":"s42-172","number":172,"surah":42,"verses":[16,21],"references":[{"surah":42,"verses":[16,21]}],"verseLabel":"الشورى: 16، 21","question":"لماذا وُصف عذاب أصحاب التشريع الباطل بأنه ﴿أَلِيمٌ﴾؟","answer":"لأنهم انحرفوا عن شرع الله وأضلوا غيرهم، فناسب جريمتهم إبراز ما يباشرونه من ألم العذاب وحسرتهم الدائمة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص138، تحت عنوان «سر وصف العذاب بالأليم دون العظيم»","url":""}]},{"id":"s42-61","number":61,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"لماذا عُطف ﴿وَهُوَ وَاقِعٌ بِهِمْ﴾ على إشفاق الظالمين من العذاب؟","answer":"ليبيّن أن خوفهم لا يغيّر المصير، بل إن العذاب الذي يشفقون منه نازل بهم حتمًا؛ فيجتمع في المشهد توقعهم المرعب وتحقق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص146، تحت عنوان «دلالة الواو في قوله ﴿وهو واقع﴾»","url":""}]},{"id":"s42-62","number":62,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"ما دلالة المقابلة بين وقوع العذاب بالظالمين ونعيم المؤمنين؟","answer":"تُظهر الفرق التام بين المصيرين: عذاب محتوم يهبط بالظالمين، وأمن واسع ينال فيه المؤمنون ما يشاؤون عند ربهم؛ فيزداد الوعد والوعيد وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص148، تحت عنوان «بلاغة المقابلة بين حال الظالمين وحال المؤمنين»","url":""}]},{"id":"s42-173","number":173,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"لماذا قيل للمؤمنين: ﴿لَهُمْ مَا يَشَاءُونَ﴾ دون «ما يطلبون»؟","answer":"للدلالة على أن نعيمهم يوافق رغباتهم من غير عناء طلب ولا انتظار؛ فما تقع عليه مشيئتهم مهيأ لهم عند ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص152–153، تحت عنوان «دلالة التعبير بالمشيئة دون الطلب»","url":""}]},{"id":"s42-63","number":63,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"لماذا عُبِّر عن نعيم المؤمنين بلفظ ﴿رَوْضَاتٍ﴾؟","answer":"لأن الروضة توحي بالخضرة والجمال وطيب المقام، وجمعها يدل على تنوع مشاهد النعيم واتساعها وتجدد بهجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص151، تحت عنوان «دلالة التعبير بـ﴿روضات﴾ مادة وصيغة»","url":""}]},{"id":"s42-174","number":174,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"ماذا تضيف إضافة الروضات إلى الجنات في ﴿رَوْضَاتِ الْجَنَّاتِ﴾؟","answer":"تجعل تلك الروضات مختارة من أعظم الجنات وأحسنها، فتضاعف صورة السعة والبهجة بدل أن يكون الحديث عن روضة واحدة محدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص151–152، تحت عنوان «دلالة إضافة الروضات إلى الجنات»","url":""}]},{"id":"s42-64","number":64,"surah":42,"verses":[22,23],"references":[{"surah":42,"verses":[22,23]}],"verseLabel":"الشورى: 22–23","question":"لماذا تكرر اسم الإشارة في ﴿ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ * ذَلِكَ الَّذِي يُبَشِّرُ اللَّهُ عِبَادَهُ﴾؟","answer":"ليعيد استحضار الفضل العظيم نفسه ويؤكده، ثم ينقله من وصف مجمل إلى بشارة مخصوصة لعباد الله المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص162، تحت عنوان «موقع جملة ﴿ذلك الذي ...﴾ مما قبلها ودلالته»","url":""}]},{"id":"s42-175","number":175,"surah":42,"verses":[22,23],"references":[{"surah":42,"verses":[22,23]}],"verseLabel":"الشورى: 22–23","question":"لماذا جاء تبشير الله عباده بالمضارع في ﴿يُبَشِّرُ﴾؟","answer":"ليصور البشارة متجددة متكررة، يقرؤها المؤمنون ويسمعونها جيلاً بعد جيل، فيظل أثر الرجاء حاضرًا في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص163، تحت عنوان «دلالة التعبير بالمضارع ﴿يبشر﴾»","url":""}]},{"id":"s42-65","number":65,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"لماذا استُعمل ﴿يَقْتَرِفْ﴾ مع الحسنة؟","answer":"لأن الاقتراف يدل على الاكتساب المتعمد، فيبرز أن الحسنة ثمرة قصد وسعي، وأن ما يحصله العبد منها يُثبت له ولو كان قليلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص174–175، تحت عنوان «دلالة التعبير بمادة الاقتراف في ﴿يقترف﴾»","url":""}]},{"id":"s42-176","number":176,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"ماذا يفيد الوعد: ﴿نَزِدْ لَهُ فِيهَا حُسْنًا﴾؟","answer":"يفيد أن جزاء الحسنة لا يقف عند مثلها، بل ينمّيه الله ويضاعف جمال أثرها وثوابها فضلًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص176، تحت عنوان «دلالة التعبير بمادة الزيادة في ﴿نزد﴾»","url":""}]},{"id":"s42-66","number":66,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"لماذا ذُيّل الوعد بزيادة الحسنة بقوله: ﴿إِنَّ اللَّهَ غَفُورٌ شَكُورٌ﴾؟","answer":"لأن الزيادة ثمرة شكره للطاعة، والمغفرة تجبر ما يعتري العامل من تقصير؛ فالتذييل يبيّن منشأ الفضل الذي وعدت به الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص177، تحت عنوان «الغرض من الختم بجملة التذييل ﴿إن الله غفور شكور﴾»","url":""}]},{"id":"s42-177","number":177,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"ما سر الجمع بين اسمي الله ﴿غَفُورٌ شَكُورٌ﴾؟","answer":"ليجمع للعبد زوال الشر وحصول الخير: يغفر الله الزلل، ويشكر العمل القليل فيثيب عليه كثيرًا؛ فلا يبقى التقصير حاجبًا ولا الطاعة بلا مضاعفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص178، تحت عنوان «سر اصطفاء الاسمين الجليلين ﴿غفور شكور﴾»","url":""}]},{"id":"s42-67","number":67,"surah":42,"verses":[24],"references":[{"surah":42,"verses":[24]}],"verseLabel":"الشورى: 24","question":"ما الدلالة البلاغية لحذف الواو رسمًا من ﴿وَيَمْحُ اللَّهُ الْبَاطِلَ﴾؟","answer":"يشير الحذف الخطي إلى سهولة محو الباطل وسرعة زواله أمام القدرة الإلهية، ويؤكد أن إبطاله أمر نافذ لا يعجز الله؛ أما في النطق فالفعل مرفوع والواو ثابتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص190، تحت عنوان «دلالة حذف الواو في ﴿ويمح﴾ في الوصل والوقف»","url":""}]},{"id":"s42-68","number":68,"surah":42,"verses":[24],"references":[{"surah":42,"verses":[24]}],"verseLabel":"الشورى: 24","question":"ماذا يضيف لفظ ﴿يَمْحُ﴾ إلى الوعد بزوال الباطل؟","answer":"لا يدل على مجرد إيقاف الباطل، بل على إزالته وإذهاب أثره؛ وجاء بالمضارع ليصور هذا سنة متجددة من سنن الله، يحفظ بها دينه ويزيل ما يفتريه المبطلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص189–190، تحت عنوان «دلالة التعبير بـ(يمح) مادة وصيغة»","url":""}]},{"id":"s42-69","number":69,"surah":42,"verses":[24,25],"references":[{"surah":42,"verses":[24,25]}],"verseLabel":"الشورى: 24–25","question":"لماذا عُقِّب قبول التوبة والعفو بقوله ﴿وَيَعْلَمُ مَا تَفْعَلُونَ﴾؟","answer":"ليؤكد أن القبول والعفو صادران عن علم تام لا عن خفاءٍ بالفعل؛ فهو يعلم صدق التائب وإخلاصه كما يعلم إصرار المسيء، فيجمع الختام بين فتح باب الرجاء والحث على مراقبة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص205، تحت عنوان «دلالة العطف في ﴿ويعلم﴾»","url":""}]},{"id":"s42-70","number":70,"surah":42,"verses":[25],"references":[{"surah":42,"verses":[25]}],"verseLabel":"الشورى: 25","question":"ماذا يوحي وصف الله بأنه ﴿يَقْبَلُ التَّوْبَةَ﴾؟","answer":"يوحي بأن رجوع العبد إلى ربه لا يضيع، بل يعتد الله به ويتلقاه بالرضا والقبول؛ وفي ذلك فتح لباب الأمل وحث على المبادرة بالتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص200–201، تحت عنوان «دلالة التعبير بمادة القبول»","url":""}]},{"id":"s42-200","number":200,"surah":42,"verses":[25],"references":[{"surah":42,"verses":[25]}],"verseLabel":"الشورى: 25","question":"ماذا يضيف قوله ﴿وَيَعْفُو عَنِ السَّيِّئَاتِ﴾ بعد قبول التوبة؟","answer":"يبين أن فضل الله لا يقف عند قبول الرجوع، بل يتجاوز السيئات ويمحو تبعتها ولا يؤاخذ بها؛ فتجتمع للتائب نعمة القبول ونعمة إسقاط العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص204، تحت عنوان «دلالة التعبير بمادة العفو»","url":""}]},{"id":"s42-71","number":71,"surah":42,"verses":[26],"references":[{"surah":42,"verses":[26]}],"verseLabel":"الشورى: 26","question":"من المستجيب في قوله ﴿وَيَسْتَجِيبُ الَّذِينَ آمَنُوا﴾: المؤمنون أم ربهم؟","answer":"يحتمل التعبير وجهين صحيحين: أن يجيب الله دعاء المؤمنين ويثيبهم على طاعتهم، أو أن يستجيب المؤمنون لربهم بالطاعة والانقياد. ويسمح اللفظ بالجمع بين المعنيين: استجابتهم له يعقبها قبوله وثوابه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص212، تحت عنوان «دلالة التعبير بمادة الاستجابة»","url":""}]},{"id":"s42-178","number":178,"surah":42,"verses":[26],"references":[{"surah":42,"verses":[26]}],"verseLabel":"الشورى: 26","question":"ماذا تضيف جملة ﴿وَيَزِيدُهُمْ مِنْ فَضْلِهِ﴾ بعد استجابة المؤمنين؟","answer":"تنقل الجزاء من مجرد الإجابة والثواب المستحق إلى عطاء زائد لا تحده أعمالهم؛ فالله يمنحهم فوق ما سألوا وفوق ما تقابله طاعتهم، وتتجدد هذه الزيادة من واسع فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص215، تحت عنوان «دلالة العطف بالواو في ﴿ويزيدهم﴾»","url":""}]},{"id":"s42-179","number":179,"surah":42,"verses":[26],"references":[{"surah":42,"verses":[26]}],"verseLabel":"الشورى: 26","question":"كيف جمعت الآية بين ترغيب المؤمنين وترهيب الكافرين بألفاظ قليلة؟","answer":"ذكرت استجابة المؤمنين وزيادتهم من الفضل، فدل ذلك على نجاتهم من العذاب؛ وذكرت عذاب الكافرين، فدل على حرمانهم من الإجابة والفضل. فحذف من كل جانب ما دل عليه مقابله، واكتمل الوعد والوعيد بإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص219، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s42-72","number":72,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا كان بسط الرزق لجميع الناس مظنةً للبغي في الأرض؟","answer":"لأن السعة العامة تفتح باب التنافس والاستعلاء، وقد تدفع النفوس إلى تجاوز الحدود طلبًا للمزيد؛ فتقدير الأرزاق يحفظ توازن الحياة ولا يعني أن كل غني يبغي أو أن الفقر يمنع البغي، وإنما يبين ما يغلب عند البسط الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص223–224، تحت عنوان «الغرض من التعبير بأسلوب الشرط بالأداة (لو)»","url":""}]},{"id":"s42-180","number":180,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا اختير لفظ ﴿لَبَغَوْا﴾ لوصف ما يفعله الناس عند بسط الرزق؟","answer":"لأن البغي يجمع تجاوز الحد والعدوان والظلم مع شدة الطلب والرغبة في الازدياد؛ فيصور كيف قد يحول التوسع في المال الشهوة إلى استعلاء وفساد يتعدى صاحبه إلى الأرض والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص227، تحت عنوان «دلالة التعبير بمادة البغي في ﴿لبغوا﴾»","url":""}]},{"id":"s42-73","number":73,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا عُبّر عن الرزق بقوله ﴿يُنَزِّلُ﴾؟","answer":"ليصوَّر الرزق عطاءً يأتي من عند الله إلى عباده، كما ينزل الغيث، فيستحضر مصدر النعمة وافتقار الخلق إلى تدبير المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص228، تحت عنوان «دلالة التعبير بمادة التنزيل في ﴿ينزل﴾»","url":""}]},{"id":"s42-201","number":201,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"ما الذي يضيفه المضارع ﴿يُنَزِّلُ﴾ إلى معنى الرزق؟","answer":"يصور إنزال الرزق فعلًا متجددًا مستمرًا، يتكرر على وفق أحوال العباد وحاجاتهم، لا عطاءً وقع مرة وانقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص229، تحت عنوان «دلالة التعبير بالمضارع ﴿ينزل﴾»","url":""}]},{"id":"s42-202","number":202,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا ينزل الله الرزق ﴿بِقَدَرٍ﴾؟","answer":"لأن العطاء مضبوط بعلمه وحكمته؛ فيبلغ كل عبد المقدار الذي يصلحه، فلا يكون البسط والمنع عشوائيين ولا خارجين عن التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص229، تحت عنوان «سر تقييد الفعل ﴿بقدر﴾»","url":""}]},{"id":"s42-74","number":74,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا جمع بين ﴿خَبِيرٌ﴾ و﴿بَصِيرٌ﴾ في تقدير أرزاق العباد؟","answer":"ليدل على شمول العلم الذي يقوم عليه التدبير: فالخبير محيط بالبواطن والحقائق وما تخفيه النفوس، والبصير محيط بالذوات والمشاهدات والظواهر؛ فلا يخفى عليه من حال عباده ما يصلح معه البسط أو التضييق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص232، تحت عنوان «سر اقتران ﴿بصير﴾ بـ﴿خبير﴾»","url":""}]},{"id":"s42-75","number":75,"surah":42,"verses":[27,28],"references":[{"surah":42,"verses":[27,28]}],"verseLabel":"الشورى: 27–28","question":"لماذا انتقل الحديث من تقدير الأرزاق إلى إنزال الغيث بعد القنوط؟","answer":"لأن الغيث مثال مشاهد على حكمة البسط والقبض: قد يؤخره الله حتى تظهر الحاجة ويزول الاتكال على العادة، ثم ينزله في وقته فتجتمع النعمة والدلالة على القدرة؛ فيرى الناس أثر التدبير الذي قررته الآية السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص234، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s42-76","number":76,"surah":42,"verses":[28],"references":[{"surah":42,"verses":[28]}],"verseLabel":"الشورى: 28","question":"لماذا وصفهم القرآن بأنهم ﴿قَنَطُوا﴾ ولم يكتف بوصف اليأس؟","answer":"لأن القنوط يصف يأسًا اشتد حتى انقطع معه الأمل وظهرت آثاره على ملامح الإنسان وتصرفاته؛ أما اليأس فأصله شعور في القلب والعقل. فالتعبير يرسم شدة الكرب التي جاء الغيث بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص242، تحت عنوان «دلالة التعبير بـ﴿قنطوا﴾ مادة وصيغة»","url":""}]},{"id":"s42-77","number":77,"surah":42,"verses":[28],"references":[{"surah":42,"verses":[28]}],"verseLabel":"الشورى: 28","question":"ما الصورة التي يرسمها قوله بعد الغيث ﴿وَيَنْشُرُ رَحْمَتَهُ﴾؟","answer":"يصور الرحمة شيئًا يمتد وينبسط في أرجاء الحياة؛ فتتوزع آثار الغيث في النبات والحيوان والإنسان، وينقلب ضيق القنوط إلى رجاء وفرح ظاهرين، كأن الرحمة قد نُشرت أمام العيون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص243، تحت عنوان «بلاغة الاستعارة في ﴿ينشر﴾»","url":""}]},{"id":"s42-78","number":78,"surah":42,"verses":[28],"references":[{"surah":42,"verses":[28]}],"verseLabel":"الشورى: 28","question":"ما مناسبة ختم آية الغيث والرحمة بقوله ﴿وَهُوَ الْوَلِيُّ الْحَمِيدُ﴾؟","answer":"الولي يتولى مصالح عباده ويسوق إليهم ما يصلحهم من الغيث وغيره، والحميد هو المستحق للحمد على هذا التدبير والإنعام. فاقتران الاسمين يربط نعمة الغيث بولاية الله التي تستوجب حمده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص245، تحت عنوان «سر الاقتران في ﴿الولي الحميد﴾»","url":""}]},{"id":"s42-79","number":79,"surah":42,"verses":[29],"references":[{"surah":42,"verses":[29]}],"verseLabel":"الشورى: 29","question":"ماذا تصوّر كلمة ﴿بَثَّ﴾ في خلق الدواب؟","answer":"تصور نشر المخلوقات وتفريقها في مواطن متباينة مع كثرتها وتنوعها، فكأن الحياة قد انتشرت في أرجاء السماوات والأرض بعد خلقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص254، تحت عنوان «البث والنشر»","url":""}]},{"id":"s42-80","number":80,"surah":42,"verses":[29],"references":[{"surah":42,"verses":[29]}],"verseLabel":"الشورى: 29","question":"هل يدل قوله ﴿وَمَا بَثَّ فِيهِمَا مِنْ دَابَّةٍ﴾ على وجود مخلوقات في السماوات؟","answer":"الضمير يشمل السماوات والأرض، لكن دلالته لا تُحصر في صورة واحدة: قيل إن ذكرهما معًا من التغليب والدواب في الأرض، وقيل يشمل الطير أو أجناسًا من المخلوقات السماوية لا نعرفها. فالآية تثبت سعة القدرة ولا تعيّن لنا طبيعة تلك المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص248–249، تحت عنوان «معنى (في) ودلالتها في ﴿فيهما﴾»","url":""}]},{"id":"s42-81","number":81,"surah":42,"verses":[29],"references":[{"surah":42,"verses":[29]}],"verseLabel":"الشورى: 29","question":"لماذا قيل ﴿إذا يشاء﴾ لا «إن يشأ» عند الحديث عن جمع الخلق؟","answer":"لأن ﴿إذا﴾ تستحضر الجمع أمرًا متحقق الوقوع في الوقت الذي تعلقت به مشيئة الله، لا احتمالًا مشكوكًا فيه. فالاعتراض يرد البعث إلى توقيته الإلهي مع تأكيد أن القدرة عليه تامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص252–253، تحت عنوان «بلاغة الاعتراض في ﴿إذا يشاء﴾»","url":""}]},{"id":"s42-82","number":82,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"ما سر إسناد كسب السيئات إلى الأيدي في ﴿فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾؟","answer":"نسب الكسب إلى الأيدي لأنها أبرز آلات مباشرة العمل، وأطلق الجزء وأريد به الإنسان وعمله. وفي هذا التصوير إشعار بأن ما يؤاخذون به من فعلهم هم، فيدعو إلى محاسبة النفس بدل الغفلة عن أسباب المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص263، تحت عنوان «بلاغة التعبير بالمجاز المرسل ﴿أيديكم﴾»","url":""}]},{"id":"s42-83","number":83,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"هل يعني قوله ﴿وما أصابكم من مصيبة فبما كسبت أيديكم﴾ أن كل ابتلاء عقوبة؟","answer":"الخطاب عام فيمن تقع عليهم المؤاخذة بذنوبهم، لكنه لا يجعل كل ما ينزل بكل إنسان عقوبة؛ فالأنبياء ومن لا ذنب له قد يبتلون لرفع الدرجات وزيادة الأجر. فالآية تقرر أثر الكسب من غير أن تلغي حكم الابتلاء الأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص262، تحت عنوان «دلالة التعبير بـ﴿مصيبة﴾ نكرة»","url":""}]},{"id":"s42-181","number":181,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"ماذا يفيد اختيار لفظ ﴿يعفو﴾ بعد ذكر ما تكسبه الأيدي؟","answer":"يفيد ترك المؤاخذة والتجاوز عن الذنب مع ما في أصل العفو من الستر والمحو؛ فالله لا يعاقب عباده على كل ما كسبوا، بل يتجاوز عن كثير تفضلًا ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص264، تحت عنوان «دلالة التعبير بمادة العفو»","url":""}]},{"id":"s42-182","number":182,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"ماذا يفيد تنكير ﴿كثير﴾ في قوله ﴿ويعفو عن كثير﴾؟","answer":"يفخّم مقدار ما يتجاوز الله عنه، فيشمل ذنوبًا كثيرة أو خلقًا كثيرين لا يؤاخذهم بكل ما استحقوه. وفي إبقاء الكثير غير محصور إشعار بسعة الرحمة وعجز الإنسان عن إحصاء وجوه العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص265، تحت عنوان «الغرض من التنكير في ﴿كثير﴾»","url":""}]},{"id":"s42-84","number":84,"surah":42,"verses":[31],"references":[{"surah":42,"verses":[31]}],"verseLabel":"الشورى: 31","question":"ما سر الجمع بين نفي الإعجاز في الأرض ونفي الولي والنصير من دون الله؟","answer":"ينفي أولًا قدرتهم على الإفلات من سلطان الله، ثم ينفي أن يجدوا من دونه وليًا يتولى خلاصهم أو نصيرًا يدفع عنهم. فتسد الجملتان طريق الاعتماد على النفس وطريق الاستعانة بغيره في دفع ما أراده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص269، تحت عنوان «نكتة الواو ودلالتها في ﴿وما لكم﴾»","url":""}]},{"id":"s42-85","number":85,"surah":42,"verses":[31],"references":[{"surah":42,"verses":[31]}],"verseLabel":"الشورى: 31","question":"ما الذي يضيفه تنكير ﴿وَلِيٍّ﴾ و﴿نَصِيرٍ﴾؟","answer":"يعمم النفي حتى لا يبقى لهم أي ولي أو نصير، مهما صغر شأنه أو عظم؛ فلا حماية ولا معونة من أي جهة دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص272، تحت عنوان «نكتة تنكير ﴿ولي﴾ و﴿نصير﴾»","url":""}]},{"id":"s42-86","number":86,"surah":42,"verses":[29,32],"references":[{"surah":42,"verses":[29,32]}],"verseLabel":"الشورى: 29، 32","question":"لماذا جاءت السفن آيةً جديدة بعد ذكر خلق السماوات والأرض؟","answer":"لأن جريان السفن مثال محسوس قريب يضاف إلى الدليل الكلي في خلق السماوات والأرض؛ فتتجدد دعوة النظر في قدرة الله، وينتقل التأمل من إحاطة الخلق كله إلى نعمة يباشرها الناس في البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص275، تحت عنوان «معنى الواو ودلالتها في قوله ﴿ومن آياته﴾»","url":""}]},{"id":"s42-87","number":87,"surah":42,"verses":[32],"references":[{"surah":42,"verses":[32]}],"verseLabel":"الشورى: 32","question":"لماذا عُبّر عن السفن في البحر بـ﴿الجوار﴾؟","answer":"لإبراز حال جريانها، فهو موضع النعمة والعبرة في تسخير البحر. وإطلاق الجريان عليها يوجه النظر إلى حركتها الظاهرة كأنها هي الجريان نفسه، فيقوى مشهد القدرة التي تحملها وتسيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص276–277، تحت عنوان «بلاغة التعبير المجازي في إطلاق الجريان على السفن»","url":""}]},{"id":"s42-183","number":183,"surah":42,"verses":[32],"references":[{"surah":42,"verses":[32]}],"verseLabel":"الشورى: 32","question":"لماذا شُبّهت السفن الجارية في البحر بالأعلام؟","answer":"لأن الأعلام هي الجبال البارزة العالية؛ فالتشبيه يستحضر ضخامة السفن وظهورها من بعيد، ومع ذلك تجري فوق الماء ولا تغرق. فتتحول عظمتها وحركتها إلى آية ظاهرة على قدرة الله وتسخيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص277–278، تحت عنوان «الغرض من التعبير بالتشبيه في قوله ﴿الجوار في البحر كالأعلام﴾»","url":""}]},{"id":"s42-88","number":88,"surah":42,"verses":[32,33],"references":[{"surah":42,"verses":[32,33]}],"verseLabel":"الشورى: 32–33","question":"لماذا فُصل قوله ﴿إن يشأ يسكن الريح﴾ عما قبله من وصف السفن؟","answer":"لأنه استئناف يجيب عما يثيره مشهد السفن العظيمة من سؤال عن سر حركتها؛ فالله الذي أجراها قادر على إسكان الريح التي تحملها، وعندئذ تبقى ثابتة لا يحميها عظمها من العجز عن السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص284–285، تحت عنوان «سر فصل الآية عما قبلها»","url":""}]},{"id":"s42-89","number":89,"surah":42,"verses":[33],"references":[{"surah":42,"verses":[33]}],"verseLabel":"الشورى: 33","question":"لماذا قيل إن السفن تبقى ﴿على ظهره﴾ لا على سطح البحر؟","answer":"صوّر البحر ككائن له ظهر بارز تحمل عليه السفن، فبرز استقرارها وعلوها وظهورها للناظر. وهذه الاستعارة أقوى من لفظ السطح في تجسيد ثبات الأجسام الثقيلة فوق الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص288–289، تحت عنوان «سر التعبير بلفظ ﴿ظهره﴾ دون (سطحه)»","url":""}]},{"id":"s42-90","number":90,"surah":42,"verses":[33],"references":[{"surah":42,"verses":[33]}],"verseLabel":"الشورى: 33","question":"لماذا وصفت الآية المنتفع بآيات البحر بأنه ﴿صبار شكور﴾؟","answer":"لأن البحر يجمع أحوالًا تتكرر فيها الشدائد والنعم؛ فشدته تحتاج إلى صبر كثير، وتسخيره والنجاة فيه يحتاجان إلى شكر كثير. وصيغتا المبالغة تدلان على رسوخ الصفتين وتجددهما في صاحب العبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص291، تحت عنوان «سر اختيار ﴿صبار شكور﴾ مادة وصيغة وتنكيرًا»","url":""}]},{"id":"s42-184","number":184,"surah":42,"verses":[33],"references":[{"surah":42,"verses":[33]}],"verseLabel":"الشورى: 33","question":"لماذا قُدّم ﴿صبار﴾ على ﴿شكور﴾؟","answer":"لأن الصبر يسبق الشكر عند الشدة ويمهد له؛ فالإنسان يصبر على الخطر أولًا ثم يشكر نعمة التيسير والنجاة. كما أن الثبات على الشكر نفسه يحتاج إلى صبر، فكان تقديم الصبر أنسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص291، تحت عنوان «سر تقديم ﴿صبار﴾ على ﴿شكور﴾»","url":""}]},{"id":"s42-91","number":91,"surah":42,"verses":[33,34],"references":[{"surah":42,"verses":[33,34]}],"verseLabel":"الشورى: 33–34","question":"ماذا يضيف قوله ﴿أو يوبقهن﴾ بعد إمكان إسكان الريح؟","answer":"يضيف وجهًا آخر من القدرة والتهديد: فالله قد يسكن الريح فتركد السفن، وقد يرسلها عاصفة فتغرق. وبذلك تظهر أحوال السير والتوقف والهلاك جميعًا خاضعة لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص292، تحت عنوان «دلالة عطف قوله ﴿أو يوبقهن﴾ على جزاء الشرط»","url":""}]},{"id":"s42-185","number":185,"surah":42,"verses":[33,34],"references":[{"surah":42,"verses":[33,34]}],"verseLabel":"الشورى: 33–34","question":"لماذا أُسند الإهلاك إلى السفن في قوله ﴿يوبقهن﴾ مع أن الهلاك يقع على ركابها؟","answer":"لأن السفن أقيمت مقام أهلها بالمجاز، فكأنها كائنات حية يصيبها الهلاك بسبب أفعال راكبيها. وهذا التجسيد يشدد صورة الخطر ويجعل مصير السفينة وركابها مشهدًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص293، تحت عنوان «بلاغة التعبير بالمجاز العقلي في ﴿يوبقهن﴾»","url":""}]},{"id":"s42-92","number":92,"surah":42,"verses":[30,34],"references":[{"surah":42,"verses":[30,34]}],"verseLabel":"الشورى: 30، 34","question":"ماذا يكشف قوله ﴿وَيَعْفُ عَنْ كَثِيرٍ﴾ بعد تهديد السفن بالإهلاك؟","answer":"يكشف أن القدرة التي تملك إغراق السفن تقترن بالعفو؛ فقد يهلك الله قومًا، وقد ينجي كثيرًا ممن استحقوا الهلاك، فتكون نجاتهم تجاوزًا ورحمة لا عجزًا عن مؤاخذتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص295، تحت عنوان «دلالة العطف في قوله ﴿ويعف﴾»","url":""}]},{"id":"s42-93","number":93,"surah":42,"verses":[35],"references":[{"surah":42,"verses":[35]}],"verseLabel":"الشورى: 35","question":"لماذا انتقل السياق من آيات البحر إلى الحديث عن المجادلين في آيات الله؟","answer":"لأن تسخير البحر وجريان السفن وركودها أو غرقها دلائل مشاهدة على القدرة؛ فمن يجادل بعد هذا البيان لا يطلب الحجة بل ينازع في آيات ظاهرة. فجاء الانتقال ليكشف عناده ويهدده بعاقبة المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص300، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s42-186","number":186,"surah":42,"verses":[35],"references":[{"surah":42,"verses":[35]}],"verseLabel":"الشورى: 35","question":"ماذا يضيف ختام الآية بقوله ﴿ما لهم من محيص﴾؟","answer":"يذيّل تهديد المجادلين بنفي أي موضع يهربون إليه من لقاء الله وعذابه. فكما لا يملك ركاب السفن الخروج من سلطان البحر حين يحيط بهم الخطر، لا يملك المعاندون الإفلات من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص305، تحت عنوان «بلاغة التذييل بقوله ﴿ما لهم من محيص﴾»","url":""}]},{"id":"s42-94","number":94,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"ما دلالة وصف ما أوتيه الناس بأنه ﴿متاع الحياة الدنيا﴾؟","answer":"المتاع ما ينتفع به زمنًا ثم ينقضي، وإضافته إلى الحياة الدنيا تؤكد فناءه وقلة بقائه. فالتعبير يضع العطايا الدنيوية في قدرها، ويهيئ للموازنة بينها وبين الخير الباقي عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص310–311، تحت عنوان «سر التعبير بالمتاع، والغرض من إضافته للدنيا في ﴿فمتاع الحياة الدنيا﴾»","url":""}]},{"id":"s42-95","number":95,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"ما دلالة الجمع بين ﴿خير﴾ و﴿أبقى﴾ في وصف ما عند الله؟","answer":"الخير يقرر تفوق ما عند الله في نفعه وجودته، والأبقى يقرر دوامه وعدم انقطاعه. فجمع الوصفان كمال النعمة وبقاءها، في مقابل متاع الدنيا الذي يشوبه النقص ويعتريه الزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص313، تحت عنوان «دلالة التعبير بـ(أفعل) التفضيل في ﴿خير وأبقى﴾»","url":""}]},{"id":"s42-96","number":96,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"لماذا خُص ما عند الله بالذين آمنوا؟","answer":"لأن التعبير بالموصول يجعل الإيمان صفةً كاشفة عن سبب استحقاق الوعد؛ فما عند الله خير دائم لمن صدق به وعمل بمقتضى إيمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص314، تحت عنوان «الغرض من التعبير باسم الموصول وصلته ﴿للذين آمنوا﴾»","url":""}]},{"id":"s42-203","number":203,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"ماذا يفيد تقديم ﴿عَلَى رَبِّهِمْ﴾ في وصف المتوكلين؟","answer":"يفيد اختصاص اعتمادهم بربهم؛ فهم لا يجعلون اتكال القلب على الأسباب أو الخلق، بل يرجعون في شؤونهم إليه وحده مع فعل ما يستطيعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص316، تحت عنوان «الغرض من تقديم ﴿على ربهم﴾ على الفعل ﴿يتوكلون﴾»","url":""}]},{"id":"s42-97","number":97,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"ما سر اختيار الاجتناب دون الترك في قوله ﴿يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ﴾؟","answer":"الاجتناب جعل الشيء في جانب بعيد، فهو يصور شدة المباعدة عن الإثم، لا مجرد تركه مع البقاء قريبًا من دواعيه. وصيغة الفعل تدل على مجاهدة المؤمنين أنفسهم ليستمروا على هذه المباعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص323، تحت عنوان «دلالة التعبير بالفعل ﴿يجتنبون﴾ مادة وصيغة»","url":""}]},{"id":"s42-98","number":98,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"هل تدل عبارة ﴿كَبَائِرَ الْإِثْمِ﴾ على أن الذنوب درجة واحدة؟","answer":"لا؛ فالإثم اسم عام يدخل فيه الصغير والكبير، وإضافة ﴿كَبَائِرَ﴾ إليه تكشف أن الذنوب متفاوتة الدرجات. لذلك تركز صفة المدح هنا على اجتناب العظائم، وفي هذا التفريق أثر من رحمة الله بعباده من غير أن يكون ترخيصًا في الصغائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص324، تحت عنوان «الغرض من إضافة ﴿كبائر﴾ إلى ﴿الإثم﴾»","url":""}]},{"id":"s42-187","number":187,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"لماذا خُصَّت ﴿الْفَوَاحِشَ﴾ بالذكر بعد ﴿كَبَائِرَ الْإِثْمِ﴾ مع أنها منها؟","answer":"عطف الفواحش من تخصيص الخاص بعد العام؛ فهي داخلة في كبائر الإثم، لكن إفرادها بالذكر ينبه إلى بلوغها الغاية في القبح والخطر، ويؤكد شدة العناية باجتنابها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص324–325، تحت عنوان «دلالة العطف في ﴿والفواحش﴾»","url":""}]},{"id":"s42-99","number":99,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"كيف يصوّر المضارع ﴿يَغْفِرُونَ﴾ تعامل المؤمنين مع الغضب؟","answer":"يصوّر المغفرة سجيّة تتجدد منهم كلما تجدد الغضب؛ فلا يكون الصفح موقفًا عابرًا وقع مرة، بل خلقًا مستمرًا مع القدرة على الرد. ويقابل ذلك مجيء الغضب بالماضي، كأنه عارض سريع الزوال بينما يبقى العفو هو الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص327–328، تحت عنوان «دلالة التعبير بالمضارع ﴿يغفرون﴾»","url":""}]},{"id":"s42-100","number":100,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"لماذا جاء الإنفاق بعد الاستجابة والصلاة والشورى في صفات المؤمنين؟","answer":"لأن الإنفاق صورة عملية من الاستجابة لله، وفي مجيئه بعد الشورى اكتمال لتعاون الجماعة: يبذلون خبرة عقولهم بالمشاورة، ويبذلون فضل أموالهم بالمواساة. وهكذا تجتمع العبادة والرأي والمال في بناء جماعة متآلفة كالجسد الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص339–340، تحت عنوان «بلاغة عطف قوله ﴿ومما رزقناهم ينفقون﴾ على ما سبق»","url":""}]},{"id":"s42-101","number":101,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"لماذا قيل ﴿وَأَمْرُهُمْ شُورَى﴾ ولم يقل: «يتشاورون»؟","answer":"الإخبار بالمصدر مبالغة في تمكن هذا الخلق منهم؛ فكأن أمرهم المشترك هو الشورى نفسها، لا مجرد فعل يقع أحيانًا. وفيه إشعار بأن تشاورهم عظيم صادق، تحمله النصيحة وصفاء القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص337، تحت عنوان «دلالة التعبير بالمصدر ﴿شورى﴾ دون غيره»","url":""}]},{"id":"s42-188","number":188,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"ماذا تضيف الجملة الاسمية ﴿وَأَمْرُهُمْ شُورَى بَيْنَهُمْ﴾ إلى وصف المؤمنين؟","answer":"تجعل الشورى شأنًا ثابتًا مستقرًا في جماعتهم، لا تصرفًا عارضًا ينفك عنهم عند تغير الظروف. ولذلك عدل السياق إليها بين جمل فعلية ليلفت إلى رسوخ هذا الخلق وعظيم العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص338، تحت عنوان «دلالة التعبير بالجملة الاسمية ﴿وأمرهم شورى بينهم﴾»","url":""}]},{"id":"s42-102","number":102,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"ما سر توسط الشورى بين الصلاة والإنفاق؟","answer":"توسط الشورى يبرز أثرها في انتظام أمر الجماعة واجتماعها على ما يحقق الخير. فهي مع الصلاة والإنفاق من الخصال التي تقيم المجتمع على طاعة الله والتعاون، وتشير إلى العناية بالشأن المشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص336، تحت عنوان «دلالة توسط أمر الشورى بين إقامة الصلاة والإنفاق»","url":""}]},{"id":"s42-103","number":103,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"لماذا لم يُذكر في ماذا ينفق المؤمنون؟","answer":"ليعم الإنفاق كل وجه مشروع نافع، من سد حاجة الفقير إلى مصالح الجماعة وسائر أبواب البر، فلا يحصره اللفظ في مصرف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص342، تحت عنوان «الغرض من حذف متعلق الإنفاق»","url":""}]},{"id":"s42-104","number":104,"surah":42,"verses":[37,39],"references":[{"surah":42,"verses":[37,39]}],"verseLabel":"الشورى: 37، 39","question":"لماذا خُصَّ الغضب بالذكر عند مدح المؤمنين بالمغفرة؟","answer":"لأن الغضب من أشد دوافع الثأر والانتقام، والسيطرة عليه صعبة؛ فإذا عفا المؤمن في تلك اللحظة ظهر كمال إيمانه وقوة إرادته وابتعاده عن أخلاق الجاهلية. ففضل المغفرة يتجلى أوضح ما يكون حين يشتد باعث الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص328، تحت عنوان «سر تخصيص الغضب بالغفران»","url":""}]},{"id":"s42-189","number":189,"surah":42,"verses":[37,39],"references":[{"surah":42,"verses":[37,39]}],"verseLabel":"الشورى: 37، 39","question":"كيف يجتمع مدح المؤمنين بالعفو عند الغضب ومدحهم بالانتصار عند البغي؟","answer":"يختلف الحكم باختلاف أثر الموقف: يُمدح العفو حين يسكن الفتنة ويرد الجاني عن جنايته، ويُمدح الانتصار المنضبط حين يشجّع العفو الظالم على مزيد من البغي. فالقرآن يجمع بين تهذيب النفس وحماية الحقوق، ولا يجعل الصفح ذلًا ولا الانتصار تشفيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص347–348، تحت عنوان «دفع توهم معارضة هذه الآية لقوله ﴿وإذا ما غضبوا هم يغفرون﴾»","url":""}]},{"id":"s42-105","number":105,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"ما سر تسمية عقوبة السيئة ﴿سَيِّئَةٌ﴾ في قوله ﴿جَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾؟","answer":"سميت العقوبة سيئة لمشاكلتها الإساءة الأولى في اللفظ والصورة، ولأنها تسوء من تقع عليه، مع أن الجزاء العادل غير مذموم. فالتسمية لا تسوي الحكم الأخلاقي بين العدوان وعقوبته المشروعة، بل تراعي المناسبة بين الفعل وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص353–354، تحت عنوان «بلاغة التعبير بالمشاكلة في ﴿وجزاء سيئة سيئة مثلها﴾»","url":""}]},{"id":"s42-106","number":106,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"ما دلالة تقييد جزاء السيئة بالمماثلة قبل فتح باب العفو والإصلاح؟","answer":"المماثلة تمنع أن يتحول استيفاء الحق إلى عدوان زائد، فتضبط الانتصار بالعدل. ثم ينتقل النظم إلى العفو والإصلاح ترغيبًا في مرتبة الإحسان إذا تحققت بها المصلحة، مع بقاء حق الجزاء في حدوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص354، تحت عنوان «بلاغة التقييد في قوله ﴿وجزاء سيئة سيئة مثلها﴾»","url":""}]},{"id":"s42-107","number":107,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"لماذا لم يبيّن القرآن مقدار أجر من عفا وأصلح؟","answer":"إبهام الأجر يعظمه؛ فهو وعد من الله الكريم بأجر يخرج عن المقادير المألوفة ولا يحيط بكنهه أحد. لذلك كان تركه بلا رقم أبلغ في الرجاء والترغيب في العفو الذي يحقق الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص359، تحت عنوان «دلالة الإبهام في عدم تعيين الأجر في قوله ﴿فأجره على الله﴾»","url":""}]},{"id":"s42-108","number":108,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"لماذا خُتمت أحكام الانتصار والعفو بقوله ﴿إِنَّهُ لَا يُحِبُّ الظَّالِمِينَ﴾؟","answer":"ليظل حق الانتصار منضبطًا بالعدل؛ فالمعتدى عليه لا يملك أن يزيد على حقه فيتحول هو إلى ظالم. والختام قاعدة عامة تذم الباغي، وتحذر المنتصر من تجاوز المماثلة، وتؤكد في الوقت نفسه فضل العفو والإصلاح حين يكونان في موضعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص362، تحت عنوان «بلاغة التذييل بجملة ﴿إنه لا يحب الظالمين﴾»","url":""}]},{"id":"s42-109","number":109,"surah":42,"verses":[40,41],"references":[{"surah":42,"verses":[40,41]}],"verseLabel":"الشورى: 40–41","question":"لماذا سُمِّيت معاقبة الظالم انتصارًا للمظلوم؟","answer":"لأن ردع الظالم المفسد عن التمادي في عدوانه نصر للمظلوم وللمجتمع، ولأن المظلوم يتحرى باستيفاء حقه الجزاء العادل؛ فاللفظ يصوّر طلب الحق لا التشفي المفتوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص368، تحت عنوان «دلالة التعبير بـ﴿انتصر﴾ مادة وصيغة»","url":""}]},{"id":"s42-190","number":190,"surah":42,"verses":[40,41],"references":[{"surah":42,"verses":[40,41]}],"verseLabel":"الشورى: 40–41","question":"لماذا قُيِّد انتصار المظلوم بأنه يكون ﴿بَعْدَ ظُلْمِهِ﴾؟","answer":"لأن استيفاء الحق لا يبدأ إلا بعد وقوع ظلم محقق؛ أما مجرد نية الاعتداء قبل أن يصدر من صاحبها قول أو فعل فلا تُقابل بعدوان مماثل، وإنما يُردع صاحبها بالوسيلة المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص368، تحت عنوان «سر التقييد بالظرفية ﴿بعد﴾»","url":""}]},{"id":"s42-110","number":110,"surah":42,"verses":[41,42],"references":[{"surah":42,"verses":[41,42]}],"verseLabel":"الشورى: 41–42","question":"لماذا عُبّر عن المؤاخذة بلفظ ﴿السَّبِيلُ﴾؟","answer":"صُورت المؤاخذة طريقًا واضحًا تسلكه الحجة إلى مستحقها؛ فلا طريق للوم المظلوم المنتصر في حد حقه، وإنما يقوم الطريق على المعتدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص370، تحت عنوان «سر التعبير بلفظ ﴿سبيل﴾ وبلاغة المجاز فيه»","url":""}]},{"id":"s42-204","number":204,"surah":42,"verses":[41,42],"references":[{"surah":42,"verses":[41,42]}],"verseLabel":"الشورى: 41–42","question":"ماذا يفيد قصر السبيل على الذين يظلمون الناس؟","answer":"يحصر اللوم والعقوبة في المعتدين الذين يبغون بغير حق، فيبرئ المظلوم الذي استوفى حقه من المؤاخذة ويحدد موضع الإدانة بدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص371، تحت عنوان «الغرض من التعبير بأسلوب القصر بـ﴿إنما﴾»","url":""}]},{"id":"s42-111","number":111,"surah":42,"verses":[42],"references":[{"surah":42,"verses":[42]}],"verseLabel":"الشورى: 42","question":"لماذا قيل إنهم ﴿يَبْغُونَ فِي الْأَرْضِ﴾ ولم يقل: في الدنيا؟","answer":"لأن لفظ الأرض يستحضر الموطن الذي استخلف الله الناس لإعماره وإصلاحه، فيبدو بغيهم نقضًا للأمانة وإفسادًا للمكان المشترك بعد إصلاحه؛ كما يعمم الذم كل بغي يقع في أي جزء منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص374، تحت عنوان «سر تقييد البغي بلفظ ﴿في الأرض﴾ دون الدنيا»","url":""}]},{"id":"s42-112","number":112,"surah":42,"verses":[41,42,43],"references":[{"surah":42,"verses":[41,42,43]}],"verseLabel":"الشورى: 41–43","question":"ما سر العودة إلى مدح الصبر والمغفرة بعد تقرير جواز الانتصار؟","answer":"بعد تقرير حق الانتصار يرجع السياق إلى الترغيب في الصبر والعفو، حتى يجتمع حفظ الحق مع تهذيب النفس. فليس المقصود إبطال الانتصار المشروع، بل بيان فضل المسامحة في الموضع الذي يصلح له العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص377، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s42-113","number":113,"surah":42,"verses":[43],"references":[{"surah":42,"verses":[43]}],"verseLabel":"الشورى: 43","question":"هل يكفي أن يصبر المظلوم عن الرد من غير أن يغفر؟","answer":"قد يصبر الإنسان على الإساءة ويؤخر الانتصار لنفسه، لكن يبقى أثرها في قلبه؛ لذلك عُطفت المغفرة على الصبر لتجمع الآية بين احتمال الأذى وصفح النفس عن المسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص380، تحت عنوان «دلالة عطف المغفرة على الصبر في ﴿صبر وغفر﴾»","url":""}]},{"id":"s42-191","number":191,"surah":42,"verses":[43],"references":[{"surah":42,"verses":[43]}],"verseLabel":"الشورى: 43","question":"لماذا قُدِّم الصبر على المغفرة في قوله ﴿صَبَرَ وَغَفَرَ﴾؟","answer":"لأن الصبر هو الأساس الذي يحمل صاحبه على كف الانتقام، ولأن العفو المحمود ما صدر عن قدرة واحتمال لا عن عجز؛ فالتقديم يميز الصفح الأخلاقي من مجرد عدم القدرة على الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص380، تحت عنوان «غرض تقديم الصبر على المغفرة»","url":""}]},{"id":"s42-114","number":114,"surah":42,"verses":[43],"references":[{"surah":42,"verses":[43]}],"verseLabel":"الشورى: 43","question":"ما سر التعبير عن الصبر والمغفرة بأنهما ﴿لَمِنْ عَزْمِ الْأُمُورِ﴾؟","answer":"اختير العزم لما يدل عليه من قوة وثبات ونفاذ؛ لأن الصبر على المكروه والعفو عمن أساء مع القدرة على الرد يحتاجان إلى قوة إرادة وثبات يصدران عن روية وإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص382، تحت عنوان «سر اختيار التعبير بلفظ ﴿عزم﴾»","url":""}]},{"id":"s42-115","number":115,"surah":42,"verses":[44],"references":[{"surah":42,"verses":[44]}],"verseLabel":"الشورى: 44","question":"كيف يحوّل المضارع في ﴿وَتَرَى الظَّالِمِينَ﴾ مصيرهم إلى مشهد حاضر؟","answer":"يستحضر رؤيتهم يوم القيامة كأنها تقع أمام المخاطب الآن، فيشاهد ذلهم وندامتهم بدل أن يسمع خبرًا بعيدًا؛ فتشتد العبرة والتحذير من الطريق الذي أوصلهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص390، تحت عنوان «دلالة التعبير بالمضارع ﴿وترى﴾»","url":""}]},{"id":"s42-116","number":116,"surah":42,"verses":[44],"references":[{"surah":42,"verses":[44]}],"verseLabel":"الشورى: 44","question":"ماذا يكشف سؤال الظالمين ﴿هَلْ إِلَى مَرَدٍّ مِنْ سَبِيلٍ﴾ عند رؤية العذاب؟","answer":"يكشف لهفتهم على فرصة فاتت؛ فالاستفهام تمنٍّ للرجوع إلى زمن العمل واستغاثة لطلب أي خلاص بعد معاينة العذاب، لا سؤال من يملك طريقًا حقيقيًا للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص393، تحت عنوان «الغرض من التعبير بالاستفهام في ﴿هل إلى مرد﴾»","url":""}]},{"id":"s42-192","number":192,"surah":42,"verses":[44],"references":[{"surah":42,"verses":[44]}],"verseLabel":"الشورى: 44","question":"لماذا لم يُذكر إلى أين يريد الظالمون الرجوع في ﴿هَلْ إِلَى مَرَدٍّ مِنْ سَبِيلٍ﴾؟","answer":"لأن المقام يكشف مرادهم: الرجوع إلى الدنيا قبل فوات العمل، أو الخروج من العذاب؛ وحذف الجهة يوسّع الحسرة، فكأنهم يطلبون أي مردّ وأي منفذ مهما كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص393، تحت عنوان «دلالة عدم ذكر محل المرد في الآية»","url":""}]},{"id":"s42-117","number":117,"surah":42,"verses":[45],"references":[{"surah":42,"verses":[45]}],"verseLabel":"الشورى: 45","question":"لماذا وُصف الظالمون بالخشوع عند عرضهم على النار؟","answer":"لأن الخشوع يُظهر على الجوارح أثر الانكسار والمهانة؛ فتبدو أجسامهم خاضعة ذليلة بعد استكبارهم في الدنيا، ويصير الجزاء صورة مقابلة لما كانوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص402، تحت عنوان «سر التعبير بالخشوع»","url":""}]},{"id":"s42-193","number":193,"surah":42,"verses":[45],"references":[{"surah":42,"verses":[45]}],"verseLabel":"الشورى: 45","question":"ما الذي تصوّره نظراتهم ﴿مِنْ طَرْفٍ خَفِيٍّ﴾؟","answer":"تصوّر نظرات ضعيفة مسروقة؛ يريدون رؤية ما يخافونه ولا يطيقون التحديق فيه، فينظرون من جانب وعلى استحياء وخوف، فتجتمع في حركتهم المهانة والرعب وانكسار النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص406، تحت عنوان «بلاغة التعبير بجملة ﴿ينظرون من طرف خفي﴾»","url":""}]},{"id":"s42-118","number":118,"surah":42,"verses":[45],"references":[{"surah":42,"verses":[45]}],"verseLabel":"الشورى: 45","question":"كيف يخسر الإنسان يوم القيامة نفسه وأهله معًا؟","answer":"يخسر نفسه باستحقاق العذاب، ويفقد الانتفاع بأهله: فإن كانوا معه في النار لم يغنوا عنه، وإن كانوا من أهل الجنة حيل بينه وبينهم؛ وقد تمتد الخسارة إلى أنه أورث أهله الضلال فصار سبب شقائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص411، تحت عنوان «سر التعبير بخسران الأنفس والأهل»","url":""}]},{"id":"s42-120","number":120,"surah":42,"verses":[44,46],"references":[{"surah":42,"verses":[44,46]}],"verseLabel":"الشورى: 44، 46","question":"ما سر تكرار ﴿وَمَنْ يُضْلِلِ اللَّهُ﴾ ثم اختلاف الجواب بين ﴿فَمَا لَهُ مِنْ وَلِيٍّ مِنْ بَعْدِهِ﴾ و﴿فَمَا لَهُ مِنْ سَبِيلٍ﴾؟","answer":"ينفي الموضع الأول الولي الذي يتولى من ضل، ثم يصور حاله عند العذاب. ويأتي الموضع الثاني بعد تمام المشهد لينفي سبيل الخلاص نفسه. فاختلاف الجواب يوافق موقع كل جملة: أولاهما تفتتح بيان الخذلان، والأخرى تغلق طرق النجاة بعد عرض عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص423–424، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s42-121","number":121,"surah":42,"verses":[46],"references":[{"surah":42,"verses":[46]}],"verseLabel":"الشورى: 46","question":"كيف يجمع ختام الآية بين فقد الناصر وانسداد كل طريق للخلاص؟","answer":"نفت الآية أولًا أن يكون لهم أولياء ينصرونهم، ثم عممت بنفي أي سبيل؛ فالولي واحد من سبل الخلاص، ونفي السبيل يضم إليه كل طريق آخر يمكن أن يتوهموه للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص423، تحت عنوان «بلاغة التذييل في جملة الفاصلة»","url":""}]},{"id":"s42-122","number":122,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"لماذا قيل ﴿اسْتَجِيبُوا لِرَبِّكُمْ﴾ باسم الربوبية؟","answer":"ليذكّرهم بأن الداعي هو الذي رباهم ورعاهم وأنعم عليهم، فتجتمع رهبة الأمر مع باعث المحبة والشكر والرجوع إلى المحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص429–430، تحت عنوان «سر إيثار لفظ الربوبية ﴿ربكم﴾ دون لفظ الجلالة»","url":""}]},{"id":"s42-123","number":123,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"كيف يجعل المضارع في ﴿أَنْ يَأْتِيَ يَوْمٌ﴾ القيامةَ حاضرةً في النفس قبل وقوعها؟","answer":"يدل المضارع على أن إتيان اليوم مستقبل، لكنه يدعو السامع في الوقت نفسه إلى استحضار مشاهده كأنها ماثلة أمامه؛ فيتحول الخبر عن الغيب إلى واعظ حي يحث على الاستجابة قبل فوات الأوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص431، تحت عنوان «نكتة صيغة المضارع في ﴿يأتي﴾»","url":""}]},{"id":"s42-194","number":194,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"لماذا جُعل يوم القيامة نفسه ﴿لَا مَرَدَّ لَهُ﴾ مع أن الناس هم العاجزون عن رده؟","answer":"أُسند عدم الرد إلى اليوم مبالغةً في تهويله؛ فكأن حتميته صفة قائمة به لا يستطيع أحد تغييرها. وتزيد هذه الصورة ضغط الإنذار على الظالمين ليرجعوا إلى الإيمان قبل مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص432، تحت عنوان «سر نسبة الرد إلى اليوم»","url":""}]},{"id":"s42-124","number":124,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"ماذا أضاف قوله ﴿وَمَا لَكُمْ مِنْ نَكِيرٍ﴾ بعد نفي كل ملجأ يوم القيامة؟","answer":"أضاف أنهم لا يملكون إنكار العذاب ولا حجة تدفعه، كما لا يملكون مكانًا أو عاصمًا يهربون إليه؛ فاجتمع انتفاء العاصم وانتفاء الحجة، وبلغ إفلاسهم غايته، ليبقى طريق النجاة قبل ذلك اليوم هو الاستجابة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص435، تحت عنوان «بلاغة عطف ﴿وما لكم من نكير﴾»","url":""}]},{"id":"s42-125","number":125,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"ما سر مقابلة نفي كون الرسول ﷺ حفيظًا على المعرضين بقصر مهمته على البلاغ؟","answer":"الحفظ المنفي يتناول مراقبة أعمالهم وإحصاءها وإجبارهم على الإيمان، وهي أمور لا تقتضيها وظيفة البلاغ. والقصر يقرر أن عليه إيصال الرسالة؛ أما حسابهم وتوفيقهم فإلى الله، وفي ذلك تسلية له عن إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص444–445، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s42-126","number":126,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"لماذا وصف تعلق الإنسان بالنعمة بـ﴿فَرِحَ بِهَا﴾ ولم يقل: بطر بها؟","answer":"لأن الفرح أعم من البطر: قد يكون محمودًا أو مذمومًا، وهو يكشف أصل تعلق النفس بالنعم؛ أما البطر فهو إساءة استعمال النعمة ولا يكون إلا مذمومًا. وفي السياق تجاوز الفرح حد السرور إلى التعلق المتجبر، فظهر الذم من المقام لا من أصل اللفظ وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص451، تحت عنوان «نكتة التعبير بالفرح دون البطر»","url":""}]},{"id":"s42-127","number":127,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"لماذا أُعيد اسم ﴿الْإِنْسَانَ﴾ ظاهرًا في قوله ﴿فَإِنَّ الْإِنْسَانَ كَفُورٌ﴾؟","answer":"لتسجيل كفران النعمة على جنس الإنسان حين تستحكم فيه هذه الطبيعة، والتنبيه إلى أن الفرح بالنعمة ثم نسيان المنعم خلق بشري متكرر، لا حادثة عارضة لفرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص457–458، تحت عنوان «سر إظهار لفظ الإنسان»","url":""}]},{"id":"s42-128","number":128,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"لماذا وُصف الإنسان بالكفران عند إصابته بسيئة سببها عمله؟","answer":"لأن ما يصيبه قليل من كثير مما كسب، ولم يؤاخذه الله بكل ما قدمت يداه؛ فكان حقه أن يرى العفو الواسع فيشكر، لكنه يستعظم البلاء وينسى سببه وما بقي له من النعم، فيظهر كفرانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص456، تحت عنوان «سر ذكر هذه الفاصلة مع إصابة السيئة»","url":""}]},{"id":"s42-195","number":195,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"كيف كشفت الآية ما حُذف من حال الإنسان في النعمة والشدة؟","answer":"ذكرت فرحه عند الرحمة، فدل مقابله على حزنٍ محذوف عند السيئة؛ وذكرت كفرانه عند السيئة، فدل مقابله على شكرٍ غائب عند الرحمة. بهذا الاحتباك حذرت من بطر الرخاء وجزع الشدة معًا، وأبرزت ما ينبغي ألا يقع من الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص458، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s42-129","number":129,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"لماذا انتقل السياق من تقلب الإنسان بين الفرح والكفران إلى قوله ﴿لِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"لأن تقلب الإنسان يثير سؤالًا عن سر اختلاف أحواله، فجاء الجواب بأن الله وحده مالك الكون والمتصرف في الخلق والأحوال. ثم عُرض تنوع الذرية مثالًا محسوسًا لمشيئته: يهب هذا، ويجمع ذاك، ويمنع آخر بحكمة وقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص460–461، تحت عنوان «علة فصل ﴿لله ملك السماوات والأرض﴾»","url":""}]},{"id":"s42-130","number":130,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"لماذا كررت الآية ﴿يَهَبُ﴾ و﴿لِمَنْ يَشَاءُ﴾ مع الإناث والذكور بدل أن تجمعهما في عبارة واحدة؟","answer":"ليفرد كل هبة بالعناية ويؤكد استقلالها بمشيئة الله، فلا يُجعل أحد الصنفين تابعًا للآخر. وفي التكرار تقرير أن الإناث والذكور عطيتان متساويتان في أصل الهبة، تستحق كل منهما الشكر ولا يليق الانتقاص من شأن الإناث.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص467، تحت عنوان «بلاغة تكرار الهبة والمشيئة»","url":""}]},{"id":"s42-131","number":131,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"ما سر تقديم هبة الإناث على هبة الذكور؟","answer":"تذكر الموسوعة أن تقديم الإناث يلائم بيان أن الهبة بمشيئة الله، لا وفق ما يتخير الناس لأنفسهم؛ فقد كانوا يفضلون الذكور. وتذكر فيه أيضًا جبر خواطر من تلحقهم الوحشة بسبب كراهة الجاهلية للإناث، فقدم ذكرهن في مقام العطية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص466–467، تحت عنوان «سر تقديم (الإناث) على ﴿الذكور﴾»","url":""}]},{"id":"s42-132","number":132,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"ما دلالة تنكير ﴿إِنَاثًا﴾ وتعريف ﴿الذُّكُورَ﴾؟","answer":"الأصل في اسمي الجنس هنا التنكير، فبقيت ﴿إناثًا﴾ عليه. أما تعريف الذكور فوجهته الموسوعة بالعهد إلى الجنس المعروف في رغبتهم؛ أي الذكور الذين يتطلعون إليهم. وفي جمعهما تحت الهبة بيان أن كليهما عطية من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص466، تحت عنوان «سر تنكير (الإناث) وتعريف ﴿الذكور﴾»","url":""}]},{"id":"s42-133","number":133,"surah":42,"verses":[49,50],"references":[{"surah":42,"verses":[49,50]}],"verseLabel":"الشورى: 49–50","question":"لماذا قُدِّم الذكران على الإناث حين جمعهما في قوله ﴿ذُكْرَانًا وَإِنَاثًا﴾؟","answer":"لأن سبب تقديم الإناث في الهبة المنفردة—مخالفة اختيار الجاهلية وجبر خاطر من يكرههن—لم يعد قائمًا عند جمع الصنفين معًا. فعاد الترتيب هنا إلى ما يوافق مواضع خلق الزوجين في القرآن، مع بقاء الصنفين كليهما داخل العطية الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص469، تحت عنوان «سر تقديم الذكران على الإناث»","url":""}]},{"id":"s42-134","number":134,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"لماذا قيل فيمن رُزق بنين وبنات ﴿يُزَوِّجُهُمْ﴾ بدل أن يقال: يهبهم؟","answer":"لأن التزويج هنا هو قرن أحد الصنفين بالآخر؛ فكل شيئين اقترن أحدهما بصاحبه زوجان. لذلك ناسب حال من جُمعت له هبة البنين والبنات، بعد أن استُعملت الهبة لكل صنف حين ذُكر منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص468، تحت عنوان «نكتة التعبير بالتزويج دون الهبة»","url":""}]},{"id":"s42-196","number":196,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"ما الرحمة التي يفتحها قوله ﴿وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا﴾ بدل «ويخلق عقيمًا»؟","answer":"يفرق الجعل بين أصل خلق الإنسان وبين الحالة التي يُصيَّر إليها؛ فقد يكون العقم طورًا أو وصفًا يتغير، لا حقيقة ملازمة منذ الخلق. كما يوجه اللفظ إلى حكمة الله في هذه الحال، فلا تُفهم على أنها عقوبة، وفي ذلك تطييب لخاطر من ابتلي بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص470–471، تحت عنوان «سر التعبير بالجعل دون الخلق مادة وصيغة»","url":""}]},{"id":"s42-197","number":197,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"كيف استوعبت الآيتان جميع أحوال الناس في الذرية؟","answer":"جاء التقسيم حاصرًا لا يترك صورة: إناث وحدهن، أو ذكور وحدهم، أو الصنفان معًا، أو عدم الولد. فجمع العطاء والمنع في أربعة أقسام تكشف شمول المشيئة الإلهية لكل أحوال الإنجاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص473، تحت عنوان «بلاغة التقسيم في الآيتين»","url":""}]},{"id":"s42-135","number":135,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"لماذا خُتم تقسيم أحوال الذرية بقوله ﴿إِنَّهُ عَلِيمٌ قَدِيرٌ﴾؟","answer":"لأن اختلاف العطاء والمنع لا يقع عبثًا، بل يصدر عن علم بمن تصلح له كل حال وقدرة على إنفاذها؛ فيدعو الموهوب إلى الشكر، ويعين المحروم على الرضا بحكم العليم القدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص474، تحت عنوان «وجه إيثار صفتي العلم والقدرة»","url":""}]},{"id":"s42-198","number":198,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"لماذا قُدِّم ﴿عَلِيمٌ﴾ على ﴿قَدِيرٌ﴾ بعد ذكر هبة الأولاد والعقم؟","answer":"لأن العلم أساس التصرف المحكم؛ فالله يعلم من يستحق كل صورة من العطاء والمنع، ثم تنفذ قدرته ما اقتضاه ذلك العلم. فجاء ترتيب الاسمين موافقًا لترتيب المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص474، تحت عنوان «غرض تقديم العليم على القدير»","url":""}]},{"id":"s42-136","number":136,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"ما دلالة تنكير ﴿بشر﴾ في قوله ﴿وما كان لبشر أن يكلمه الله﴾؟","answer":"جاء ﴿بشر﴾ نكرة في سياق النفي ليعم الحكم جنس البشر؛ فلا يختص بيان كيفية التكليم بفرد دون آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص478، تحت عنوان «دلالة تنكير ﴿لبشر﴾»","url":""}]},{"id":"s42-137","number":137,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"كيف يقع تكليم الله للبشر في الصور الثلاث التي ذكرتها الآية؟","answer":"إما أن يلقي الله المعنى في القلب يقظة أو منامًا، وإما أن يُسمع كلامه من وراء حجاب دون رؤية المتكلم كما وقع لموسى، وإما أن يرسل ملكًا يبلغ ما شاء. فالمراد واحد، وتختلف وسيلة وصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص477، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s42-138","number":138,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"لماذا سمّت الآية صور تكليم الله للبشر كلَّها ﴿وَحْيًا﴾؟","answer":"لأن الوحي لفظ جامع لكل تكليم من الله للإنسان، أيًّا كان طريقه، ولأنه يدل أصلًا على إلقاء العلم في خفاء؛ فجمع اللفظ شمول صور التكليم مع إبراز الصفة المشتركة بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص479–480، تحت عنوان «بلاغة التعبير بالوحي»","url":""}]},{"id":"s42-139","number":139,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"لماذا خُتم بيان طرق الوحي بوصف الله بأنه ﴿عَلِيٌّ حَكِيمٌ﴾؟","answer":"لأن علوه ينزهه عن أن يكون تكليمه كتكليم البشر، وحكمته تقتضي أن يختار لكل رسول صورة الوحي التي تلائم حاله وطاقته؛ فاجتمع التنزيه مع حسن التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص485، تحت عنوان «وجه إيثار صفتي العلو والحكمة»","url":""}]},{"id":"s42-199","number":199,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"لماذا قُدِّم وصف الله بـ﴿عَلِيٌّ﴾ على ﴿حَكِيمٌ﴾ في ختام آية الوحي؟","answer":"لأن علو الله يهيئ نفوس البشر لتلقي خطابه، ثم تختار حكمته من صور التكليم ما يبلغ مراده على الوجه الأتم الأكمل؛ فجاء ترتيب الاسمين موافقًا لهذا المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص486، تحت عنوان «سر تقديم العلي على الحكيم»","url":""}]},{"id":"s42-140","number":140,"surah":42,"verses":[51,52],"references":[{"surah":42,"verses":[51,52]}],"verseLabel":"الشورى: 51–52","question":"إلى ماذا تشير ﴿كَذَلِكَ﴾ في قوله ﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"تشير إلى صور التكليم المذكورة قبلها، أي أن ما أوحي إلى النبي ﷺ وقع بطريق من تلك الطرق، ولا سيما بواسطة الرسول الملكي؛ فتصل الإشارة الحكم بمثاله الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص492، تحت عنوان «مرجع الإشارة في ﴿وكذلك﴾ ولطيفة إيثار التعبير بها»","url":""}]},{"id":"s42-141","number":141,"surah":42,"verses":[52],"references":[{"surah":42,"verses":[52]}],"verseLabel":"الشورى: 52","question":"لماذا وصف الله القرآن بأنه ﴿رُوحًا﴾؟","answer":"لأنه يحيي القلوب بالإيمان والعلم كما تحيا الأجساد بالروح، وينقل النفوس من موت الجهل والضلال إلى حياة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص494–495، تحت عنوان «حكمة التعبير بلفظ ﴿روحًا﴾»","url":""}]},{"id":"s42-142","number":142,"surah":42,"verses":[52],"references":[{"surah":42,"verses":[52]}],"verseLabel":"الشورى: 52","question":"لماذا عُقِّب تشبيه الوحي بالنور بقوله ﴿نَهْدِي بِهِ﴾؟","answer":"لأن الهداية هي وجه الشبه المقصود ومهمة الوحي الأولى: فكما يكشف النور الطريق المحسوس، يكشف الوحي طريق الحق ويأخذ من شاء الله به إلى السلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص505، تحت عنوان «حكمة التعبير بمفردة الهداية في ﴿نهدي﴾»","url":""}]},{"id":"s42-143","number":143,"surah":42,"verses":[52],"references":[{"surah":1,"verses":[6]},{"surah":42,"verses":[52]}],"verseLabel":"الشورى: 52؛ الفاتحة: 6","question":"كيف تبقى هداية الرسول ﷺ ممتدة بعد وفاته؟","answer":"تبقى بما بلغه من القرآن والسنة؛ فجاء ﴿لَتَهْدِي﴾ مصورًا دوام مهمته في الدعوة إلى الله وتجدد ثمارها، إذ يحمل الوحي وهديه دعوته إلى الناس بعد وفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص512، تحت عنوان «فائدة المضارعة في الفعل ﴿لتهدي﴾»","url":""}]},{"id":"s42-144","number":144,"surah":42,"verses":[52,53],"references":[{"surah":42,"verses":[52,53]}],"verseLabel":"الشورى: 52–53","question":"لماذا جاء ﴿صِرَاطِ اللَّهِ﴾ بعد قوله ﴿صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"ليبين أن الطريق الذي يهدي إليه الرسول ليس طريقًا من عنده، بل هو طريق الله. وإضافته إلى الله تزكي دعوة الرسول وتعظم شأن هذا الصراط المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص515، تحت عنوان «فائدة موقع ﴿صراط الله﴾»","url":""}]},{"id":"s42-145","number":145,"surah":42,"verses":[53],"references":[{"surah":42,"verses":[53]}],"verseLabel":"الشورى: 53","question":"لماذا كان قوله ﴿أَلَا إِلَى اللَّهِ تَصِيرُ الْأُمُورُ﴾ حسن ختام لسورة الشورى؟","answer":"لأن نهاية التلاوة توافق نهاية الأحداث كلها إلى الله؛ وفيها وعد لمن آمن بالوحي وسلك صراطه، ووعيد لمن عانده. فاختتمت السورة بالمصير الذي تنتهي عنده حججها ووعدها ووعيدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص520–521، تحت عنوان «بلاغة التذييل بجملة ﴿ألا إلى الله تصير الأمور﴾»","url":""}]},{"id":"s43-1","number":1,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الزخرف»، مع أن اللفظ لم يرد فيها إلا مرة واحدة؟","answer":"ورد اسم الزخرف في سياق بيان متاع الدنيا، وهو رمز الزينة المادية التي افتتن بها المكذبون. وتسميتها به تلائم نقد هذه الموازين الزائلة، وتوجيه النظر إلى هداية القرآن وحكمته بدل الاغترار بالزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص525–526، تحت عنوان «اسم السورة، ومناسبة تسميتها»","url":""}]},{"id":"s43-2","number":2,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما الخيط الذي يجمع جدل سورة الزخرف وقصصها؟","answer":"يجمعها صراع الوحي مع القيم المادية الموروثة: فقد خاصم المشركون الحق بترفهم وتقليد آبائهم، وردت السورة ميزانهم إلى الإيمان والوحي، ثم عرضت مصائر نماذج سابقة تؤكد هذا الصراع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص526، تحت عنوان «المحور العام للسورة»","url":""}]},{"id":"s43-3","number":3,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما المفارقة العقدية التي تكشفها سورة الزخرف في مجادلة المشركين؟","answer":"تكشف السورة تناقضهم بين الاعتراف بأن الله خالقهم وخالق الموجودات، وبين اتخاذ شركاء عاجزين معه ونسبة البنات إليه. فيكون إقرارهم بالخلق حجة على بطلان شركهم وافترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص527–528، تحت عنوان «موضوعات السورة وخصائصها»","url":""}]},{"id":"s43-4","number":4,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"لماذا جمعت سورة الزخرف بين قصص إبراهيم وموسى وعيسى عليهم السلام؟","answer":"جمعتها لتبطل أصول الانحراف التي واجهتها: تقليد الآباء في قصة إبراهيم، والاغترار بالملك في قصة موسى، والغلو في عيسى؛ فتتساند القصص في تقرير التوحيد وتصحيح ميزان الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص527–528، تحت عنوان «موضوعات السورة ومحاورها»","url":""}]},{"id":"s43-5","number":5,"surah":43,"verses":[1,2],"references":[{"surah":43,"verses":[1,2]}],"verseLabel":"الزخرف: 1–2","question":"ما دلالة القسم بـ﴿الكتاب المبين﴾ في افتتاح سورة الزخرف؟","answer":"القسم تنويه بعظمة القرآن ووضوحه، وقد اتحد المقسم به والمقسم عليه؛ فكأنه بلغ من شرفه أن يشهد لنفسه. ثم يبين أنه قرآن عربي ليعقله المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص533–534، تحت عنوان «بلاغة التناسب في القسم»","url":""}]},{"id":"s43-6","number":6,"surah":43,"verses":[2],"references":[{"surah":43,"verses":[2]}],"verseLabel":"الزخرف: 2","question":"ما سر وصف القرآن بـ﴿الْكِتَابِ الْمُبِينِ﴾ في سورة تعرض شبه المشركين وجدالهم؟","answer":"المبين يوضح الهدى من الضلال والحلال من الحرام، ويكشف ما يحتاج إليه الناس. وفي وصفه بذلك تعريض بالمعاندين من أهل اللسان؛ فهم يدركون وضوح بيانه ومع ذلك يعرضون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص534–535، تحت عنوان «نكتة وصف الكتاب بـ﴿المبين﴾»","url":""}]},{"id":"s43-7","number":7,"surah":43,"verses":[2,3],"references":[{"surah":43,"verses":[2,3]}],"verseLabel":"الزخرف: 2–3","question":"ما دلالة الانتقال من ﴿الْكِتَابِ﴾ إلى ﴿قُرْآنًا عَرَبِيًّا﴾، واختيار ﴿جَعَلْنَاهُ﴾ بدل «أنزلناه»؟","answer":"وصفه بالكتاب يبرز ثبوته وبقاء هدايته، والتعبير بجعله قرآنًا عربيًا يعتني بخصوصية بيانه العربي المقصودة للفهم. وإيثار الجعل على الإنزال أو التسمية ينبه إلى أن هذه الخصوصية مرادة، لا مجرد وصف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص537، تحت عنوان «سر إيثار التعبير بالجعل في ﴿جعلناه قرآنًا﴾»","url":""}]},{"id":"s43-8","number":8,"surah":43,"verses":[3],"references":[{"surah":43,"verses":[3]}],"verseLabel":"الزخرف: 3","question":"ما المسؤولية التي يحملها قوله: ﴿لَعَلَّكُمْ تَعْقِلُونَ﴾ للمخاطبين؟","answer":"يحملهم مسؤولية إعمال عقولهم في القرآن بعد أن جاء بلسانهم واضحًا؛ فبيانه لا يغني عن تدبرهم، ومن أعرض عنه عطّل النعمة التي تتيح له إدراك الحق والانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص539–540، تحت عنوان «نكتة الصياغة في ﴿تعقلون﴾»","url":""}]},{"id":"s43-9","number":9,"surah":43,"verses":[3,4],"references":[{"surah":43,"verses":[3,4]}],"verseLabel":"الزخرف: 3–4","question":"لماذا قُيّد القرآن بأنه ﴿فِي أُمِّ الْكِتَابِ لَدَيْنَا﴾؟","answer":"ليثبت أن هذا القرآن ثابت في أصله المحفوظ عند الله، جامع لحقائق الكتب؛ فيسقط زعم المشركين أنه مختلق، ويظهر كمال تقديره وحفظه وشرف منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص542، تحت عنوان «نكتة التقييد بـ﴿في أم الكتاب لدينا﴾»","url":""}]},{"id":"s43-164","number":164,"surah":43,"verses":[3,4],"references":[{"surah":43,"verses":[3,4]}],"verseLabel":"الزخرف: 3–4","question":"ما سر الجمع بين وصفي القرآن ﴿لَعَلِيٌّ حَكِيمٌ﴾؟","answer":"يجمع الوصفان كمالين متلازمين: فهو بالغ العلو في قدره، بالغ الحكمة في بيانه؛ فلا يكون علوه غموضًا يمنع الانتفاع به، ولا حكمته منزلة بلا رفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص545–546، تحت عنوان «لطيفة الجمع بين ﴿لعلي﴾، و﴿حكيم﴾»","url":""}]},{"id":"s43-10","number":10,"surah":43,"verses":[4],"references":[{"surah":43,"verses":[4]}],"verseLabel":"الزخرف: 4","question":"لماذا عُبّر عن اللوح المحفوظ بـ﴿أُمِّ الْكِتَابِ﴾؟","answer":"لأن الأم أصل ما يتفرع عنها؛ فالتعبير يصور اللوح المحفوظ أصلًا جامعًا للكتب، ويكني عن ثبوت القرآن فيه وسمو مصدره وحفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص543–544، تحت عنوان «بلاغة الاستعارة، وما وراءها من كناية في ﴿أم الكتاب﴾»","url":""}]},{"id":"s43-165","number":165,"surah":43,"verses":[4],"references":[{"surah":43,"verses":[4]}],"verseLabel":"الزخرف: 4","question":"لماذا قُدّم ﴿فِي أُمِّ الْكِتَابِ لَدَيْنَا﴾ على وصف القرآن بالعلو والحكمة؟","answer":"لأن المقام يعتني أولًا بإثبات مصدر القرآن عند الله ونفي الشك فيه؛ فإذا تقرر أصله المحفوظ جاء وصفه بالعلو والحكمة نتيجة تليق بذلك المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص542–543، تحت عنوان «حكمة تقديم ﴿في أم الكتاب لدينا﴾ على الخبر»","url":""}]},{"id":"s43-11","number":11,"surah":43,"verses":[1,2,3,4],"references":[{"surah":43,"verses":[1,2,3,4]}],"verseLabel":"الزخرف: 1–4","question":"لماذا أقسم الله في مطلع السورة بـ﴿الْكِتَابِ الْمُبِينِ﴾؟","answer":"لأن القرآن نفسه آية التحدي وموضع إنكار المكذبين؛ فجاء القسم به تنويهًا بعظمته ووضوح دلالته، وتناسب المقسم به مع القضية التي يثبتها القسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص533–534، تحت عنوان «بلاغة التناسب في القسم»","url":""}]},{"id":"s43-12","number":12,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"ما الصورة التي يرسمها قوله: ﴿أَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ﴾؟","answer":"يصور إبعاد الذكر عنهم بصورة طرد الإبل الغريبة عن الحوض ومنعها منه؛ فتجعل الصورة حرمانهم من الوحي عقوبة مهولة بعد أن كان باب الهداية مفتوحًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص551، تحت عنوان «جمال الاستعارة التمثيلية في ﴿أفنضرب عنكم الذكر﴾»","url":""}]},{"id":"s43-166","number":166,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"لماذا قيل: ﴿أَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ صَفْحًا﴾؟","answer":"لأن الصفح مأخوذ من صفحة الوجه، فيصور الإعراض عنهم بترك الالتفات إليهم؛ وهو أشد من مجرد ترك الكلام، إذ يجمع الإهمال والحرمان من التذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص552–553، تحت عنوان «دلالة التعبير بالصفح في ﴿أفنضرب عنكم الذكر صفحًا﴾»","url":""}]},{"id":"s43-13","number":13,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"كيف يكشف قوله: ﴿إِنْ كُنْتُمْ قَوْمًا مُسْرِفِينَ﴾ أن إسرافهم لم يكن عذرًا لترك تذكيرهم؟","answer":"جاء إسرافهم في صورة الشرط مع أنه واقع؛ ليوبخهم على حال كان ينبغي ألا تقع، وينكر أن يصبح تماديهم في الباطل سببًا لقطع الوحي عنهم قبل إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص554–555، تحت عنوان «نكتة التقييد بـ (إن) على قراءة كسر همزتها»","url":""}]},{"id":"s43-14","number":14,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"لماذا لم يمنع إسراف المخاطبين استمرار تذكيرهم بالقرآن؟","answer":"لأن الله أنزل الكتاب رحمةً ونصحًا ليبين لهم طريق الحق؛ فلا يقطع عنهم التذكير بسبب عنادهم، بل يمهلهم للرجوع ويقيم عليهم الحجة إن أصروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص548–549، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s43-15","number":15,"surah":43,"verses":[6,7,8],"references":[{"surah":43,"verses":[6,7,8]}],"verseLabel":"الزخرف: 6–8","question":"ما دلالة تدرج سنة المكذبين من كثرة إرسال الأنبياء إلى الاستهزاء بهم ثم إهلاك أمم أشد بطشًا؟","answer":"تقرر الآيات تكرر إرسال الرسل واستهزاء المكذبين بهم، ثم تذكر هلاك أمم كانت أشد قوة من المخاطبين. ففيها تسلية للنبي ﷺ وتحذير لقومه؛ إذ لا تمنع القوة عقوبة التكذيب، وإهلاك الأقوى ينذر الأضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص558–559، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s43-16","number":16,"surah":43,"verses":[6,7,8],"references":[{"surah":43,"verses":[6,7,8]}],"verseLabel":"الزخرف: 6–8","question":"لماذا وُصفت الأمم السابقة بـ﴿الْأَوَّلِينَ﴾؟","answer":"ليستحضر اللفظ رسل الله وأممهم السابقين بوصفهم أصولًا في التاريخ البشري، ويقرر أن اعتراض المكذبين الحاليين امتداد لطريق قديم انتهى بأهله إلى الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص562، تحت عنوان «معنى (الـ) في ﴿الأولين﴾، ودلالة التعبير به»","url":""}]},{"id":"s43-167","number":167,"surah":43,"verses":[6,7,8],"references":[{"surah":43,"verses":[6,7,8]}],"verseLabel":"الزخرف: 6–8","question":"لماذا أُعيد لفظ ﴿الْأَوَّلِينَ﴾ ظاهرًا في قوله: ﴿وَمَضَى مَثَلُ الْأَوَّلِينَ﴾؟","answer":"لزيادة التقرير وربط مصير المكذبين مباشرة بمن سبقهم؛ فالإظهار يزيل احتمال عود الضمير إلى غيرهم، ويجعل سنتهم الماضية حاضرة في السمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص571، تحت عنوان «دلالة الإظهار في جملة ﴿ومضى مثل الأولين﴾»","url":""}]},{"id":"s43-17","number":17,"surah":43,"verses":[9],"references":[{"surah":43,"verses":[9]}],"verseLabel":"الزخرف: 9","question":"ما مناسبة وصف خالق السماوات والأرض بـ﴿العزيز العليم﴾؟","answer":"خلق السماوات والأرض بهذا الإحكام يدل على عزة لا تعجزها المخلوقات، وعلم محيط بتفاصيلها. وهذه صفات لا تتصف بها الأصنام، فذكرها يحتج على بطلان إشراك العاجز بمن خلق وأحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص578–579، تحت عنوان «دلالة تخصيص صفتي ﴿العزيز العليم﴾»","url":""}]},{"id":"s43-18","number":18,"surah":43,"verses":[9],"references":[{"surah":43,"verses":[9]}],"verseLabel":"الزخرف: 9","question":"هل نطق المشركون فعلًا بقولهم: ﴿خَلَقَهُنَّ الْعَزِيزُ الْعَلِيمُ﴾؟","answer":"جمهور المفسرين على أن أصل جوابهم كان: خلقهن الله، ثم حكى القرآن لازم اعترافهم ووصف الخالق بما يليق به؛ فحُذف قولهم المقدر وأقيم البيان الإلهي مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص579–580، تحت عنوان «دلالة الحذف في ﴿خلقهن العزيز العليم﴾»","url":""}]},{"id":"s43-19","number":19,"surah":43,"verses":[10],"references":[{"surah":43,"verses":[10]}],"verseLabel":"الزخرف: 10","question":"ما سر تشبيه الأرض بالمهد في قوله ﴿جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا﴾؟","answer":"تشبيه الأرض بالمهد يستحضر ما يهيأ للوليد من راحة واستقرار. فكما هيئ المهد للطفل، هيأ الله الأرض لمعيشة الناس بما فيها من أسباب الانتفاع، وفي الصورة تذكير بعنايته وحث على شكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص582–583، تحت عنوان «بلاغة التشبيه في ﴿جعل لكم الأرض مهدًا﴾»","url":""}]},{"id":"s43-20","number":20,"surah":43,"verses":[10],"references":[{"surah":43,"verses":[10]}],"verseLabel":"الزخرف: 10","question":"لماذا قيل: ﴿وَجَعَلَ لَكُمْ فِيهَا سُبُلًا﴾ بالجمع؟","answer":"لأن تعدد السبل يبرز كثرة الطرق الممتدة في الأرض وتنوع المقاصد التي تبلغها؛ وهي نعمة تيسر التنقل والتعارف وجلب المنافع ودفع الأضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص584–585، تحت عنوان «دلالة التعبير بـ﴿سبلًا﴾»","url":""}]},{"id":"s43-21","number":21,"surah":43,"verses":[9,10],"references":[{"surah":43,"verses":[9,10]}],"verseLabel":"الزخرف: 9–10","question":"لماذا عُرّف الخالق بقوله: ﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا﴾؟","answer":"لأن الموصول يستدعي أفعالًا يعرفها المخاطبون ويلفتهم إلى آثار عزة الله وعلمه في حياتهم؛ فمن مهّد لهم الأرض وشق فيها السبل هو المستحق وحده للشكر والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص580–581، تحت عنوان «وجه التعبير بالموصول ﴿الذي﴾»","url":""}]}]);
